CREATE OR REPLACE FUNCTION public.create_admin_notifications_rpc(p_title text, p_message text, p_type text, p_reference_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(admin_id uuid, notification_id uuid, notification_title text, notification_message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_title TEXT;
  v_message TEXT;
  v_tracking_number TEXT;
  v_sender_name TEXT;
  v_rating INTEGER;
  v_feedback_message TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_type = 'order_update' THEN
    SELECT o.tracking_number, o.sender_name
      INTO v_tracking_number, v_sender_name
      FROM public.orders AS o
     WHERE o.id = p_reference_id
       AND o.user_id = auth.uid();

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Notification reference is not owned by the caller';
    END IF;

    v_title := 'New Booking';
    v_message := format(
      'New order %s from %s',
      v_tracking_number,
      COALESCE(NULLIF(btrim(v_sender_name), ''), 'Customer')
    );
  ELSIF p_type = 'feedback' THEN
    SELECT f.rating, f.message
      INTO v_rating, v_feedback_message
      FROM public.customer_feedback AS f
      JOIN public.orders AS o ON o.id = f.order_id
     WHERE f.order_id = p_reference_id
       AND f.customer_id = auth.uid()
       AND o.user_id = auth.uid()
       AND o.status = 'Delivered';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Notification reference is not an owned delivered-order feedback';
    END IF;

    v_title := 'New Customer Feedback';
    v_message := format(
      '%s? rating%s',
      v_rating,
      CASE
        WHEN NULLIF(btrim(v_feedback_message), '') IS NULL THEN ''
        ELSE ': ' || left(btrim(v_feedback_message), 60)
      END
    );
  ELSE
    RAISE EXCEPTION 'Unsupported customer notification event';
  END IF;

  -- One notification fan-out per event key. The advisory lock closes the
  -- race where two browser callbacks arrive in the same millisecond.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(p_type || ':' || COALESCE(p_reference_id::TEXT, ''), 0)
  );
  IF EXISTS (
    SELECT 1
      FROM public.notifications AS n
     WHERE n.type = p_type
       AND n.reference_id = p_reference_id
       AND n.created_at > now() - INTERVAL '10 minutes'
  ) THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH inserted AS (
    INSERT INTO public.notifications (user_id, title, message, type, reference_id)
    SELECT p.id, v_title, v_message, p_type, p_reference_id
      FROM public.profiles AS p
     WHERE p.role = 'admin'
    RETURNING id, user_id
  )
  SELECT user_id, id, v_title, v_message FROM inserted;
END;
$function$;
CREATE OR REPLACE FUNCTION public.set_photo_storage_mode(p_upload_mode text, p_reason text DEFAULT NULL::text, p_force_firebase_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(upload_mode text, force_firebase_expires_at timestamp with time zone, updated_at timestamp with time zone, updated_by uuid, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_previous_mode TEXT;
  v_settings public.photo_storage_settings%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_upload_mode NOT IN ('automatic', 'force_firebase') THEN
    RAISE EXCEPTION 'Invalid upload mode' USING ERRCODE = '22023';
  END IF;
  IF char_length(COALESCE(p_reason, '')) > 500 THEN
    RAISE EXCEPTION 'Reason is too long' USING ERRCODE = '22001';
  END IF;
  IF p_upload_mode = 'force_firebase' THEN
    IF p_force_firebase_expires_at IS NULL
       OR p_force_firebase_expires_at <= now()
       OR p_force_firebase_expires_at > now() + INTERVAL '24 hours' THEN
      RAISE EXCEPTION 'Force Firebase expiry must be within the next 24 hours' USING ERRCODE = '22023';
    END IF;
  ELSE
    p_force_firebase_expires_at := NULL;
  END IF;

  SELECT pss.upload_mode INTO v_previous_mode
    FROM public.photo_storage_settings pss WHERE pss.id = TRUE FOR UPDATE;

  UPDATE public.photo_storage_settings
     SET upload_mode = p_upload_mode,
         force_firebase_expires_at = p_force_firebase_expires_at,
         reason = NULLIF(btrim(p_reason), ''),
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = TRUE
   RETURNING * INTO v_settings;

  INSERT INTO public.photo_storage_events (event_type, provider, outcome, message, metadata, created_by) VALUES (
    'mode_change', 'system', 'success',
    CASE WHEN p_upload_mode = 'force_firebase'
      THEN 'New evidence uploads are routed directly to Firebase fallback.'
      ELSE 'New evidence uploads use Supabase first with Firebase fallback.'
    END,
    jsonb_build_object(
      'previous_mode', COALESCE(v_previous_mode, 'automatic'),
      'upload_mode', p_upload_mode,
      'force_firebase_expires_at', p_force_firebase_expires_at,
      'reason', NULLIF(btrim(p_reason), '')
    ),
    auth.uid()
  );

  RETURN QUERY
  SELECT v_settings.upload_mode, v_settings.force_firebase_expires_at,
         v_settings.updated_at, v_settings.updated_by, v_settings.reason;
END;
$function$;
CREATE OR REPLACE FUNCTION private.enqueue_notification_delivery_jobs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_inserted INTEGER := 0;
BEGIN
  INSERT INTO public.notification_delivery_jobs (
    notification_id,
    user_id,
    device_token_id,
    dedupe_key
  )
  SELECT
    NEW.id,
    NEW.user_id,
    d.id,
    NEW.id::TEXT || ':' || d.id::TEXT
  FROM public.user_device_tokens AS d
  WHERE d.user_id = NEW.user_id
  ON CONFLICT (dedupe_key) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- A terminal placeholder makes "not delivered because the account has no
  -- registered device" observable without keeping a pointless retry alive.
  IF v_inserted = 0 THEN
    INSERT INTO public.notification_delivery_jobs (
      notification_id,
      user_id,
      device_token_id,
      dedupe_key,
      status,
      completed_at,
      last_error
    ) VALUES (
      NEW.id,
      NEW.user_id,
      NULL,
      NEW.id::TEXT || ':none',
      'skipped',
      now(),
      'No device tokens for user'
    ) ON CONFLICT (dedupe_key) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_new_trip_customers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  SELECT
    p.id,
    'New Trip Available',
    format(
      '%s → %s is scheduled for %s. Tap to view the trip and book cargo space.',
      NEW.origin,
      NEW.destination,
      to_char(NEW.departure_date AT TIME ZONE 'Asia/Manila', 'FMMonth FMDD, YYYY')
    ),
    'trip_update',
    NEW.id
  FROM public.profiles AS p
  WHERE p.role = 'customer'
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.list_orphaned_evidence_photos()
 RETURNS TABLE(name text, folder text, tracking_number text, size_bytes bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    o.name,
    (storage.foldername(o.name))[1],
    (storage.foldername(o.name))[2],
    CASE WHEN o.metadata ->> 'size' ~ '^[0-9]+$' THEN (o.metadata ->> 'size')::BIGINT ELSE 0 END
  FROM storage.objects o
  WHERE o.bucket_id = 'cargo-photos'
    AND (storage.foldername(o.name))[1] IN ('pickup-proofs', 'delivery-proofs', 'receipts')
    AND (storage.foldername(o.name))[2] IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.orders ord
      WHERE ord.tracking_number = (storage.foldername(o.name))[2]
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_contact_inquiry_resolve_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'resolved' AND OLD.status IS DISTINCT FROM 'resolved' THEN
    IF NEW.assigned_admin_id IS NULL THEN
      RAISE EXCEPTION 'Claim this inquiry before marking it resolved.' USING ERRCODE = '42501';
    ELSIF NEW.assigned_admin_id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION 'Only the admin who claimed this inquiry can mark it resolved.' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_notification_delivery_jobs(p_limit integer DEFAULT 25)
 RETURNS TABLE(job_id uuid, notification_id uuid, user_id uuid, device_token_id uuid, job_claim_id uuid, job_attempt_count integer)
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  WITH candidate AS (
    SELECT j.id
    FROM public.notification_delivery_jobs AS j
    WHERE (
        (j.status IN ('pending', 'retry') AND j.available_at <= now())
        OR (j.status = 'processing' AND j.claimed_at < now() - INTERVAL '5 minutes')
      )
      AND j.device_token_id IS NOT NULL
    ORDER BY j.available_at, j.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 25), 1), 100)
  ), claimed AS (
    UPDATE public.notification_delivery_jobs AS j
       SET status = 'processing',
           attempt_count = j.attempt_count + 1,
           claimed_at = now(),
           claim_id = gen_random_uuid(),
           updated_at = now(),
           last_error = NULL
      FROM candidate AS c
     WHERE j.id = c.id
    RETURNING
      j.id,
      j.notification_id,
      j.user_id,
      j.device_token_id,
      j.claim_id,
      j.attempt_count
  )
  SELECT
    c.id,
    c.notification_id,
    c.user_id,
    c.device_token_id,
    c.claim_id,
    c.attempt_count
  FROM claimed AS c;
$function$;
CREATE OR REPLACE FUNCTION public.guard_trip_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count INT;
  v_unsettled TEXT;
  v_eligible_count INT;
  v_eligible_weight NUMERIC;
  v_pending_cancellation_count INT;
  v_not_picked_up_count INT;
  v_scheduled_day DATE;
  v_today DATE;
  v_departure_at TIMESTAMPTZ;
  v_starting BOOLEAN;
  v_arriving BOOLEAN;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.departure_at IS NOT NULL
       OR NEW.estimated_arrival_at IS NOT NULL
       OR NEW.arrived_at IS NOT NULL THEN
      RAISE EXCEPTION 'Trip timestamps are recorded by the server during trip status transitions.';
    END IF;
    RETURN NEW;
  END IF;

  v_starting := OLD.status = 'scheduled' AND NEW.status = 'in_progress';
  v_arriving := OLD.status = 'in_progress' AND NEW.status = 'arrived';

  IF NEW.status = 'in_progress' AND OLD.status IS DISTINCT FROM 'in_progress' AND NOT v_starting THEN
    RAISE EXCEPTION 'Only a scheduled trip can be started.';
  END IF;

  IF NOT v_starting AND NEW.departure_at IS DISTINCT FROM OLD.departure_at THEN
    RAISE EXCEPTION 'Actual departure is set only when a scheduled trip starts.';
  END IF;
  IF NOT v_starting AND NEW.estimated_arrival_at IS DISTINCT FROM OLD.estimated_arrival_at THEN
    RAISE EXCEPTION 'Estimated arrival can only be provided when the trip starts.';
  END IF;
  IF NOT v_arriving AND NEW.arrived_at IS DISTINCT FROM OLD.arrived_at THEN
    RAISE EXCEPTION 'Actual arrival is set only when the trip is confirmed at the destination hub.';
  END IF;

  IF v_starting THEN
    IF NEW.departure_date IS NULL THEN
      RAISE EXCEPTION 'A departure date is required before starting the trip.';
    END IF;

    v_scheduled_day := (NEW.departure_date AT TIME ZONE 'Asia/Manila')::DATE;
    v_today := (clock_timestamp() AT TIME ZONE 'Asia/Manila')::DATE;
    IF v_today < v_scheduled_day THEN
      RAISE EXCEPTION 'This trip is scheduled to depart on %. To depart earlier, reschedule it first.',
        to_char(v_scheduled_day, 'FMMonth FMDD, YYYY');
    ELSIF v_today > v_scheduled_day THEN
      RAISE EXCEPTION 'Overdue — Reschedule Required. Update the departure date before starting.';
    END IF;

    SELECT COUNT(*) INTO v_pending_cancellation_count
      FROM (SELECT 1 FROM public.orders WHERE trip_id = NEW.id AND status = 'Pending Cancellation' FOR SHARE) q;

    IF v_pending_cancellation_count > 0 THEN
      RAISE EXCEPTION 'Cannot start trip: % order(s) awaiting cancellation decision.', v_pending_cancellation_count;
    END IF;

    SELECT COUNT(*) INTO v_not_picked_up_count
      FROM (SELECT 1 FROM public.orders WHERE trip_id = NEW.id AND status IN ('Pending', 'Assigned') FOR SHARE) q;

    IF v_not_picked_up_count > 0 THEN
      RAISE EXCEPTION 'Cannot start trip: % order(s) not yet picked up.', v_not_picked_up_count;
    END IF;

    SELECT COUNT(*), COALESCE(SUM(actual_weight), 0)
      INTO v_eligible_count, v_eligible_weight
      FROM (
        SELECT actual_weight
          FROM public.orders
         WHERE trip_id = NEW.id
           AND status NOT IN ('Cancelled', 'Pending Cancellation', 'Pending', 'Assigned')
           FOR SHARE
      ) locked_orders;

    IF v_eligible_count = 0 THEN
      RAISE EXCEPTION 'Cannot start trip: no active shipments are ready for departure.';
    END IF;

    IF v_eligible_weight <= 0 THEN
      RAISE EXCEPTION 'Cannot start trip: record pickup and actual cargo weight first.';
    END IF;

    v_departure_at := clock_timestamp();
    IF NEW.estimated_arrival_at IS NOT NULL AND NEW.estimated_arrival_at <= v_departure_at THEN
      RAISE EXCEPTION 'Estimated arrival at the destination hub must be later than actual departure.';
    END IF;

    -- Never trust a timestamp supplied for actual departure by the caller.
    NEW.departure_at := v_departure_at;
  END IF;

  IF v_arriving THEN
    -- Do not invent a historical departure for legacy in-progress trips that
    -- have none. Mark Arrived still records the actual arrival at this moment.
    NEW.arrived_at := clock_timestamp();
  END IF;

  IF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed' THEN
    SELECT COUNT(*)
      INTO v_count
      FROM public.orders
     WHERE trip_id = NEW.id
       AND status <> 'Cancelled'
       AND COALESCE(remaining_balance, 0) > 0;

    IF v_count > 0 THEN
      SELECT STRING_AGG(tracking_number, ', ')
        INTO v_unsettled
        FROM (
          SELECT tracking_number
            FROM public.orders
           WHERE trip_id = NEW.id
             AND status <> 'Cancelled'
             AND COALESCE(remaining_balance, 0) > 0
           ORDER BY tracking_number
           LIMIT 5
        ) t;

      IF v_count > 5 THEN
        v_unsettled := v_unsettled || ' …';
      END IF;

      RAISE EXCEPTION
        'Cannot complete trip % — % order(s) still have an unpaid balance: %',
        NEW.trip_number,
        v_count,
        v_unsettled;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_trips_load(trip_ids uuid[])
 RETURNS TABLE(trip_id uuid, current_weight numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    o.trip_id,
    COALESCE(SUM(o.actual_weight), 0) AS current_weight
  FROM public.orders o
  WHERE o.trip_id = ANY(trip_ids)
    AND o.status NOT IN ('Cancelled', 'Pending Cancellation', 'Pending', 'Assigned')
  GROUP BY o.trip_id;
$function$;
CREATE OR REPLACE FUNCTION public.get_expired_evidence_orders(p_cutoff timestamp with time zone)
 RETURNS TABLE(order_id uuid, tracking_number text, status text, terminal_status_at timestamp with time zone, pickup_photos jsonb, delivery_photos jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT o.id, o.tracking_number, o.status, s.terminal_status_at, o.pickup_photos, o.delivery_photos
  FROM public.orders o
  JOIN LATERAL (
    SELECT max(e.changed_at) AS terminal_status_at
    FROM public.order_status_events e
    WHERE e.order_id = o.id AND e.status = o.status
  ) s ON TRUE
  WHERE o.status IN ('Delivered', 'Cancelled')
    AND COALESCE(o.featured_on_website, FALSE) = FALSE
    AND s.terminal_status_at IS NOT NULL
    AND s.terminal_status_at < p_cutoff
    AND (
      COALESCE(o.pickup_photos, '[]'::jsonb) <> '[]'::jsonb
      OR COALESCE(o.delivery_photos, '[]'::jsonb) <> '[]'::jsonb
    );
$function$;
CREATE OR REPLACE FUNCTION public.get_photo_storage_live_usage()
 RETURNS TABLE(total_size_bytes bigint, object_count bigint, buckets jsonb, measured_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH bucket_usage AS (
    SELECT
      o.bucket_id,
      count(*)::BIGINT AS object_count,
      COALESCE(sum(
        CASE
          WHEN o.metadata ->> 'size' ~ '^[0-9]+$'
            THEN (o.metadata ->> 'size')::BIGINT
          ELSE 0
        END
      ), 0)::BIGINT AS size_bytes
    FROM storage.objects o
    GROUP BY o.bucket_id
  )
  SELECT
    COALESCE(sum(bu.size_bytes), 0)::BIGINT,
    COALESCE(sum(bu.object_count), 0)::BIGINT,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'bucket_id', bu.bucket_id,
          'size_bytes', bu.size_bytes,
          'object_count', bu.object_count
        ) ORDER BY bu.size_bytes DESC, bu.bucket_id
      ),
      '[]'::JSONB
    ),
    now()
  FROM bucket_usage bu;
END;
$function$;
CREATE OR REPLACE FUNCTION public.effective_trip_price(p_trip_id uuid)
 RETURNS numeric
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT NULLIF(price_per_kg, 0) FROM public.trips WHERE id = p_trip_id),
    public.global_price_per_kilo()
  );
$function$;
CREATE OR REPLACE FUNCTION public.claim_notification_delivery_job(p_notification_id uuid, p_device_token_id uuid)
 RETURNS TABLE(job_id uuid, job_claim_id uuid, job_attempt_count integer)
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  WITH candidate AS (
    SELECT j.id
    FROM public.notification_delivery_jobs AS j
    WHERE j.notification_id = p_notification_id
      AND j.device_token_id = p_device_token_id
      AND (
        (j.status IN ('pending', 'retry') AND j.available_at <= now())
        OR (j.status = 'processing' AND j.claimed_at < now() - INTERVAL '5 minutes')
      )
    FOR UPDATE SKIP LOCKED
    LIMIT 1
  ), claimed AS (
    UPDATE public.notification_delivery_jobs AS j
       SET status = 'processing',
           attempt_count = j.attempt_count + 1,
           claimed_at = now(),
           claim_id = gen_random_uuid(),
           updated_at = now(),
           last_error = NULL
      FROM candidate AS c
     WHERE j.id = c.id
    RETURNING j.id, j.claim_id, j.attempt_count
  )
  SELECT c.id, c.claim_id, c.attempt_count FROM claimed AS c;
$function$;
CREATE OR REPLACE FUNCTION public.queue_expired_evidence_cleanup(p_order_ids uuid[], p_items jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_count INTEGER := 0;
  v_item JSONB;
  v_provider TEXT;
  v_path TEXT;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Service access required' USING ERRCODE = '42501';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'Cleanup items must be an array' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_provider := v_item ->> 'provider';
    v_path := v_item ->> 'storage_path';
    IF v_provider = 'supabase' AND v_path ~ '^(pickup-proofs|delivery-proofs)/[^/]+/.+' THEN
      NULL;
    ELSIF v_provider = 'firebase' AND v_path ~ '^photoFallbacks/[^/]+$' THEN
      NULL;
    ELSE
      RAISE EXCEPTION 'Invalid cleanup item' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.photo_cleanup_queue (provider, storage_path)
    VALUES (v_provider, v_path)
    ON CONFLICT (provider, storage_path) DO UPDATE
      SET queued_at = now(), completed_at = NULL, attempts = 0, last_error = NULL;
  END LOOP;

  IF COALESCE(cardinality(p_order_ids), 0) > 0 THEN
    UPDATE public.orders
    SET pickup_photos = '[]'::JSONB,
        delivery_photos = '[]'::JSONB
    WHERE id = ANY(p_order_ids);
    GET DIAGNOSTICS v_order_count = ROW_COUNT;
    IF v_order_count <> cardinality(p_order_ids) THEN
      RAISE EXCEPTION 'Not every cleanup order could be updated' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN v_order_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_photo_cleanup_queue_result(p_ids bigint[], p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Service access required' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(cardinality(p_ids), 0) = 0 THEN
    RETURN;
  END IF;

  UPDATE public.photo_cleanup_queue
  SET attempts = attempts + 1,
      completed_at = CASE WHEN p_error IS NULL THEN now() ELSE NULL END,
      last_error = CASE WHEN p_error IS NULL THEN NULL ELSE left(p_error, 500) END
  WHERE id = ANY(p_ids);
END;
$function$;
CREATE OR REPLACE FUNCTION public.trigger_scheduled_old_photo_cleanup()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'vault'
AS $function$
DECLARE
  v_project_url text;
  v_service_key text;
BEGIN
  SELECT decrypted_secret INTO v_project_url FROM vault.decrypted_secrets WHERE name = 'project_url';
  SELECT decrypted_secret INTO v_service_key FROM vault.decrypted_secrets WHERE name = 'service_role_key';

  IF v_project_url IS NULL OR v_service_key IS NULL THEN
    RAISE WARNING 'Scheduled old-photo cleanup skipped because its server credentials are not configured.';
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := v_project_url || '/functions/v1/archive-expired-evidence-photos',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := '{}'::jsonb
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_cancellation_settlement_decision(p_order_id uuid, p_decision_type text, p_agreed_retained_amount numeric, p_customer_agreement_confirmed boolean, p_internal_notes text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_existing_history public.cancellation_settlement_history%ROWTYPE;
  v_decision public.cancellation_settlements%ROWTYPE;
  v_admin_id UUID := auth.uid();
  v_admin_name TEXT;
  v_type TEXT := LOWER(BTRIM(COALESCE(p_decision_type, '')));
  v_fee NUMERIC(10,2) := ROUND(COALESCE(p_agreed_retained_amount, 0), 2);
  v_notes TEXT := NULLIF(BTRIM(p_internal_notes), '');
  v_gross NUMERIC(10,2);
  v_succeeded NUMERIC(10,2);
  v_pending NUMERIC(10,2);
  v_final_charge NUMERIC(10,2);
BEGIN
  IF v_admin_id IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_order_id IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'Order and idempotency key are required' USING ERRCODE = '22023';
  END IF;
  IF v_type NOT IN ('full_refund', 'retained_fee') THEN
    RAISE EXCEPTION 'Decision must be full_refund or retained_fee' USING ERRCODE = '22023';
  END IF;
  IF v_notes IS NOT NULL AND char_length(v_notes) > 1000 THEN
    RAISE EXCEPTION 'Internal notes must be 1000 characters or fewer' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found' USING ERRCODE = 'P0002'; END IF;
  IF v_order.status <> 'Cancelled' THEN
    RAISE EXCEPTION 'Only a cancelled booking can receive a cancellation settlement decision'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing_history
  FROM public.cancellation_settlement_history
  WHERE idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing_history.order_id <> p_order_id
       OR v_existing_history.action <> 'recorded'
       OR v_existing_history.new_decision->>'decision_type' <> v_type
       OR (v_existing_history.new_decision->>'agreed_retained_amount')::numeric <> v_fee THEN
      RAISE EXCEPTION 'Idempotency key was already used for another settlement action'
        USING ERRCODE = '23505';
    END IF;
    RETURN public.get_cancellation_settlement_summary(p_order_id);
  END IF;

  IF EXISTS (SELECT 1 FROM public.cancellation_settlements WHERE order_id = p_order_id) THEN
    RAISE EXCEPTION 'A settlement decision already exists; use the explicit amendment action'
      USING ERRCODE = '23505';
  END IF;

  IF v_type = 'full_refund' THEN
    IF v_fee <> 0 OR COALESCE(p_customer_agreement_confirmed, FALSE) THEN
      RAISE EXCEPTION 'A full-refund decision must retain zero and does not record a fee agreement'
        USING ERRCODE = '22023';
    END IF;
  ELSIF v_fee <= 0 OR NOT COALESCE(p_customer_agreement_confirmed, FALSE) THEN
    RAISE EXCEPTION 'A retained fee must be positive and the admin must confirm the customer agreement'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_gross
  FROM public.payment_transactions
  WHERE order_id = p_order_id AND payment_status IN ('paid', 'partial');
  SELECT
    COALESCE(SUM(amount) FILTER (WHERE status = 'succeeded'), 0),
    COALESCE(SUM(amount) FILTER (
      WHERE status IN ('creating', 'pending', 'processing')
         OR (COALESCE(outcome_uncertain, FALSE) AND status NOT IN ('succeeded', 'failed'))
    ), 0)
  INTO v_succeeded, v_pending
  FROM public.payment_refunds WHERE order_id = p_order_id;
  v_final_charge := public.order_payable_amount(v_order.shipping_cost, v_order.discount_amount);

  IF v_succeeded > v_gross + 0.005 OR v_succeeded + v_pending > v_gross + 0.005 THEN
    RAISE EXCEPTION 'Existing payment/refund records need reconciliation before a decision can be recorded'
      USING ERRCODE = '22023';
  END IF;
  IF v_fee > LEAST(v_gross, v_final_charge) + 0.005 THEN
    RAISE EXCEPTION 'Agreed fee exceeds retained collections or the historical final charge'
      USING ERRCODE = '22023';
  END IF;
  IF v_succeeded + v_pending + v_fee > v_gross + 0.005 THEN
    RAISE EXCEPTION 'Successful refunds, active refunds, and agreed fee exceed successful collections'
      USING ERRCODE = '22023';
  END IF;

  SELECT name INTO v_admin_name FROM public.profiles WHERE id = v_admin_id AND role = 'admin';

  INSERT INTO public.cancellation_settlements (
    order_id, decision_type, agreed_retained_amount,
    customer_agreement_confirmed, customer_agreement_confirmed_at,
    internal_notes, decided_by, decided_at, updated_at, version, last_idempotency_key
  ) VALUES (
    p_order_id, v_type, v_fee,
    COALESCE(p_customer_agreement_confirmed, FALSE),
    CASE WHEN v_type = 'retained_fee' THEN NOW() ELSE NULL END,
    v_notes, v_admin_id, NOW(), NOW(), 1, p_idempotency_key
  ) RETURNING * INTO v_decision;

  INSERT INTO public.cancellation_settlement_history (
    order_id, tracking_number, action, old_decision, new_decision,
    changed_by, changed_by_name, idempotency_key
  ) VALUES (
    p_order_id, v_order.tracking_number, 'recorded', NULL, to_jsonb(v_decision),
    v_admin_id, COALESCE(v_admin_name, 'Unknown Admin'), p_idempotency_key
  );

  INSERT INTO public.activity_logs (
    admin_id, admin_name, module, action, record_type, record_id, record_ref,
    previous_value, new_value, details
  ) VALUES (
    v_admin_id, COALESCE(v_admin_name, 'Unknown Admin'), 'Payments',
    'Cancellation Settlement Recorded', 'order', p_order_id, v_order.tracking_number,
    NULL,
    jsonb_build_object('decision_type', v_type, 'agreed_retained_amount', v_fee),
    'Recorded a cancellation financial decision. This action did not send money or create a payment/refund.'
  );

  RETURN public.get_cancellation_settlement_summary(p_order_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.amend_cancellation_settlement_decision(p_order_id uuid, p_decision_type text, p_agreed_retained_amount numeric, p_customer_agreement_confirmed boolean, p_internal_notes text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_old public.cancellation_settlements%ROWTYPE;
  v_new public.cancellation_settlements%ROWTYPE;
  v_existing_history public.cancellation_settlement_history%ROWTYPE;
  v_admin_id UUID := auth.uid();
  v_admin_name TEXT;
  v_type TEXT := LOWER(BTRIM(COALESCE(p_decision_type, '')));
  v_fee NUMERIC(10,2) := ROUND(COALESCE(p_agreed_retained_amount, 0), 2);
  v_notes TEXT := NULLIF(BTRIM(p_internal_notes), '');
  v_gross NUMERIC(10,2);
  v_succeeded NUMERIC(10,2);
  v_pending NUMERIC(10,2);
  v_final_charge NUMERIC(10,2);
BEGIN
  IF v_admin_id IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_order_id IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION 'Order and idempotency key are required' USING ERRCODE = '22023';
  END IF;
  IF v_type NOT IN ('full_refund', 'retained_fee') THEN
    RAISE EXCEPTION 'Decision must be full_refund or retained_fee' USING ERRCODE = '22023';
  END IF;
  IF v_notes IS NOT NULL AND char_length(v_notes) > 1000 THEN
    RAISE EXCEPTION 'Internal notes must be 1000 characters or fewer' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found' USING ERRCODE = 'P0002'; END IF;
  IF v_order.status <> 'Cancelled' THEN
    RAISE EXCEPTION 'Only a cancelled booking can have a settlement decision amended'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing_history
  FROM public.cancellation_settlement_history
  WHERE idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing_history.order_id <> p_order_id OR v_existing_history.action <> 'amended' THEN
      RAISE EXCEPTION 'Idempotency key was already used for another settlement action'
        USING ERRCODE = '23505';
    END IF;
    RETURN public.get_cancellation_settlement_summary(p_order_id);
  END IF;

  SELECT * INTO v_old FROM public.cancellation_settlements
  WHERE order_id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No settlement decision exists; use the record action first'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT
    COALESCE(SUM(amount) FILTER (WHERE status = 'succeeded'), 0),
    COALESCE(SUM(amount) FILTER (
      WHERE status IN ('creating', 'pending', 'processing')
         OR (COALESCE(outcome_uncertain, FALSE) AND status NOT IN ('succeeded', 'failed'))
    ), 0)
  INTO v_succeeded, v_pending
  FROM public.payment_refunds WHERE order_id = p_order_id;
  IF v_pending > 0.005 THEN
    RAISE EXCEPTION 'Settlement decisions cannot be amended while a refund is pending or awaiting confirmation'
      USING ERRCODE = '55000';
  END IF;

  IF v_type = 'full_refund' THEN
    IF v_fee <> 0 OR COALESCE(p_customer_agreement_confirmed, FALSE) THEN
      RAISE EXCEPTION 'A full-refund decision must retain zero and does not record a fee agreement'
        USING ERRCODE = '22023';
    END IF;
  ELSIF v_fee <= 0 OR NOT COALESCE(p_customer_agreement_confirmed, FALSE) THEN
    RAISE EXCEPTION 'A retained fee must be positive and the admin must confirm the customer agreement'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_gross
  FROM public.payment_transactions
  WHERE order_id = p_order_id AND payment_status IN ('paid', 'partial');
  v_final_charge := public.order_payable_amount(v_order.shipping_cost, v_order.discount_amount);
  IF v_succeeded > v_gross + 0.005
     OR v_fee > LEAST(v_gross, v_final_charge) + 0.005
     OR v_succeeded + v_fee > v_gross + 0.005 THEN
    RAISE EXCEPTION 'Amended decision conflicts with successful collections/refunds'
      USING ERRCODE = '22023';
  END IF;

  SELECT name INTO v_admin_name FROM public.profiles WHERE id = v_admin_id AND role = 'admin';
  UPDATE public.cancellation_settlements
  SET decision_type = v_type,
      agreed_retained_amount = v_fee,
      customer_agreement_confirmed = COALESCE(p_customer_agreement_confirmed, FALSE),
      customer_agreement_confirmed_at = CASE WHEN v_type = 'retained_fee' THEN NOW() ELSE NULL END,
      internal_notes = v_notes,
      decided_by = v_admin_id,
      decided_at = NOW(),
      updated_at = NOW(),
      version = version + 1,
      last_idempotency_key = p_idempotency_key
  WHERE order_id = p_order_id
  RETURNING * INTO v_new;

  INSERT INTO public.cancellation_settlement_history (
    order_id, tracking_number, action, old_decision, new_decision,
    changed_by, changed_by_name, idempotency_key
  ) VALUES (
    p_order_id, v_order.tracking_number, 'amended', to_jsonb(v_old), to_jsonb(v_new),
    v_admin_id, COALESCE(v_admin_name, 'Unknown Admin'), p_idempotency_key
  );

  INSERT INTO public.activity_logs (
    admin_id, admin_name, module, action, record_type, record_id, record_ref,
    previous_value, new_value, details
  ) VALUES (
    v_admin_id, COALESCE(v_admin_name, 'Unknown Admin'), 'Payments',
    'Cancellation Settlement Amended', 'order', p_order_id, v_order.tracking_number,
    jsonb_build_object('decision_type', v_old.decision_type, 'agreed_retained_amount', v_old.agreed_retained_amount),
    jsonb_build_object('decision_type', v_new.decision_type, 'agreed_retained_amount', v_new.agreed_retained_amount),
    'Amended a cancellation financial decision. Durable old/new values are stored in cancellation_settlement_history.'
  );

  RETURN public.get_cancellation_settlement_summary(p_order_id);
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_cancellation_settlement_history(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(h) ORDER BY h.changed_at DESC), '[]'::jsonb)
  INTO v_result
  FROM public.cancellation_settlement_history h
  WHERE h.order_id = p_order_id;
  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.trigger_photo_storage_health_check()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'vault'
AS $function$
DECLARE
  v_project_url text;
  v_service_key text;
BEGIN
  SELECT decrypted_secret INTO v_project_url FROM vault.decrypted_secrets WHERE name = 'project_url';
  SELECT decrypted_secret INTO v_service_key FROM vault.decrypted_secrets WHERE name = 'service_role_key';

  IF v_project_url IS NULL OR v_service_key IS NULL THEN
    RAISE WARNING 'Photo storage warning check skipped because its server credentials are not configured.';
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := v_project_url || '/functions/v1/photo-storage-health',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := '{}'::jsonb
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.complete_notification_delivery_job(p_job_id uuid, p_claim_id uuid, p_outcome text, p_error text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_job public.notification_delivery_jobs%ROWTYPE;
  v_status TEXT;
BEGIN
  IF p_outcome NOT IN ('sent', 'skipped', 'retry', 'dead') THEN
    RAISE EXCEPTION 'Invalid delivery outcome';
  END IF;

  SELECT * INTO v_job
  FROM public.notification_delivery_jobs
  WHERE id = p_job_id
  FOR UPDATE;

  IF NOT FOUND OR v_job.status <> 'processing' OR v_job.claim_id IS DISTINCT FROM p_claim_id THEN
    RETURN NULL;
  END IF;

  v_status := CASE
    WHEN p_outcome IN ('sent', 'skipped', 'dead') THEN p_outcome
    WHEN v_job.attempt_count >= 5 THEN 'dead'
    ELSE 'retry'
  END;

  UPDATE public.notification_delivery_jobs
     SET status = v_status,
         available_at = CASE
           WHEN v_status = 'retry' THEN now() + make_interval(
             secs => LEAST(900, (15 * power(2, GREATEST(v_job.attempt_count - 1, 0)))::INTEGER)
           )
           ELSE available_at
         END,
         completed_at = CASE WHEN v_status IN ('sent', 'skipped', 'dead') THEN now() ELSE NULL END,
         claimed_at = NULL,
         claim_id = NULL,
         last_error = NULLIF(left(COALESCE(p_error, ''), 1000), ''),
         updated_at = now()
   WHERE id = p_job_id;

  -- Contact inquiries use "at least one admin device accepted" semantics.
  -- Mark the inquiry complete when the first correlated delivery succeeds.
  IF v_status = 'sent' THEN
    UPDATE public.contact_inquiries AS i
       SET push_dispatched_at = COALESCE(i.push_dispatched_at, now()),
           push_dispatch_started_at = NULL,
           push_dispatch_claim_id = NULL
      FROM public.notifications AS n
     WHERE n.id = v_job.notification_id
       AND n.type = 'inquiry'
       AND n.reference_id = i.id;
  END IF;

  RETURN v_status;
END;
$function$;
CREATE OR REPLACE FUNCTION private.trigger_push_delivery_worker()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_project_url TEXT;
  v_service_key TEXT;
BEGIN
  SELECT decrypted_secret INTO v_project_url
  FROM vault.decrypted_secrets
  WHERE name = 'project_url'
  LIMIT 1;

  SELECT decrypted_secret INTO v_service_key
  FROM vault.decrypted_secrets
  WHERE name = 'service_role_key'
  LIMIT 1;

  IF v_project_url IS NULL OR v_service_key IS NULL THEN
    RAISE WARNING 'Push delivery worker skipped because project_url/service_role_key are not configured in Vault.';
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := rtrim(v_project_url, '/') || '/functions/v1/process-push-deliveries',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body := jsonb_build_object('limit', 25)
  );
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_new_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  SELECT
    p.id,
    'Booking Received',
    format('Your booking %s was received. We will keep you updated as it moves.', NEW.tracking_number),
    'general',
    NEW.id
  FROM public.profiles AS p
  WHERE p.id = NEW.user_id
    AND p.role = 'customer'
  ON CONFLICT DO NOTHING;

  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  SELECT
    p.id,
    'New Booking',
    format(
      'New order %s from %s',
      NEW.tracking_number,
      COALESCE(NULLIF(btrim(NEW.sender_name), ''), 'Customer')
    ),
    'order_update',
    NEW.id
  FROM public.profiles AS p
  WHERE p.role = 'admin'
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.purge_old_notification_delivery_jobs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_deleted INTEGER;
BEGIN
  DELETE FROM public.notification_delivery_jobs
  WHERE status IN ('sent', 'skipped', 'dead')
    AND completed_at < now() - INTERVAL '30 days';
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_admins_of_feedback()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  SELECT
    p.id,
    'New Customer Feedback',
    format(
      '%s-star rating%s',
      NEW.rating,
      CASE
        WHEN NULLIF(btrim(COALESCE(NEW.message, '')), '') IS NULL THEN ''
        ELSE ': ' || left(btrim(NEW.message), 60)
      END
    ),
    'feedback',
    NEW.order_id
  FROM public.profiles AS p
  WHERE p.role = 'admin'
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_human_chat_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_customer_id UUID;
  v_status TEXT;
BEGIN
  SELECT c.customer_id, c.status
    INTO v_customer_id, v_status
  FROM public.conversations AS c
  WHERE c.id = NEW.conversation_id;

  IF NEW.sender_role = 'admin' AND v_customer_id IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, title, message, type, reference_id)
    VALUES (
      v_customer_id,
      'New Support Reply',
      'CargoExpress support replied to your conversation.',
      'chat_message',
      NEW.conversation_id
    );
  ELSIF NEW.sender_role = 'customer' AND v_status = 'waiting' THEN
    INSERT INTO public.notifications (user_id, title, message, type, reference_id)
    SELECT
      p.id,
      'Customer Waiting for Support',
      'A customer sent a message that needs a human response.',
      'chat_message',
      NEW.conversation_id
    FROM public.profiles AS p
    WHERE p.role = 'admin';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_announcement_customers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.is_active AND NEW.audience = 'public' THEN
    INSERT INTO public.notifications (user_id, title, message, type, reference_id)
    SELECT p.id, 'New Announcement', NEW.title, 'announcement', NEW.id
    FROM public.profiles AS p
    WHERE p.role = 'customer'
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_payment_failed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
BEGIN
  IF NEW.status <> 'failed' OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = NEW.order_id;
  IF NOT FOUND OR v_order.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  VALUES (
    v_order.user_id,
    'Payment Not Completed',
    format('The payment for order %s was not completed. You may safely try again.', v_order.tracking_number),
    'payment_update',
    v_order.id
  );
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.request_order_cancellation(p_order_id uuid, p_reason text)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_reason TEXT := btrim(COALESCE(p_reason, ''));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF char_length(v_reason) < 5 OR char_length(v_reason) > 500 THEN
    RAISE EXCEPTION 'Cancellation reason must be between 5 and 500 characters.';
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
    AND user_id = auth.uid()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Only your own bookings can be cancelled';
  END IF;
  IF v_order.status = 'Pending Cancellation' THEN
    RAISE EXCEPTION 'A cancellation request for this booking is already awaiting review.';
  END IF;
  IF v_order.status = 'Cancelled' THEN
    RAISE EXCEPTION 'This booking is already cancelled.';
  END IF;
  IF v_order.status IN ('Picked Up', 'In Transit', 'Arrived at Hub', 'Out for Delivery', 'Delivered') THEN
    RAISE EXCEPTION 'This shipment is already in the delivery network. Please contact support instead.';
  END IF;

  UPDATE public.orders
     SET status = 'Pending Cancellation',
         cancellation_details = jsonb_build_object(
           'reason', v_reason,
           'requested_at', now(),
           'previous_status', v_order.status
         )
   WHERE id = p_order_id
   RETURNING * INTO v_order;

  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  SELECT
    p.id,
    'Cancellation Requested',
    format('Order %s: the customer asked to cancel. Reason: %s', v_order.tracking_number, v_reason),
    'order_update',
    v_order.id
  FROM public.profiles AS p
  WHERE p.role = 'admin';

  INSERT INTO public.activity_logs (
    module, action, record_type, record_id, record_ref,
    previous_value, new_value, details
  ) VALUES (
    'Orders',
    'Cancellation Requested',
    'order',
    v_order.id,
    v_order.tracking_number,
    jsonb_build_object('status', v_order.cancellation_details->>'previous_status'),
    jsonb_build_object('status', 'Pending Cancellation'),
    'Customer requested to cancel the booking. Reason: ' || v_reason
  );

  RETURN v_order;
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_feedback_visibility_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tracking_number TEXT;
  v_admin_name TEXT;
BEGIN
  IF NEW.is_hidden IS NOT DISTINCT FROM OLD.is_hidden THEN
    RETURN NEW;
  END IF;

  SELECT o.tracking_number
    INTO v_tracking_number
    FROM public.orders o
   WHERE o.id = NEW.order_id;

  SELECT COALESCE(NULLIF(btrim(p.name), ''), 'Unknown Admin')
    INTO v_admin_name
    FROM public.profiles p
   WHERE p.id = auth.uid();

  INSERT INTO public.activity_logs (
    admin_id, admin_name, module, action, record_type, record_id, record_ref,
    previous_value, new_value, details
  ) VALUES (
    auth.uid(),
    COALESCE(v_admin_name, 'System'),
    'Feedback',
    CASE WHEN NEW.is_hidden THEN 'Feedback Hidden' ELSE 'Feedback Unhidden' END,
    'feedback',
    NEW.id,
    v_tracking_number,
    jsonb_build_object('is_hidden', OLD.is_hidden),
    jsonb_build_object('is_hidden', NEW.is_hidden),
    CASE WHEN NEW.is_hidden
      THEN 'Hid this review from the public website.'
      ELSE 'Restored this review to the public website.'
    END
  );

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.validate_trip_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_count INTEGER;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  IF NOT public.is_admin() AND auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'Admin privileges required';
  END IF;

  IF NOT (
    (OLD.status = 'scheduled' AND NEW.status IN ('in_progress', 'cancelled'))
    OR (OLD.status = 'in_progress' AND NEW.status IN ('arrived', 'cancelled'))
    OR (OLD.status = 'arrived' AND NEW.status IN ('completed', 'cancelled'))
  ) THEN
    RAISE EXCEPTION 'Invalid trip status transition from % to %', OLD.status, NEW.status;
  END IF;

  IF NEW.status = 'in_progress' THEN
    SELECT count(*) INTO v_count
    FROM public.orders
    WHERE trip_id = NEW.id
      AND status NOT IN ('Picked Up', 'Cancelled');
    IF v_count > 0 THEN
      RAISE EXCEPTION 'All assigned orders must be picked up before the trip can start.';
    END IF;
  ELSIF NEW.status = 'completed' THEN
    SELECT count(*) INTO v_count
    FROM public.orders
    WHERE trip_id = NEW.id
      AND status NOT IN ('Delivered', 'Cancelled');
    IF v_count > 0 THEN
      RAISE EXCEPTION 'All assigned orders must be delivered or cancelled before completing the trip.';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.cascade_trip_status_and_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order RECORD;
  v_target_status TEXT;
  v_title TEXT;
  v_message TEXT;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  v_target_status := CASE NEW.status
    WHEN 'in_progress' THEN 'In Transit'
    WHEN 'arrived' THEN 'Arrived at Hub'
    WHEN 'cancelled' THEN 'Cancelled'
    ELSE NULL
  END;
  v_title := CASE NEW.status
    WHEN 'in_progress' THEN 'Trip Started'
    WHEN 'arrived' THEN 'Trip Arrived'
    WHEN 'completed' THEN 'Trip Completed'
    WHEN 'cancelled' THEN 'Trip Cancelled'
  END;

  FOR v_order IN
    SELECT o.id, o.user_id, o.tracking_number, o.status
    FROM public.orders AS o
    WHERE o.trip_id = NEW.id
      AND o.user_id IS NOT NULL
      AND o.status <> 'Cancelled'
      AND (
        (NEW.status = 'in_progress' AND o.status = 'Picked Up')
        OR (NEW.status = 'arrived' AND o.status = 'In Transit')
        OR (NEW.status = 'cancelled' AND o.status IN (
          'Pending', 'Assigned', 'Picked Up', 'Pending Cancellation',
          'In Transit', 'Arrived at Hub', 'Out for Delivery'
        ))
        OR (NEW.status = 'completed' AND o.status = 'Delivered')
      )
    FOR UPDATE
  LOOP
    IF v_target_status IS NOT NULL AND v_order.status IS DISTINCT FROM v_target_status THEN
      UPDATE public.orders SET status = v_target_status WHERE id = v_order.id;
    END IF;

    v_message := CASE NEW.status
      WHEN 'in_progress' THEN format('Order %s is now in transit.', v_order.tracking_number)
      WHEN 'arrived' THEN format('Order %s has arrived at the destination hub.', v_order.tracking_number)
      WHEN 'completed' THEN format('The trip carrying order %s has been completed.', v_order.tracking_number)
      WHEN 'cancelled' THEN format('The trip assigned to order %s was cancelled.', v_order.tracking_number)
    END;

    INSERT INTO public.notifications (user_id, title, message, type, reference_id)
    VALUES (v_order.user_id, v_title, v_message, 'trip_update', v_order.id);

    IF v_target_status IS NOT NULL AND v_order.status IS DISTINCT FROM v_target_status THEN
      INSERT INTO public.activity_logs (
        module, action, record_type, record_id, record_ref,
        previous_value, new_value, details
      ) VALUES (
        'Orders',
        'Status Changed to ' || v_target_status,
        'order',
        v_order.id,
        v_order.tracking_number,
        jsonb_build_object('status', v_order.status),
        jsonb_build_object('status', v_target_status),
        'Triggered atomically by trip ' || NEW.trip_number || ' status change'
      );
    END IF;
  END LOOP;

  INSERT INTO public.activity_logs (
    module, action, record_type, record_id, record_ref,
    previous_value, new_value, details
  ) VALUES (
    'Trips',
    v_title,
    'trip',
    NEW.id,
    NEW.trip_number,
    jsonb_build_object('status', OLD.status),
    jsonb_build_object('status', NEW.status),
    'Trip status updated atomically to ' || NEW.status
  );

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_trip_rescheduled()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.status = 'scheduled'
     AND (
       NEW.departure_date IS DISTINCT FROM OLD.departure_date
       OR NEW.arrival_date IS DISTINCT FROM OLD.arrival_date
     ) THEN
    INSERT INTO public.notifications (user_id, title, message, type, reference_id)
    SELECT
      o.user_id,
      'Trip Rescheduled',
      format(
        'The trip for order %s is now scheduled to depart on %s.',
        o.tracking_number,
        to_char(NEW.departure_date AT TIME ZONE 'Asia/Manila', 'Mon DD, YYYY')
      ),
      'trip_update',
      o.id
    FROM public.orders AS o
    WHERE o.trip_id = NEW.id
      AND o.user_id IS NOT NULL
      AND o.status <> 'Cancelled';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.trigger_trip_reschedule_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_project_url TEXT;
  v_service_key TEXT;
BEGIN
  IF current_setting('cargoexpress.trip_reschedule_notify_all', true) = 'true' THEN
    -- The admin chose "Email this schedule update to all subscribers" for
    -- this reschedule; that broader, public broadcast (created client-side
    -- via createAnnouncement, see src/lib/database.js) covers this trip's
    -- booked+opted-in customers too, via email_subscriptions. Sending the
    -- narrow per-trip courtesy email as well would duplicate it.
    RETURN NEW;
  END IF;

  SELECT decrypted_secret INTO v_project_url
  FROM vault.decrypted_secrets
  WHERE name = 'project_url'
  LIMIT 1;

  SELECT decrypted_secret INTO v_service_key
  FROM vault.decrypted_secrets
  WHERE name = 'service_role_key'
  LIMIT 1;

  IF v_project_url IS NULL OR v_service_key IS NULL THEN
    RAISE WARNING 'trigger_trip_reschedule_email: project_url/service_role_key not found in Vault — skipping trip %.', NEW.id;
    RETURN NEW;
  END IF;

  PERFORM net.http_post(
    url     := rtrim(v_project_url, '/') || '/functions/v1/email-trip-reschedule',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := jsonb_build_object(
      'trip_id',             NEW.id,
      'old_departure_date',  OLD.departure_date,
      'old_arrival_date',    OLD.arrival_date,
      'new_departure_date',  NEW.departure_date,
      'new_arrival_date',    NEW.arrival_date
    )
  );

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_activity(p_client_event_id uuid, p_module text, p_action text, p_record_type text DEFAULT NULL::text, p_record_id uuid DEFAULT NULL::uuid, p_record_ref text DEFAULT NULL::text, p_previous_value jsonb DEFAULT NULL::jsonb, p_new_value jsonb DEFAULT NULL::jsonb, p_details text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_is_admin BOOLEAN;
  v_admin_name TEXT;
  v_log_id UUID;
  v_occurred_at TIMESTAMPTZ;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_client_event_id IS NULL THEN
    RAISE EXCEPTION 'A client event ID is required';
  END IF;

  IF NULLIF(btrim(p_module), '') IS NULL OR NULLIF(btrim(p_action), '') IS NULL THEN
    RAISE EXCEPTION 'Module and action are required';
  END IF;

  v_is_admin := public.is_admin();
  IF NOT v_is_admin AND p_module NOT IN ('Orders', 'Authentication', 'Chat') THEN
    RAISE EXCEPTION 'Not allowed to write % activity logs', p_module;
  END IF;

  SELECT COALESCE(NULLIF(btrim(p.name), ''), 'Unknown Admin')
    INTO v_admin_name
    FROM public.profiles p
   WHERE p.id = v_uid;

  -- Keep the real time of a temporarily queued event, but do not accept a
  -- future timestamp or preserve an event beyond the screen's retention.
  v_occurred_at := GREATEST(
    now() - INTERVAL '7 days',
    LEAST(COALESCE(p_occurred_at, now()), now())
  );

  INSERT INTO public.activity_logs (
    admin_id,
    admin_name,
    module,
    action,
    record_type,
    record_id,
    record_ref,
    previous_value,
    new_value,
    details,
    created_at,
    client_event_id
  ) VALUES (
    v_uid,
    COALESCE(v_admin_name, 'Unknown Admin'),
    btrim(p_module),
    btrim(p_action),
    NULLIF(btrim(p_record_type), ''),
    p_record_id,
    NULLIF(btrim(p_record_ref), ''),
    p_previous_value,
    p_new_value,
    NULLIF(btrim(p_details), ''),
    v_occurred_at,
    p_client_event_id
  )
  ON CONFLICT (admin_id, client_event_id) DO NOTHING
  RETURNING id INTO v_log_id;

  IF v_log_id IS NULL THEN
    SELECT id
      INTO v_log_id
      FROM public.activity_logs
     WHERE admin_id = v_uid
       AND client_event_id = p_client_event_id;
  END IF;

  RETURN v_log_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_order_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  trip_row      public.trips%ROWTYPE;
  weight        NUMERIC;
  price         NUMERIC;
  v_current_load NUMERIC;
  v_capacity_allowance CONSTANT NUMERIC := 200;
  v_payable     NUMERIC;
BEGIN
  -- ── Cancellation review hold ──────────────────────────────────────────────
  IF OLD.status = 'Pending Cancellation'
     AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status NOT IN ('Cancelled', COALESCE(OLD.cancellation_details->>'previous_status', 'Pending'))
  THEN
    RAISE EXCEPTION
      'Order % has a cancellation request awaiting review. Approve or reject it before changing its status.',
      NEW.tracking_number;
  END IF;

  -- ── Sender/receiver first+last <-> full-name sync (NEW) ─────────────────
  -- Whichever side of the write actually changed wins: first/last changed
  -- -> recompute the full name; only the full name changed (an old caller,
  -- a script, update_order_contact_details() before it is migrated) ->
  -- re-derive first/last from it. Must run before the lock check below.
  IF (NEW.sender_first_name, NEW.sender_last_name) IS DISTINCT FROM
     (OLD.sender_first_name, OLD.sender_last_name) THEN
    NEW.sender_name := NULLIF(btrim(concat_ws(' ', NEW.sender_first_name, NEW.sender_last_name)), '');
  ELSIF NEW.sender_name IS DISTINCT FROM OLD.sender_name THEN
    NEW.sender_first_name := split_part(btrim(NEW.sender_name), ' ', 1);
    NEW.sender_last_name  := CASE
      WHEN position(' ' in btrim(NEW.sender_name)) = 0 THEN ''
      ELSE btrim(substring(btrim(NEW.sender_name) from position(' ' in btrim(NEW.sender_name)) + 1))
    END;
  END IF;

  IF (NEW.receiver_first_name, NEW.receiver_last_name) IS DISTINCT FROM
     (OLD.receiver_first_name, OLD.receiver_last_name) THEN
    NEW.receiver_name := NULLIF(btrim(concat_ws(' ', NEW.receiver_first_name, NEW.receiver_last_name)), '');
  ELSIF NEW.receiver_name IS DISTINCT FROM OLD.receiver_name THEN
    NEW.receiver_first_name := split_part(btrim(NEW.receiver_name), ' ', 1);
    NEW.receiver_last_name  := CASE
      WHEN position(' ' in btrim(NEW.receiver_name)) = 0 THEN ''
      ELSE btrim(substring(btrim(NEW.receiver_name) from position(' ' in btrim(NEW.receiver_name)) + 1))
    END;
  END IF;

  -- ── NEW (20260922160000) — sender/receiver name policy, on CHANGE only ──
  -- Placed AFTER the first/last <-> full-name sync above, so whichever side
  -- of the write the caller used, the values judged here are the fully
  -- resolved ones. Placed BEFORE the contact/address lock so an invalid
  -- name is refused for the same reason on every path.
  --
  -- Every check is gated on "IS DISTINCT FROM OLD": a booking carrying a
  -- historical name that predates this policy can still be assigned, picked
  -- up, paid, delivered, reweighed and cancelled. Only a write that CHANGES
  -- a name to a non-conforming value is refused. A blank last_name stays
  -- legal (legacy mononyms, see 20260922100000's backfill).
  IF NEW.sender_first_name IS DISTINCT FROM OLD.sender_first_name
     AND NULLIF(btrim(NEW.sender_first_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.sender_first_name) THEN
    RAISE EXCEPTION 'Sender first name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;
  IF NEW.sender_last_name IS DISTINCT FROM OLD.sender_last_name
     AND NULLIF(btrim(NEW.sender_last_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.sender_last_name) THEN
    RAISE EXCEPTION 'Sender last name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;
  IF NEW.receiver_first_name IS DISTINCT FROM OLD.receiver_first_name
     AND NULLIF(btrim(NEW.receiver_first_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.receiver_first_name) THEN
    RAISE EXCEPTION 'Receiver first name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;
  IF NEW.receiver_last_name IS DISTINCT FROM OLD.receiver_last_name
     AND NULLIF(btrim(NEW.receiver_last_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.receiver_last_name) THEN
    RAISE EXCEPTION 'Receiver last name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;

  -- ── Contact/address details lock (mirrors update_order_contact_details(),
  --    20260915120000) — see 20260915130000's header comment. ────────────
  IF (NEW.sender_name, NEW.sender_phone, NEW.sender_province, NEW.sender_city,
      NEW.sender_barangay, NEW.sender_street, NEW.sender_landmark, NEW.sender_address,
      NEW.receiver_name, NEW.receiver_phone, NEW.receiver_province, NEW.receiver_city,
      NEW.receiver_barangay, NEW.receiver_street, NEW.receiver_landmark, NEW.receiver_address)
     IS DISTINCT FROM
     (OLD.sender_name, OLD.sender_phone, OLD.sender_province, OLD.sender_city,
      OLD.sender_barangay, OLD.sender_street, OLD.sender_landmark, OLD.sender_address,
      OLD.receiver_name, OLD.receiver_phone, OLD.receiver_province, OLD.receiver_city,
      OLD.receiver_barangay, OLD.receiver_street, OLD.receiver_landmark, OLD.receiver_address)
  THEN
    IF public.is_admin() THEN
      IF OLD.status IN ('Out for Delivery', 'Delivered') THEN
        RAISE EXCEPTION 'Customer details are locked once the booking is out for delivery. (current status: %)', OLD.status;
      END IF;
    ELSE
      IF OLD.status IN ('Out for Delivery', 'Delivered', 'Cancelled') THEN
        RAISE EXCEPTION 'Customer details are locked once the booking is out for delivery. (current status: %)', OLD.status;
      END IF;
    END IF;
  END IF;

  IF NEW.trip_id IS NOT NULL AND NEW.status <> 'Cancelled' THEN
    SELECT * INTO trip_row FROM public.trips WHERE id = NEW.trip_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Selected trip does not exist';
    END IF;

    NEW.origin := trip_row.origin;
    NEW.destination := trip_row.destination;

    -- ── Capacity enforcement (matches frontend TRIP_CAPACITY_ALLOWANCE_KG) ──
    -- Only enforce when the trip has a positive capacity set and either the
    -- trip assignment changed or the actual_weight changed.
    IF trip_row.capacity > 0
       AND (OLD.trip_id IS DISTINCT FROM NEW.trip_id
            OR NEW.actual_weight IS DISTINCT FROM OLD.actual_weight)
    THEN
      SELECT COALESCE(SUM(COALESCE(o.actual_weight, 0)), 0)
        INTO v_current_load
        FROM public.orders o
       WHERE o.trip_id = NEW.trip_id
         AND o.id <> NEW.id
         AND o.status <> 'Cancelled';

      IF (v_current_load + COALESCE(NEW.actual_weight, 0)) > (trip_row.capacity + v_capacity_allowance) THEN
        RAISE EXCEPTION
          'Cannot accept booking: exceeds maximum van capacity of % kg (% kg planned + % kg allowance). This trip is carrying % kg.',
          trip_row.capacity + v_capacity_allowance,
          trip_row.capacity,
          v_capacity_allowance,
          v_current_load;
      END IF;
    END IF;

    IF OLD.trip_id IS DISTINCT FROM NEW.trip_id AND NEW.status = 'Pending' THEN
      NEW.status := 'Assigned';
    END IF;
  END IF;

  IF NEW.actual_weight IS DISTINCT FROM OLD.actual_weight
     OR NEW.trip_id IS DISTINCT FROM OLD.trip_id
     OR NEW.amount_paid IS DISTINCT FROM OLD.amount_paid
     OR NEW.discount_amount IS DISTINCT FROM OLD.discount_amount THEN
    weight := COALESCE(NEW.actual_weight, 0);
    price := CASE
      WHEN NEW.trip_id IS NOT NULL THEN public.effective_trip_price(NEW.trip_id)
      ELSE public.global_price_per_kilo()
    END;
    NEW.shipping_cost := ROUND(weight * price, 2);

    -- ── Discount guard ────────────────────────────────────────────────────
    -- Fires only when discount_amount/reason/notes are ACTUALLY changing —
    -- not on the amount_paid-triggered recompute cascade that runs every time
    -- update_order_payment_totals writes a new total (see that function's own
    -- comment), which would otherwise re-enter this block on every payment.
    IF NEW.discount_amount IS DISTINCT FROM OLD.discount_amount
       OR NEW.discount_reason IS DISTINCT FROM OLD.discount_reason
       OR NEW.discount_notes  IS DISTINCT FROM OLD.discount_notes THEN

      IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Admin access required to change a shipping discount.';
      END IF;

      -- Read-only once pickup is confirmed. record_pickup_payment() is the
      -- only place a discount is ever set, and it always does so from one of
      -- these three pre-pickup statuses — so this also rejects a raw
      -- `.update()` bypassing that RPC entirely, not only a second call to it.
      IF OLD.status NOT IN ('Pending Review', 'Pending', 'Assigned') THEN
        RAISE EXCEPTION 'A discount can only be set or changed before pickup is confirmed.';
      END IF;

      -- Belt-and-suspenders: even if some future status allowed this branch
      -- to run past pickup, a recorded payment blocks it outright.
      IF EXISTS (
        SELECT 1 FROM public.payment_transactions
         WHERE order_id = NEW.id AND payment_status IN ('paid', 'partial')
      ) THEN
        RAISE EXCEPTION 'This order already has a recorded payment; its discount can no longer be changed.';
      END IF;

      IF COALESCE(NEW.discount_amount, 0) < 0 THEN
        RAISE EXCEPTION 'Discount cannot be negative.';
      END IF;

      IF NEW.discount_amount > NEW.shipping_cost THEN
        RAISE EXCEPTION 'Discount of ₱% cannot exceed the original shipping fee of ₱%.',
          TO_CHAR(NEW.discount_amount, 'FM999999990.00'), TO_CHAR(NEW.shipping_cost, 'FM999999990.00');
      END IF;

      IF NEW.discount_amount > 0 THEN
        IF NEW.discount_reason IS NULL OR NEW.discount_reason NOT IN ('Regular customer', 'Negotiated price', 'Other') THEN
          RAISE EXCEPTION 'A discount requires a reason: Regular customer, Negotiated price, or Other.';
        END IF;
        IF NEW.discount_reason = 'Other' AND NULLIF(btrim(NEW.discount_notes), '') IS NULL THEN
          RAISE EXCEPTION 'Please explain the discount reason when "Other" is selected.';
        END IF;
        NEW.discount_applied_by := auth.uid();
        NEW.discount_applied_at := now();
      ELSE
        -- Toggled off before confirming: no reason, no notes, no audit stamp
        -- left behind for a discount that was never actually applied.
        NEW.discount_amount     := 0;
        NEW.discount_reason     := NULL;
        NEW.discount_notes      := NULL;
        NEW.discount_applied_by := NULL;
        NEW.discount_applied_at := NULL;
      END IF;
    END IF;

    v_payable := public.order_payable_amount(NEW.shipping_cost, NEW.discount_amount);
    NEW.remaining_balance := GREATEST(0, v_payable - COALESCE(NEW.amount_paid, 0));
    -- The badge follows the balance. Without this a re-weighed order kept a
    -- stale 'Paid' label while money was owing (20260805120000).
    NEW.payment_status := public.derive_payment_status(v_payable, NEW.amount_paid);
  END IF;

  -- ── Warehouse dispatch gate (20260804100000, 20260806030000) ─────────────
  -- Placed last so it sees the recomputed weight and remaining_balance above.
  IF NEW.status = 'Out for Delivery' AND OLD.status IS DISTINCT FROM NEW.status THEN

    -- (a) Priced? An unweighed parcel has no cost, so its ₱0.00 balance must
    -- not be read as "paid". Applies to every payer type.
    IF COALESCE(NEW.actual_weight, 0) <= 0 THEN
      RAISE EXCEPTION
        'Cannot dispatch order % — it has not been weighed, so it has no price yet. Record the actual weight first.',
        NEW.tracking_number;
    END IF;

    -- (b) Paid? Unpaid cargo is held at the destination warehouse and not
    -- dispatched for doorstep delivery. Freight Collect is exempt (payment is
    -- due at the door); a recorded Promise Date is the explicit override.
    IF COALESCE(NEW.payer_type, 'sender') <> 'receiver'
       AND COALESCE(NEW.remaining_balance, 0) > 0
       AND NEW.promised_payment_date IS NULL
    THEN
      RAISE EXCEPTION
        'Cannot dispatch order % — ₱% is still owing. Settle the balance, or record a Promise Date to dispatch anyway.',
        NEW.tracking_number,
        TO_CHAR(COALESCE(NEW.remaining_balance, 0), 'FM999999990.00');
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT role = 'admin' FROM public.profiles WHERE id = auth.uid()),
    FALSE
  );
$function$;
CREATE OR REPLACE FUNCTION public.generate_order_tracking_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  candidate TEXT;
BEGIN
  LOOP
    candidate := 'CE-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || FLOOR(1000 + RANDOM() * 9000)::INT;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.orders WHERE tracking_number = candidate);
  END LOOP;
  RETURN candidate;
END;
$function$;
CREATE OR REPLACE FUNCTION public.global_price_per_kilo()
 RETURNS numeric
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((SELECT default_price_per_kg FROM public.company_information WHERE id = '00000000-0000-0000-0000-000000000001' LIMIT 1), 70);
$function$;
CREATE OR REPLACE FUNCTION public.safe_uuid(value text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN value::UUID;
EXCEPTION WHEN invalid_text_representation THEN
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_manual_gcash_payment(p_reference text, p_admin_verified_receipt boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ref_norm TEXT;
  v_dupe     RECORD;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  IF NOT COALESCE(p_admin_verified_receipt, false) THEN
    RAISE EXCEPTION 'Confirm that you have verified receipt of this GCash transfer before recording it.'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(trim(p_reference), '') = '' THEN
    RAISE EXCEPTION 'A GCash transfer reference number is required.'
      USING ERRCODE = '22023';
  END IF;

  v_ref_norm := upper(regexp_replace(trim(p_reference), '[\s-]+', '', 'g'));

  SELECT pt.order_id, o.tracking_number, pt.amount, pt.created_at
    INTO v_dupe
    FROM public.payment_transactions pt
    JOIN public.orders o ON o.id = pt.order_id
   WHERE pt.gcash_channel = 'manual'
     AND pt.transaction_reference_normalized = v_ref_norm
   LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'This GCash reference was already recorded against order % (₱% on %). It cannot be credited again.',
      v_dupe.tracking_number, TO_CHAR(v_dupe.amount, 'FM999999990.00'), v_dupe.created_at::date
      USING ERRCODE = '23505';
  END IF;

  RETURN v_ref_norm;
END;
$function$;
CREATE OR REPLACE FUNCTION public.prepare_order_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  trip_row       public.trips%ROWTYPE;
  v_current_load NUMERIC;
  v_capacity_allowance CONSTANT NUMERIC := 200;
BEGIN
  IF auth.uid() IS NOT NULL AND NEW.user_id <> auth.uid() AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Cannot create orders for another user';
  END IF;

  -- ── NEW (20260922160000) — sender/receiver name policy ─────────────────
  -- A booking is created here for the first time, so there is no legacy
  -- value to grandfather: every name written must conform. A blank
  -- last_name is tolerated (mononyms); a non-blank one must be valid.
  IF NULLIF(btrim(NEW.sender_first_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.sender_first_name) THEN
    RAISE EXCEPTION 'Sender first name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(NEW.sender_last_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.sender_last_name) THEN
    RAISE EXCEPTION 'Sender last name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(NEW.receiver_first_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.receiver_first_name) THEN
    RAISE EXCEPTION 'Receiver first name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(NEW.receiver_last_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.receiver_last_name) THEN
    RAISE EXCEPTION 'Receiver last name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;
  -- An older client that still writes only the combined column is checked
  -- on that column instead, so neither shape of write escapes the policy.
  IF NULLIF(btrim(NEW.sender_first_name), '') IS NULL
     AND NULLIF(btrim(NEW.sender_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.sender_name) THEN
    RAISE EXCEPTION 'Sender name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;
  IF NULLIF(btrim(NEW.receiver_first_name), '') IS NULL
     AND NULLIF(btrim(NEW.receiver_name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.receiver_name) THEN
    RAISE EXCEPTION 'Receiver name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;

  NEW.tracking_number := public.generate_order_tracking_number();
  NEW.actual_weight := NULL;
  NEW.payment_method := NULL;
  NEW.payment_status := 'unpaid';
  NEW.amount_paid := 0;
  NEW.promised_payment_date := NULL;
  NEW.payment_reference := NULL;
  NEW.pickup_photos := '[]'::jsonb;
  NEW.delivery_photos := '[]'::jsonb;

  -- A booking cannot be born already asking to be cancelled.
  NEW.cancellation_details         := NULL;

  -- A booking cannot be born already discounted — a discount is applied at
  -- pickup, by an admin, through record_pickup_payment(), never at creation.
  NEW.discount_amount     := 0;
  NEW.discount_reason     := NULL;
  NEW.discount_notes      := NULL;
  NEW.discount_applied_by := NULL;
  NEW.discount_applied_at := NULL;

  -- A booking's out-of-coverage review flag is derived from the sender's
  -- actual province, never trusted from the client request. 'approved' and
  -- 'rejected' are only ever reachable afterward, through the admin-only
  -- UPDATE path (OrderDetailPage's handleApproveReview/handleRejectReview).
  NEW.service_area_status := CASE
    WHEN public.is_standard_service_area_province(NEW.sender_province) THEN 'standard'
    ELSE 'for_review'
  END;
  NEW.service_area_remarks := NULL;

  IF NEW.trip_id IS NOT NULL THEN
    SELECT * INTO trip_row FROM public.trips WHERE id = NEW.trip_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Selected trip does not exist';
    END IF;

    -- ── Capacity enforcement (matches frontend TRIP_CAPACITY_ALLOWANCE_KG) ──
    IF trip_row.capacity > 0 THEN
      SELECT COALESCE(SUM(COALESCE(o.actual_weight, 0)), 0)
        INTO v_current_load
        FROM public.orders o
       WHERE o.trip_id = NEW.trip_id
         AND o.status <> 'Cancelled';

      IF v_current_load > (trip_row.capacity + v_capacity_allowance) THEN
        RAISE EXCEPTION
          'Cannot accept booking: exceeds maximum van capacity of % kg (% kg planned + % kg allowance). This trip is carrying % kg.',
          trip_row.capacity + v_capacity_allowance,
          trip_row.capacity,
          v_capacity_allowance,
          v_current_load;
      END IF;
    END IF;

    NEW.status := 'Assigned';
    NEW.origin := trip_row.origin;
    NEW.destination := trip_row.destination;
  ELSE
    NEW.status := 'Pending';
  END IF;

  -- No weight, no price. Both are set by guard_order_update the moment an
  -- admin records actual_weight at pickup.
  NEW.shipping_cost := 0;
  NEW.remaining_balance := 0;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.maintain_conversation_service_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status      TEXT;
  v_next        TEXT;
  v_new_session BOOLEAN;
BEGIN
  SELECT status
    INTO v_status
    FROM public.conversations
   WHERE id = NEW.conversation_id;

  PERFORM set_config('app.conversation_service_write', 'on', true);

  IF NEW.sender_role = 'customer' THEN
    v_next := CASE
                WHEN v_status = 'bot_active' THEN 'bot_active'
                WHEN v_status = 'resolved' THEN 'bot_active'
                ELSE 'waiting'
              END;

    v_new_session := (v_status = 'resolved' AND v_next = 'bot_active');

    UPDATE public.conversations
       SET last_customer_message_at = NEW.created_at,
           status      = v_next,
           escalated   = CASE WHEN v_new_session THEN FALSE ELSE escalated END,
           resolved_at = NULL
     WHERE id = NEW.conversation_id;

  ELSIF NEW.sender_role = 'admin' THEN
    UPDATE public.conversations
       SET first_response_at = COALESCE(first_response_at, NEW.created_at),
           status = 'waiting_customer'
     WHERE id = NEW.conversation_id;
  END IF;

  PERFORM set_config('app.conversation_service_write', 'off', true);
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.ph_calendar_day(ts timestamp with time zone)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE STRICT
AS $function$
  SELECT ((ts + INTERVAL '8 hours') AT TIME ZONE 'UTC')::date;
$function$;
CREATE OR REPLACE FUNCTION public.get_order_status_counts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  payload JSONB;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  SELECT COALESCE(jsonb_object_agg(s.status, s.n), '{}'::jsonb)
    INTO payload
  FROM (
    SELECT status, COUNT(*) AS n
      FROM public.orders
     GROUP BY status
  ) s;

  -- A status with no orders is simply absent; the client reads a missing key
  -- as 0. Padding every known status with a zero here would invent rows the
  -- table does not have.
  RETURN payload;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_customer_of_order_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_title TEXT;
  v_message TEXT;
  v_reason TEXT;
BEGIN
  -- A trip-status trigger updates its orders and emits the more useful
  -- trip-specific message itself. Suppress a second generic order message for
  -- those nested writes.
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  -- Walk-in orders are initially owned by the creating admin. Only registered
  -- customer profiles should receive customer lifecycle notifications.
  IF NEW.user_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.profiles AS p
    WHERE p.id = NEW.user_id
      AND p.role = 'customer'
  ) THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    v_title := 'Booking Added to Your Account';
    v_message := format(
      'Booking %s has been added to your account history.',
      NEW.tracking_number
    );

  ELSIF NEW.service_area_status IS DISTINCT FROM OLD.service_area_status
        AND NEW.service_area_status = 'approved' THEN
    v_title := 'Pickup Request Approved';
    v_message := format(
      'Your special pickup request for Order %s has been approved.',
      NEW.tracking_number
    );

  ELSIF NEW.service_area_status IS DISTINCT FROM OLD.service_area_status
        AND NEW.service_area_status = 'rejected' THEN
    v_title := 'Pickup Request Rejected';
    v_message := format(
      'Your special pickup request for Order %s could not be accommodated. Reason: %s',
      NEW.tracking_number,
      COALESCE(NULLIF(btrim(NEW.service_area_remarks), ''), 'Not specified')
    );

  ELSIF NEW.trip_id IS DISTINCT FROM OLD.trip_id THEN
    IF NEW.trip_id IS NULL THEN
      v_title := 'Trip Assignment Removed';
      v_message := format(
        'Order %s is no longer assigned to its previous trip.',
        NEW.tracking_number
      );
    ELSIF OLD.trip_id IS NULL THEN
      v_title := 'Order Assigned';
      v_message := format('Order %s assigned to a trip', NEW.tracking_number);
    ELSE
      v_title := 'Trip Reassigned';
      v_message := format(
        'Order %s has been moved to a new trip',
        NEW.tracking_number
      );
    END IF;

  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    -- These transitions already create purpose-built notifications in their
    -- owning RPCs. Avoid duplicating those messages.
    IF NEW.status = 'Pending Cancellation'
       OR OLD.status = 'Pending Cancellation' THEN
      RETURN NEW;
    END IF;

    CASE NEW.status
      WHEN 'Picked Up' THEN
        v_title := 'Pickup Complete';
        v_message := format(
          'Order %s has been picked up',
          NEW.tracking_number
        );
      WHEN 'Delivered' THEN
        v_title := 'Delivery Complete';
        v_message := format(
          'Order %s has been delivered',
          NEW.tracking_number
        );
      WHEN 'Cancelled' THEN
        v_reason := NULLIF(btrim(NEW.cancellation_details->>'reason'), '');
        v_title := 'Order Cancelled';
        v_message := format(
          'Order %s has been cancelled.%s',
          NEW.tracking_number,
          CASE WHEN v_reason IS NULL THEN '' ELSE ' Reason: ' || v_reason END
        );
      ELSE
        v_title := 'Order Updated';
        v_message := format(
          'Order %s: %s',
          NEW.tracking_number,
          NEW.status
        );
    END CASE;
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.notifications (
    user_id, title, message, type, reference_id
  ) VALUES (
    NEW.user_id, v_title, v_message, 'order_update', NEW.id
  );

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_delivery_payment(p_order_id uuid, p_delivery_photos jsonb DEFAULT '[]'::jsonb, p_payment_method text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric, p_reference text DEFAULT NULL::text, p_payment_date date DEFAULT NULL::date, p_receipt_url text DEFAULT NULL::text, p_payment_type text DEFAULT 'Balance Settlement'::text, p_notes text DEFAULT 'Balance settlement upon delivery'::text, p_promised_payment_date date DEFAULT NULL::date, p_idempotency_key uuid DEFAULT NULL::uuid, p_admin_verified_receipt boolean DEFAULT false)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order                  public.orders;
  v_admin_name             TEXT;
  v_paid_after             NUMERIC;
  v_label                  TEXT;
  v_total_paid_before      NUMERIC;
  v_total_paid_projected   NUMERIC;
  v_payable                NUMERIC;
  v_outstanding_before     NUMERIC;
  v_remaining_projected    NUMERIC;
  v_effective_promise_date DATE;
  v_idempotency_order_id   UUID;
  v_ref_norm               TEXT;
  v_method                 TEXT := lower(COALESCE(p_payment_method, ''));
  v_gcash_channel          TEXT;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- The order lock makes a retry with the same key observe the first call's
  -- committed ledger row before deciding whether to do any work. This is the
  -- ONLY thing that stops a retried/double-clicked delivery confirmation
  -- from creating a second cash (or gcash) transaction — it does not depend
  -- on payment method, and nothing below it needs to duplicate this check.
  IF p_idempotency_key IS NOT NULL THEN
    SELECT order_id INTO v_idempotency_order_id
      FROM public.payment_transactions
     WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN
      IF v_idempotency_order_id = p_order_id THEN
        RETURN v_order;
      END IF;
      RAISE EXCEPTION 'This payment attempt identifier is already associated with another order.'
        USING ERRCODE = '23505';
    END IF;
  END IF;

  -- Delivery is the final state transition, not a generic status override.
  -- Enforce the same lifecycle and proof rules as DeliveryModal on the trusted
  -- side of the API so a direct authenticated RPC call cannot bypass them.
  IF v_order.status <> 'Out for Delivery' THEN
    RAISE EXCEPTION 'Only an order that is Out for Delivery can be marked as delivered.'
      USING ERRCODE = '22023';
  END IF;

  IF p_delivery_photos IS NULL
     OR jsonb_typeof(p_delivery_photos) <> 'array'
     OR jsonb_array_length(p_delivery_photos) NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'Attach between 1 and 3 photos as proof of delivery.'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_amount, 0) < 0 THEN
    RAISE EXCEPTION 'Amount cannot be negative'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_amount, 0) > 0 THEN
    -- Cash or GCash: the admin is physically receiving this payment right
    -- now, during the same delivery-confirmation call — exactly the pickup
    -- counter's situation. A LATER, out-of-band balance settlement goes
    -- through record_additional_payment() instead, which stays GCash-only.
    IF v_method NOT IN ('cash', 'gcash') THEN
      RAISE EXCEPTION 'Unsupported payment method: %', COALESCE(p_payment_method, '(missing)')
        USING ERRCODE = '22023';
    END IF;

    IF v_method = 'gcash' THEN
      -- All GCash money entered through this RPC is a verified manual
      -- transfer (the automated PayMongo checkout settles through the
      -- webhook's own reconcile RPC, never through this parameter).
      v_ref_norm := public.guard_manual_gcash_payment(p_reference, p_admin_verified_receipt);
      v_gcash_channel := 'manual';
    END IF;
    -- Cash needs no reference, no verification checkbox, and no
    -- gcash_channel — it is recorded as exactly what it is.
  END IF;

  DECLARE
    v_gross_paid_before NUMERIC;
    v_refunded          NUMERIC;
  BEGIN
    SELECT COALESCE(SUM(amount), 0)
      INTO v_gross_paid_before
      FROM public.payment_transactions
     WHERE order_id = p_order_id
       AND payment_status IN ('paid', 'partial');
       
    SELECT COALESCE(SUM(amount), 0)
      INTO v_refunded
      FROM public.payment_refunds
     WHERE order_id = p_order_id
       AND status = 'succeeded';
       
    v_total_paid_before := GREATEST(0, v_gross_paid_before - v_refunded);
  END;

  v_payable            := public.order_payable_amount(v_order.shipping_cost, v_order.discount_amount);
  v_outstanding_before := GREATEST(0, v_payable - v_total_paid_before);

  -- The UI caps at remaining_balance; this is the authoritative equivalent
  -- under the same lock that serializes concurrent admin submissions.
  IF COALESCE(p_amount, 0) > v_outstanding_before + 0.005 THEN
    RAISE EXCEPTION 'Payment amount of ₱% exceeds the outstanding balance of ₱%.',
      TO_CHAR(p_amount, 'FM999999990.00'),
      TO_CHAR(v_outstanding_before, 'FM999999990.00')
      USING ERRCODE = '22023';
  END IF;

  v_total_paid_projected := v_total_paid_before + GREATEST(COALESCE(p_amount, 0), 0);
  v_remaining_projected  := GREATEST(0, v_payable - v_total_paid_projected);
  v_effective_promise_date := COALESCE(p_promised_payment_date, v_order.promised_payment_date);

  IF v_remaining_projected > 0.005 AND v_effective_promise_date IS NULL THEN
    RAISE EXCEPTION
      'Cannot mark order % as delivered with ₱% still owing and no promise date on record. Record a Promise Date or collect the balance first.',
      v_order.tracking_number,
      TO_CHAR(v_remaining_projected, 'FM999999990.00');
  END IF;

  -- Order metadata and ledger insertion remain in this single transaction.
  UPDATE public.orders
     SET delivery_photos       = COALESCE(p_delivery_photos, delivery_photos),
         payment_method        = COALESCE(p_payment_method, payment_method),
         payment_reference     = COALESCE(p_reference, payment_reference),
         promised_payment_date = COALESCE(p_promised_payment_date, promised_payment_date),
         status                = 'Delivered'
   WHERE id = p_order_id;

  IF COALESCE(p_amount, 0) > 0 THEN
    SELECT name INTO v_admin_name FROM public.profiles WHERE id = auth.uid();

    v_paid_after := v_total_paid_before + p_amount;
    v_label := CASE WHEN v_paid_after >= v_payable THEN 'paid' ELSE 'partial' END;

    BEGIN
      INSERT INTO public.payment_transactions (
        order_id, amount, payment_method, payment_status,
        transaction_reference, transaction_reference_normalized, gcash_channel,
        admin_id, admin_name, notes, payment_type, payment_date, receipt_url,
        idempotency_key
      ) VALUES (
        -- Store the actual method collected (was hardcoded 'gcash' for every
        -- row this function wrote, back when gcash was the only value that
        -- could reach here). gcash_channel stays NULL for a cash row.
        p_order_id, p_amount, v_method, v_label,
        p_reference, v_ref_norm, v_gcash_channel,
        auth.uid(), COALESCE(v_admin_name, 'Unknown Admin'), p_notes,
        p_payment_type, p_payment_date, p_receipt_url, p_idempotency_key
      );
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'This GCash reference was already recorded on another order. It cannot be credited again.'
        USING ERRCODE = '23505';
    END;
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  RETURN v_order;
END;
$function$;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_terms_version TEXT;
  v_privacy_version TEXT;
  v_requested_terms_version TEXT;
  v_requested_privacy_version TEXT;
BEGIN
  SELECT version INTO v_terms_version
  FROM public.legal_documents
  WHERE document_type = 'terms_of_service' AND is_current = true;

  SELECT version INTO v_privacy_version
  FROM public.legal_documents
  WHERE document_type = 'privacy_policy' AND is_current = true;

  v_requested_terms_version := NULLIF(trim(NEW.raw_user_meta_data->>'legal_terms_version'), '');
  v_requested_privacy_version := NULLIF(trim(NEW.raw_user_meta_data->>'legal_privacy_version'), '');

  IF v_terms_version IS NULL OR v_privacy_version IS NULL THEN
    RAISE EXCEPTION 'Account creation is temporarily unavailable because legal documents are not published.'
      USING ERRCODE = 'P0001';
  END IF;

  IF COALESCE(NEW.raw_user_meta_data->>'legal_terms_accepted', 'false') <> 'true'
     OR COALESCE(NEW.raw_user_meta_data->>'legal_privacy_accepted', 'false') <> 'true'
     OR v_requested_terms_version IS DISTINCT FROM v_terms_version
     OR v_requested_privacy_version IS DISTINCT FROM v_privacy_version THEN
    RAISE EXCEPTION 'The current Terms of Service and Privacy Policy must be accepted to create an account.'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.profiles (id, email, name, role, created_at, updated_at)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NULLIF(NEW.raw_user_meta_data->>'name', ''), initcap(split_part(NEW.email, '@', 1))),
    'customer',
    now(),
    now()
  )
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.legal_consents (user_id, document_type, document_version, source)
  VALUES
    (NEW.id, 'terms_of_service', v_terms_version, 'registration'),
    (NEW.id, 'privacy_policy', v_privacy_version, 'registration');

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.purge_old_photo_storage_events(retention_days integer DEFAULT 30)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_count INTEGER;
BEGIN
  -- Retention Policy: 30 days is sufficient for operational health metrics.
  DELETE FROM public.photo_storage_events
  WHERE created_at < now() - (retention_days || ' days')::interval;

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
  RETURN v_deleted_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.purge_old_photo_cleanup_queue(retention_days integer DEFAULT 7)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_count INTEGER;
BEGIN
  -- Purge ONLY successfully completed tasks past the retention period.
  -- Pending, running, failed, and retryable tasks are explicitly preserved.
  -- Base the period on completed_at.
  DELETE FROM public.photo_cleanup_queue
  WHERE completed_at IS NOT NULL
    AND completed_at < now() - (retention_days || ' days')::interval;

  GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
  RETURN v_deleted_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_customer_order_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trip_status    TEXT;
  v_departure_date TIMESTAMPTZ;
  v_trip_capacity  NUMERIC;
  v_current_load   NUMERIC;
  v_capacity_allowance CONSTANT NUMERIC := 200;
BEGIN
  IF auth.uid() IS NULL OR public.is_admin() THEN
    RETURN NEW;
  END IF;

  NEW.featured_on_website := false;
  NEW.featured_title := NULL;
  NEW.featured_caption := NULL;
  NEW.featured_image_type := NULL;
  NEW.featured_at := NULL;

  IF NEW.trip_id IS NOT NULL THEN
    SELECT t.status, t.departure_date, t.capacity
      INTO v_trip_status, v_departure_date, v_trip_capacity
      FROM public.trips AS t
     WHERE t.id = NEW.trip_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Selected trip does not exist';
    END IF;

    -- Date-only cutoff: blocks once the PH calendar day has moved past the
    -- scheduled departure date, OR the moment status leaves 'scheduled'
    -- (Start Trip, or an admin cancelling/completing/arriving it) --
    -- whichever comes first. A same-day booking stays open all day no
    -- matter what time it currently is. ph_calendar_day() is the same
    -- PH-timezone helper the duplicate-route unique index already uses.
    IF v_trip_status <> 'scheduled'
       OR public.ph_calendar_day(now()) > public.ph_calendar_day(v_departure_date) THEN
      RAISE EXCEPTION 'This trip is no longer accepting bookings';
    END IF;

    -- ── Capacity enforcement (matches frontend TRIP_CAPACITY_ALLOWANCE_KG) ──
    IF COALESCE(v_trip_capacity, 0) > 0 THEN
      SELECT COALESCE(SUM(COALESCE(o.actual_weight, 0)), 0)
        INTO v_current_load
        FROM public.orders o
       WHERE o.trip_id = NEW.trip_id
         AND o.status <> 'Cancelled';

      IF v_current_load > (v_trip_capacity + v_capacity_allowance) THEN
        RAISE EXCEPTION
          'This trip is full and cannot accept more bookings.';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.order_payable_amount(p_shipping_cost numeric, p_discount_amount numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT GREATEST(COALESCE(p_shipping_cost, 0) - COALESCE(p_discount_amount, 0), 0);
$function$;
CREATE OR REPLACE FUNCTION public.record_pickup_payment(p_order_id uuid, p_actual_weight numeric, p_payment_method text, p_payer_type text DEFAULT 'sender'::text, p_pickup_photos jsonb DEFAULT '[]'::jsonb, p_promised_payment_date date DEFAULT NULL::date, p_amount numeric DEFAULT NULL::numeric, p_reference text DEFAULT NULL::text, p_payment_date date DEFAULT NULL::date, p_receipt_url text DEFAULT NULL::text, p_payment_type text DEFAULT 'Initial Payment'::text, p_notes text DEFAULT 'Initial pickup payment'::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_admin_verified_receipt boolean DEFAULT false, p_discount_amount numeric DEFAULT NULL::numeric, p_discount_reason text DEFAULT NULL::text, p_discount_notes text DEFAULT NULL::text)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order                 public.orders;
  v_admin_name            TEXT;
  v_paid_after            NUMERIC;
  v_label                 TEXT;
  v_ref_norm              TEXT;
  v_method                TEXT := lower(COALESCE(p_payment_method, ''));
  v_has_recorded_payment BOOLEAN;
  -- NEW (20260922150000) — authoritative post-weighing settlement figures.
  v_gross_paid_before     NUMERIC;
  v_refunded_before       NUMERIC;
  v_paid_before           NUMERIC;
  v_payable               NUMERIC;
  v_outstanding           NUMERIC;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  -- ── NEW (20260922150000) — GAP 1: reject a negative collection ─────────
  -- Placed before the row is even locked, so an invalid amount cannot touch
  -- the booking, the discount or the ledger. NULL and 0 fall through
  -- untouched: they are the supported "nothing collected now" cases.
  IF p_amount IS NOT NULL AND p_amount < 0 THEN
    RAISE EXCEPTION 'Payment amount cannot be negative (received ₱%). Enter ₱0.00 or leave it blank if nothing was collected.',
      TO_CHAR(p_amount, 'FM999999990.00')
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order
    FROM public.orders
   WHERE id = p_order_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- Retry of the SAME collection (double-click, or a lost response after the
  -- transaction committed) is a no-op.
  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1
      FROM public.payment_transactions
     WHERE idempotency_key = p_idempotency_key
  ) THEN
    RETURN v_order;
  END IF;

  IF v_order.status NOT IN ('Pending Review', 'Pending', 'Assigned') THEN
    RAISE EXCEPTION 'This order has already been picked up (status: %). Pickup, and any discount applied with it, can no longer be changed.', v_order.status;
  END IF;

  IF COALESCE(p_actual_weight, 0) <= 0 THEN
    RAISE EXCEPTION 'Actual weight must be greater than zero';
  END IF;

  SELECT EXISTS (
    SELECT 1
      FROM public.payment_transactions
     WHERE order_id = p_order_id
       AND payment_status IN ('paid', 'partial')
  ) INTO v_has_recorded_payment;

  -- A payment may have been reconciled by the PayMongo webhook between source
  -- creation and this final pickup confirmation. In that case, an omitted
  -- discount (and the legacy client's explicit 0/null/null payload) means
  -- preserve the already-staged value. A different positive value remains a
  -- forbidden post-payment edit.
  IF v_has_recorded_payment
     AND COALESCE(p_discount_amount, 0) = 0
     AND p_discount_reason IS NULL
     AND p_discount_notes IS NULL
  THEN
    p_discount_amount := v_order.discount_amount;
    p_discount_reason := v_order.discount_reason;
    p_discount_notes := v_order.discount_notes;
  ELSIF v_has_recorded_payment
     AND (
       p_discount_amount IS DISTINCT FROM v_order.discount_amount
       OR p_discount_reason IS DISTINCT FROM v_order.discount_reason
       OR p_discount_notes IS DISTINCT FROM v_order.discount_notes
     )
  THEN
    RAISE EXCEPTION 'This order already has a recorded payment; its discount can no longer be changed.';
  ELSE
    p_discount_amount := COALESCE(p_discount_amount, 0);
  END IF;

  IF COALESCE(p_amount, 0) > 0 AND v_method = 'gcash' THEN
    v_ref_norm := public.guard_manual_gcash_payment(p_reference, p_admin_verified_receipt);
  END IF;

  UPDATE public.orders
     SET actual_weight         = p_actual_weight,
         payment_method        = p_payment_method,
         payer_type            = COALESCE(p_payer_type, payer_type, 'sender'),
         pickup_photos         = COALESCE(p_pickup_photos, pickup_photos),
         promised_payment_date = p_promised_payment_date,
         payment_reference     = COALESCE(p_reference, payment_reference),
         status                = 'Picked Up',
         discount_amount       = ROUND(COALESCE(p_discount_amount, 0), 2),
         discount_reason       = p_discount_reason,
         discount_notes        = p_discount_notes
   WHERE id = p_order_id;

  -- ── NEW (20260922150000) — GAP 2: cap against the FINAL payable ────────
  -- Re-read AFTER the UPDATE: guard_order_update() has now recomputed
  -- shipping_cost from the measured weight and this trip's rate, and the
  -- discount decided above is committed to the row. This, minus payments
  -- already on the ledger net of succeeded refunds, is the authoritative
  -- amount still payable — never a stale remaining_balance and never the
  -- browser's estimate.
  IF COALESCE(p_amount, 0) > 0 THEN
    SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;

    SELECT COALESCE(SUM(amount), 0)
      INTO v_gross_paid_before
      FROM public.payment_transactions
     WHERE order_id = p_order_id
       AND payment_status IN ('paid', 'partial');

    SELECT COALESCE(SUM(amount), 0)
      INTO v_refunded_before
      FROM public.payment_refunds
     WHERE order_id = p_order_id
       AND status = 'succeeded';

    v_paid_before := GREATEST(0, v_gross_paid_before - v_refunded_before);
    v_payable     := public.order_payable_amount(v_order.shipping_cost, v_order.discount_amount);
    v_outstanding := GREATEST(0, v_payable - v_paid_before);

    IF p_amount > v_outstanding + 0.005 THEN
      RAISE EXCEPTION
        'The entered amount of ₱% exceeds the amount still payable by ₱%. Please check the amount. Extra money is not automatically recorded as a tip.',
        TO_CHAR(p_amount, 'FM999999990.00'),
        TO_CHAR(p_amount - v_outstanding, 'FM999999990.00')
        USING ERRCODE = '22023',
              DETAIL  = 'Amount still payable: ' || TO_CHAR(v_outstanding, 'FM999999990.00')
                        || ' (fee ' || TO_CHAR(COALESCE(v_order.shipping_cost, 0), 'FM999999990.00')
                        || ' less discount ' || TO_CHAR(COALESCE(v_order.discount_amount, 0), 'FM999999990.00')
                        || ' less payments already received ' || TO_CHAR(v_paid_before, 'FM999999990.00') || ').',
              HINT    = 'Correct the amount to the amount still payable, or record the excess outside this booking.';
    END IF;
  END IF;

  IF COALESCE(p_amount, 0) > 0 THEN
    SELECT name INTO v_admin_name
      FROM public.profiles
     WHERE id = auth.uid();

    SELECT COALESCE(SUM(amount), 0) + p_amount
      INTO v_paid_after
      FROM public.payment_transactions
     WHERE order_id = p_order_id
       AND payment_status IN ('paid', 'partial');

    SELECT CASE
             WHEN v_paid_after >= public.order_payable_amount(shipping_cost, discount_amount) THEN 'paid'
             ELSE 'partial'
           END
      INTO v_label
      FROM public.orders
     WHERE id = p_order_id;

    BEGIN
      INSERT INTO public.payment_transactions (
        order_id, amount, payment_method, payment_status,
        transaction_reference, transaction_reference_normalized, gcash_channel,
        admin_id, admin_name, notes, payment_type, payment_date, receipt_url,
        idempotency_key
      ) VALUES (
        p_order_id, p_amount, p_payment_method, v_label,
        p_reference, v_ref_norm, CASE WHEN v_ref_norm IS NOT NULL THEN 'manual' END,
        auth.uid(), COALESCE(v_admin_name, 'Unknown Admin'), p_notes,
        p_payment_type, p_payment_date, p_receipt_url, p_idempotency_key
      )
      ON CONFLICT (transaction_reference) WHERE transaction_reference IS NOT NULL
      DO NOTHING;
    EXCEPTION WHEN unique_violation THEN
      RAISE EXCEPTION 'This GCash reference was already recorded on another order. It cannot be credited again.'
        USING ERRCODE = '23505';
    END;
  END IF;

  SELECT * INTO v_order
    FROM public.orders
   WHERE id = p_order_id;
  RETURN v_order;
END;
$function$;
CREATE OR REPLACE FUNCTION public.notify_admins_of_contact_inquiry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  SELECT
    p.id,
    'New Contact Inquiry',
    format(
      'Inquiry from %s: %s',
      COALESCE(NULLIF(btrim(NEW.name), ''), 'Visitor'),
      left(COALESCE(btrim(NEW.message), ''), 80)
    ),
    'inquiry',
    NEW.id
  FROM public.profiles AS p
  WHERE p.role = 'admin';

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.trigger_daily_payment_reminders()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'vault'
AS $function$
DECLARE
  v_project_url  text;
  v_service_key  text;
BEGIN
  SELECT decrypted_secret INTO v_project_url FROM vault.decrypted_secrets WHERE name = 'project_url';
  SELECT decrypted_secret INTO v_service_key FROM vault.decrypted_secrets WHERE name = 'service_role_key';

  IF v_project_url IS NULL OR v_service_key IS NULL THEN
    RAISE WARNING 'trigger_daily_payment_reminders: project_url / service_role_key not found in Vault — skipping. See the migration comment for the one-time setup step.';
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := v_project_url || '/functions/v1/process-daily-reminders',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := '{}'::jsonb
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.reassign_trip(p_order_id uuid, p_new_trip_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_trip_id UUID;
  v_admin_id UUID;
  v_reassignment_history JSONB;
BEGIN
  v_admin_id := auth.uid();
  IF v_admin_id IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Only administrators can reassign trips';
  END IF;

  -- Get current trip
  SELECT trip_id INTO v_old_trip_id
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF v_old_trip_id = p_new_trip_id THEN
    RAISE EXCEPTION 'The new trip must be different from the current trip';
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  -- Update the order's trip_id and append to JSONB reassignment_history
  UPDATE public.orders
  SET 
    trip_id = p_new_trip_id,
    reassignment_history = COALESCE(reassignment_history, '[]'::jsonb) || jsonb_build_object(
      'id', gen_random_uuid(),
      'previous_trip_id', v_old_trip_id,
      'new_trip_id', p_new_trip_id,
      'reason', p_reason,
      'admin_id', v_admin_id,
      'created_at', now()
    )
  WHERE id = p_order_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_push_device_registration(p_device_id text, p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_device_id TEXT := NULLIF(btrim(p_device_id), '');
  v_token TEXT := NULLIF(btrim(p_token), '');
  v_subscription JSONB;
  v_endpoint TEXT;
  v_p256dh TEXT;
  v_auth TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_device_id IS NULL OR v_token IS NULL THEN
    RAISE EXCEPTION 'A device ID and push token are required';
  END IF;

  IF char_length(v_device_id) < 8
     OR char_length(v_device_id) > 200
     OR v_device_id ~ '[[:space:][:cntrl:]]'
     OR v_device_id !~ '^[A-Za-z0-9._:-]+$' THEN
    RAISE EXCEPTION 'Device ID is not valid';
  END IF;

  IF left(v_token, 8) = 'webpush:' THEN
    IF char_length(v_token) > 6000 THEN
      RAISE EXCEPTION 'Web Push subscription is too long';
    END IF;

    BEGIN
      v_subscription := substring(v_token FROM 9)::JSONB;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Web Push subscription is not valid JSON';
    END;

    IF jsonb_typeof(v_subscription) <> 'object'
       OR jsonb_typeof(v_subscription->'keys') <> 'object' THEN
      RAISE EXCEPTION 'Web Push subscription has an invalid shape';
    END IF;

    v_endpoint := v_subscription->>'endpoint';
    v_p256dh := v_subscription->'keys'->>'p256dh';
    v_auth := v_subscription->'keys'->>'auth';

    -- CargoExpress currently creates native Web Push subscriptions only in
    -- Safari/WebKit. Restrict egress to Apple's documented push-service domain.
    IF v_endpoint IS NULL
       OR v_endpoint !~ '^https://([A-Za-z0-9-]+\.)+push\.apple\.com(?::443)?/[^[:space:]#]+$' THEN
      RAISE EXCEPTION 'Web Push endpoint is not an approved Apple push endpoint';
    END IF;

    -- PushSubscription.toJSON() emits unpadded base64url: a 65-byte P-256
    -- public key is 87 characters and a 16-byte auth secret is 22.
    IF v_p256dh IS NULL OR v_p256dh !~ '^[A-Za-z0-9_-]{87}$' THEN
      RAISE EXCEPTION 'Web Push p256dh key is not valid';
    END IF;
    IF v_auth IS NULL OR v_auth !~ '^[A-Za-z0-9_-]{22}$' THEN
      RAISE EXCEPTION 'Web Push auth key is not valid';
    END IF;
  ELSE
    -- FCM registration tokens are opaque. Enforce conservative structural
    -- limits without assuming a provider-internal fixed length.
    IF char_length(v_token) < 20
       OR char_length(v_token) > 4096
       OR v_token ~ '[[:space:][:cntrl:]]' THEN
      RAISE EXCEPTION 'FCM token is not valid';
    END IF;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(v_device_id));

  DELETE FROM public.user_device_tokens
  WHERE device_id = v_device_id
     OR token = v_token;

  INSERT INTO public.user_device_tokens (user_id, device_id, token)
  VALUES (auth.uid(), v_device_id, v_token);
END;
$function$;
CREATE OR REPLACE FUNCTION public.remove_push_device_registration(p_device_id text DEFAULT NULL::text, p_token text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_device_id TEXT := NULLIF(btrim(p_device_id), '');
  v_token TEXT := NULLIF(btrim(p_token), '');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_device_id IS NULL AND v_token IS NULL THEN
    RAISE EXCEPTION 'A device ID or push token is required';
  END IF;

  DELETE FROM public.user_device_tokens
  WHERE user_id = auth.uid()
    AND (
      (v_device_id IS NOT NULL AND device_id = v_device_id)
      OR (v_token IS NOT NULL AND token = v_token)
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_admin_customers(p_page integer DEFAULT 1, p_per_page integer DEFAULT 15, p_search text DEFAULT ''::text, p_status_filter text DEFAULT 'all'::text, p_province text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text)
 RETURNS TABLE(id uuid, name text, email text, phone text, address_city text, address_province text, created_at timestamp with time zone, total_bookings bigint, outstanding_balance numeric, last_booking_at timestamp with time zone, pending_bookings bigint, active_bookings bigint, directory_status text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_page INTEGER := GREATEST(COALESCE(p_page, 1), 1);
  v_per_page INTEGER := LEAST(GREATEST(COALESCE(p_per_page, 15), 1), 100);
  v_search TEXT := btrim(COALESCE(p_search, ''));
  v_filter TEXT := lower(btrim(COALESCE(p_status_filter, 'all')));
  v_province TEXT := NULLIF(btrim(COALESCE(p_province, '')), '');
  v_sort TEXT := lower(btrim(COALESCE(p_sort, 'newest')));
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  IF char_length(v_search) > 100 THEN
    RAISE EXCEPTION 'Search must be 100 characters or less' USING ERRCODE = '22023';
  END IF;

  IF v_province IS NOT NULL AND char_length(v_province) > 255 THEN
    RAISE EXCEPTION 'Province filter is too long' USING ERRCODE = '22023';
  END IF;

  IF v_filter NOT IN ('all', 'with_balance', 'pending', 'active', 'no_bookings') THEN
    RAISE EXCEPTION 'Unsupported customer filter' USING ERRCODE = '22023';
  END IF;

  IF v_sort NOT IN ('name_asc', 'newest', 'oldest', 'most_bookings', 'highest_balance', 'recent_booking') THEN
    RAISE EXCEPTION 'Unsupported customer sort' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH rollup AS (
    SELECT
      p.id,
      p.name::TEXT,
      p.email::TEXT,
      p.phone::TEXT,
      p.address_city::TEXT,
      p.address_province::TEXT,
      p.created_at,
      count(o.id)::BIGINT AS total_bookings,
      round(COALESCE(sum(
        CASE
          WHEN o.id IS NULL OR o.status = 'Cancelled' THEN 0::NUMERIC
          ELSE greatest(
            COALESCE(o.shipping_cost, 0)
              - COALESCE(o.discount_amount, 0)
              - COALESCE(o.amount_paid, 0),
            0::NUMERIC
          )
        END
      ), 0::NUMERIC), 2) AS outstanding_balance,
      max(o.created_at) AS last_booking_at,
      count(o.id) FILTER (
        WHERE o.status IN ('Pending Review', 'Pending', 'Pending Cancellation')
      )::BIGINT AS pending_bookings,
      count(o.id) FILTER (
        WHERE o.status IN ('Assigned', 'Picked Up', 'In Transit', 'Arrived at Hub', 'Out for Delivery')
      )::BIGINT AS active_bookings
    FROM public.profiles p
    LEFT JOIN public.orders o ON o.user_id = p.id
    WHERE p.role = 'customer'
    GROUP BY p.id, p.name, p.email, p.phone, p.address_city, p.address_province, p.created_at
  ), filtered AS (
    SELECT
      r.*,
      CASE
        WHEN r.outstanding_balance > 0 THEN 'with_balance'
        WHEN r.pending_bookings > 0 THEN 'pending'
        WHEN r.active_bookings > 0 THEN 'active'
        ELSE 'inactive'
      END AS directory_status
    FROM rollup r
    WHERE (
      v_search = ''
      OR r.name ILIKE '%' || v_search || '%'
      OR r.email ILIKE '%' || v_search || '%'
      OR COALESCE(r.phone, '') ILIKE '%' || v_search || '%'
      OR COALESCE(r.address_city, '') ILIKE '%' || v_search || '%'
      OR COALESCE(r.address_province, '') ILIKE '%' || v_search || '%'
    )
    AND (v_province IS NULL OR lower(btrim(COALESCE(r.address_province, ''))) = lower(v_province))
    AND CASE v_filter
      WHEN 'with_balance' THEN r.outstanding_balance > 0
      WHEN 'pending' THEN r.pending_bookings > 0
      WHEN 'active' THEN r.active_bookings > 0
      WHEN 'no_bookings' THEN r.total_bookings = 0
      ELSE true
    END
  )
  SELECT
    f.id,
    f.name,
    f.email,
    f.phone,
    f.address_city,
    f.address_province,
    f.created_at,
    f.total_bookings,
    f.outstanding_balance,
    f.last_booking_at,
    f.pending_bookings,
    f.active_bookings,
    f.directory_status,
    count(*) OVER()::BIGINT AS total_count
  FROM filtered f
  ORDER BY
    CASE WHEN v_sort = 'name_asc' THEN lower(f.name) END ASC NULLS LAST,
    CASE WHEN v_sort = 'newest' THEN f.created_at END DESC NULLS LAST,
    CASE WHEN v_sort = 'oldest' THEN f.created_at END ASC NULLS LAST,
    CASE WHEN v_sort = 'most_bookings' THEN f.total_bookings END DESC NULLS LAST,
    CASE WHEN v_sort = 'highest_balance' THEN f.outstanding_balance END DESC NULLS LAST,
    CASE WHEN v_sort = 'recent_booking' THEN f.last_booking_at END DESC NULLS LAST,
    lower(f.name) ASC,
    f.id ASC
  LIMIT v_per_page
  OFFSET (v_page - 1) * v_per_page;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_admin_customer_provinces()
 RETURNS TABLE(province text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT DISTINCT btrim(p.address_province)::TEXT
  FROM public.profiles p
  WHERE p.role = 'customer'
    AND NULLIF(btrim(p.address_province), '') IS NOT NULL
  ORDER BY 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_contact_inquiry_push(p_inquiry_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_dispatched_at TIMESTAMPTZ;
  v_started_at TIMESTAMPTZ;
  v_claim_id UUID := gen_random_uuid();
BEGIN
  SELECT push_dispatched_at, push_dispatch_started_at
    INTO v_dispatched_at, v_started_at
    FROM public.contact_inquiries
   WHERE id = p_inquiry_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inquiry not found';
  END IF;

  IF v_dispatched_at IS NOT NULL THEN
    RETURN NULL;
  END IF;

  IF v_started_at IS NOT NULL AND v_started_at > now() - INTERVAL '5 minutes' THEN
    RETURN NULL;
  END IF;

  UPDATE public.contact_inquiries
     SET push_dispatch_started_at = now(),
         push_dispatch_claim_id = v_claim_id
   WHERE id = p_inquiry_id;

  RETURN v_claim_id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.complete_contact_inquiry_push(p_inquiry_id uuid, p_claim_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  UPDATE public.contact_inquiries
     SET push_dispatched_at = now(),
         push_dispatch_started_at = NULL,
         push_dispatch_claim_id = NULL
   WHERE id = p_inquiry_id
     AND push_dispatch_claim_id = p_claim_id
     AND push_dispatched_at IS NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reconcile_paymongo_payment_failure(p_source_id text, p_payment_id text DEFAULT NULL::text, p_failure_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_attempt public.payment_attempts%ROWTYPE;
BEGIN
  IF p_source_id IS NOT NULL AND p_source_id !~ '^src_[A-Za-z0-9_-]{4,128}$' THEN
    RAISE EXCEPTION 'Invalid PayMongo source id' USING ERRCODE = '22023';
  END IF;
  IF p_payment_id IS NOT NULL AND p_payment_id !~ '^pay_[A-Za-z0-9_-]{4,128}$' THEN
    RAISE EXCEPTION 'Invalid PayMongo payment id' USING ERRCODE = '22023';
  END IF;
  IF p_source_id IS NULL AND p_payment_id IS NULL THEN
    RETURN jsonb_build_object('linked', FALSE, 'message', 'No provider identifier was supplied');
  END IF;

  SELECT * INTO v_attempt
  FROM public.payment_attempts
  WHERE (p_source_id IS NOT NULL AND source_id = p_source_id)
     OR (p_payment_id IS NOT NULL AND payment_id = p_payment_id)
  ORDER BY CASE WHEN source_id = p_source_id THEN 0 ELSE 1 END, created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('linked', FALSE, 'message', 'No payment attempt found');
  END IF;
  IF v_attempt.status = 'reconciled' THEN
    RETURN jsonb_build_object('linked', TRUE, 'changed', FALSE, 'message', 'Paid attempt is already reconciled');
  END IF;

  UPDATE public.payment_attempts
  SET status = 'failed',
      payment_id = COALESCE(p_payment_id, payment_id),
      payment_status = 'failed',
      last_error = LEFT(COALESCE(NULLIF(BTRIM(p_failure_message), ''), 'PayMongo reported payment.failed'), 1000)
  WHERE id = v_attempt.id
  RETURNING * INTO v_attempt;

  RETURN jsonb_build_object(
    'linked', TRUE,
    'changed', TRUE,
    'order_id', v_attempt.order_id,
    'payment_id', v_attempt.payment_id
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_chat_message_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actual_role TEXT;
BEGIN
  SELECT role INTO actual_role FROM public.profiles WHERE id = auth.uid();
  IF actual_role IS NULL THEN
    RAISE EXCEPTION 'Profile not found';
  END IF;

  NEW.sender_id := auth.uid();

  IF actual_role = 'customer' AND NEW.sender_role = 'bot' THEN
    NEW.sender_role := 'bot';
  ELSE
    NEW.sender_role := actual_role;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.release_contact_inquiry_push(p_inquiry_id uuid, p_claim_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  UPDATE public.contact_inquiries
     SET push_dispatch_started_at = NULL,
         push_dispatch_claim_id = NULL
   WHERE id = p_inquiry_id
     AND push_dispatch_claim_id = p_claim_id
     AND push_dispatched_at IS NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.is_standard_service_area_province(p_province text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(p_province, '') IN (
    'Bohol', 'Metro Manila', 'Cavite', 'Batangas', 'Laguna', 'Bulacan'
  );
$function$;
CREATE OR REPLACE FUNCTION private.trigger_paymongo_refund_recovery()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_project_url TEXT;
  v_service_key TEXT;
BEGIN
  SELECT decrypted_secret INTO v_project_url
  FROM vault.decrypted_secrets
  WHERE name = 'project_url'
  LIMIT 1;

  SELECT decrypted_secret INTO v_service_key
  FROM vault.decrypted_secrets
  WHERE name = 'service_role_key'
  LIMIT 1;

  IF v_project_url IS NULL OR v_service_key IS NULL THEN
    RAISE WARNING 'PayMongo refund recovery skipped because project_url/service_role_key are not configured in Vault.';
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := rtrim(v_project_url, '/') || '/functions/v1/paymongo-refund-recovery',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body := jsonb_build_object('limit', 15),
    timeout_milliseconds := 120000
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_payment_transaction_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tracking_number TEXT;
  v_action TEXT;
  v_admin_name TEXT;
  v_method_key TEXT;
  v_channel_key TEXT;
  v_method_label TEXT;
BEGIN
  SELECT o.tracking_number
    INTO v_tracking_number
    FROM public.orders o
   WHERE o.id = NEW.order_id;

  v_action := CASE
    WHEN lower(COALESCE(NEW.payment_type, '')) LIKE '%initial%'
      THEN 'Initial Payment Recorded'
    WHEN lower(COALESCE(NEW.payment_type, '')) LIKE '%settlement%'
      OR lower(COALESCE(NEW.payment_status, '')) = 'paid'
      THEN 'Payment Completed'
    ELSE 'Additional Payment Recorded'
  END;

  SELECT COALESCE(
           NULLIF(btrim(p.name), ''),
           NULLIF(btrim(NEW.admin_name), ''),
           CASE WHEN NEW.admin_id IS NULL THEN 'System' ELSE 'Unknown Admin' END
         )
    INTO v_admin_name
    FROM (SELECT 1) seed
    LEFT JOIN public.profiles p ON p.id = NEW.admin_id;

  v_method_key := lower(COALESCE(NULLIF(btrim(NEW.payment_method), ''), ''));
  v_channel_key := lower(COALESCE(NULLIF(btrim(NEW.gcash_channel), ''), ''));
  v_method_label := CASE
    WHEN v_method_key = 'gcash' AND v_channel_key = 'manual'
      THEN 'Direct GCash transfer (staff verified)'
    WHEN v_method_key = 'gcash' AND v_channel_key = 'paymongo'
      THEN 'GCash online payment (automatically verified)'
    WHEN v_method_key = 'gcash' THEN 'GCash'
    WHEN v_method_key = 'cash' THEN 'Cash'
    WHEN v_method_key = '' THEN 'Unspecified method'
    ELSE initcap(replace(v_method_key, '_', ' '))
  END;

  INSERT INTO public.activity_logs (
    admin_id, admin_name, module, action, record_type, record_id, record_ref,
    new_value, details, created_at
  ) VALUES (
    NEW.admin_id,
    v_admin_name,
    'Payments',
    v_action,
    'payment',
    NEW.id,
    v_tracking_number,
    jsonb_build_object(
      'amount', NEW.amount,
      'payment_method', NEW.payment_method,
      'gcash_channel', NEW.gcash_channel,
      'payment_status', NEW.payment_status,
      'payment_type', NEW.payment_type,
      'payment_date', NEW.payment_date
    ),
    'Payment recorded: ' || chr(8369) || to_char(NEW.amount, 'FM999,999,999,990.00') ||
      ' via ' || v_method_label || '. ' ||
      CASE
        WHEN lower(COALESCE(NEW.payment_status, '')) = 'paid' THEN 'Payment is complete.'
        WHEN lower(COALESCE(NEW.payment_status, '')) = 'partial' THEN 'A balance is still due.'
        ELSE 'Payment status: ' || COALESCE(NEW.payment_status, 'not specified') || '.'
      END,
    COALESCE(NEW.created_at, now())
  );

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_featured_deliveries()
 RETURNS TABLE(id uuid, featured_title text, featured_caption text, featured_image_type text, featured_at timestamp with time zone, featured_photo text, receiver_city text, receiver_province text, delivered_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    o.id,
    o.featured_title,
    o.featured_caption,
    o.featured_image_type,
    o.featured_at,
    CASE
      WHEN o.featured_image_type = 'delivery'
           AND jsonb_array_length(COALESCE(o.delivery_photos, '[]'::jsonb)) > 0
        THEN o.delivery_photos ->> 0
      WHEN jsonb_array_length(COALESCE(o.pickup_photos, '[]'::jsonb)) > 0
        THEN o.pickup_photos ->> 0
      ELSE NULL
    END AS featured_photo,
    o.receiver_city,
    o.receiver_province,
    (
      SELECT MIN(e.changed_at)
      FROM public.order_status_events e
      WHERE e.order_id = o.id AND e.status = 'Delivered'
    ) AS delivered_at
  FROM public.orders o
  WHERE o.featured_on_website = true
    AND o.featured_title IS NOT NULL
    AND btrim(o.featured_title) <> ''
  ORDER BY o.featured_at DESC NULLS LAST;
$function$;
CREATE OR REPLACE FUNCTION public.add_announcement_comment(p_announcement_id uuid, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id  UUID := auth.uid();
  v_name     TEXT;
  v_text     TEXT := btrim(COALESCE(p_text, ''));
  v_comment  JSONB;
  v_comments JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'You must be signed in to comment.' USING ERRCODE = '42501';
  END IF;

  IF v_text = '' THEN
    RAISE EXCEPTION 'Comment cannot be empty.' USING ERRCODE = '22023';
  END IF;

  IF length(v_text) > 500 THEN
    RAISE EXCEPTION 'Comment must be 500 characters or less.' USING ERRCODE = '22023';
  END IF;

  -- The display name is read here, not passed in, for the same reason the id
  -- is: it is the author's identity and the client does not get to assert it.
  -- A profile with no name is left as the honest placeholder rather than
  -- backfilled with an email or an id.
  SELECT name INTO v_name FROM profiles WHERE id = v_user_id;

  v_comment := jsonb_build_object(
    'id',         gen_random_uuid(),
    'user_id',    v_user_id,
    'name',       COALESCE(NULLIF(btrim(v_name), ''), 'Customer'),
    'text',       v_text,
    'created_at', to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  );

  -- Concurrent appends are safe: UPDATE locks the row and, under READ
  -- COMMITTED, the second writer re-reads the freshly committed array before
  -- concatenating. A read-then-write from the client could not make that
  -- promise — it would lose whichever comment landed first.
  UPDATE announcements
     SET comments = COALESCE(comments, '[]'::jsonb) || jsonb_build_array(v_comment)
   WHERE id = p_announcement_id
   RETURNING comments INTO v_comments;

  IF v_comments IS NULL THEN
    RAISE EXCEPTION 'Announcement not found.' USING ERRCODE = 'P0002';
  END IF;

  RETURN v_comments;
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_customer_chat_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.sender_role = 'customer' THEN
    IF (SELECT count(*) FROM chat_messages WHERE conversation_id = NEW.conversation_id) = 1 THEN
      INSERT INTO activity_logs (admin_name, module, action, record_type, record_id, record_ref, details, created_at)
      SELECT profiles.name, 'Chat', 'Customer Started Conversation', 'conversation', NEW.conversation_id, profiles.name, 'Customer initiated a new support conversation.', NOW()
      FROM conversations JOIN profiles ON conversations.customer_id = profiles.id
      WHERE conversations.id = NEW.conversation_id;
    ELSE
      INSERT INTO activity_logs (admin_name, module, action, record_type, record_id, record_ref, details, created_at)
      SELECT profiles.name, 'Chat', 'Customer Sent Message', 'conversation', NEW.conversation_id, profiles.name, 'Customer replied.', NOW()
      FROM conversations JOIN profiles ON conversations.customer_id = profiles.id
      WHERE conversations.id = NEW.conversation_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_contact_inquiry_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ 
BEGIN
  IF NEW.ip IS NOT NULL AND btrim(NEW.ip) <> '' THEN
    IF (SELECT COUNT(*) FROM public.contact_inquiries WHERE ip = NEW.ip AND created_at > now() - interval '10 minutes') >= 5 THEN
      RAISE EXCEPTION 'Too many inquiries from your network. Please wait 10 minutes before submitting again.' USING ERRCODE = '42501';
    END IF;
  ELSE
    IF (SELECT COUNT(*) FROM public.contact_inquiries WHERE phone = NEW.phone AND created_at > now() - interval '10 minutes') >= 3 THEN
      RAISE EXCEPTION 'Too many inquiries from this phone number. Please wait 10 minutes before submitting again.' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF (SELECT COUNT(*) FROM public.contact_inquiries WHERE created_at > now() - interval '1 minute') >= 15 THEN
    RAISE EXCEPTION 'Too many inquiries right now. Please try again in a minute.' USING ERRCODE = '42501';
  END IF;
  NEW.name := btrim(NEW.name);
  NEW.phone := btrim(NEW.phone);
  NEW.message := btrim(NEW.message);
  IF NEW.ip IS NOT NULL THEN NEW.ip := btrim(NEW.ip); END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.stamp_conversation_resolved_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN IF NEW.status = 'resolved' AND OLD.status IS DISTINCT FROM 'resolved' THEN NEW.resolved_at := COALESCE(NEW.resolved_at, now()); ELSIF NEW.status <> 'resolved' THEN NEW.resolved_at := NULL; END IF; RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.stamp_inquiry_service_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status THEN IF NEW.status <> 'new' THEN NEW.first_response_at := COALESCE(NEW.first_response_at, now()); END IF; IF NEW.status = 'resolved' THEN NEW.resolved_at := COALESCE(NEW.resolved_at, now()); ELSE NEW.resolved_at := NULL; END IF; END IF; RETURN NEW; END; $function$;
CREATE OR REPLACE FUNCTION public.review_order_cancellation(p_order_id uuid, p_approve boolean, p_notes text DEFAULT NULL::text)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.orders;
  v_restore varchar;
  v_notes text;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin privileges required' USING ERRCODE = '42501';
  END IF;

  v_notes := NULLIF(trim(p_notes), '');

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;
  IF v_order.status != 'Pending Cancellation' THEN
    RAISE EXCEPTION 'Order is not pending cancellation';
  END IF;

  v_restore := COALESCE(v_order.cancellation_details->>'previous_status', 'Pending');

  UPDATE public.orders
     SET status = CASE WHEN p_approve THEN 'Cancelled' ELSE v_restore END,
         cancellation_details = COALESCE(v_order.cancellation_details, '{}'::jsonb)
           || jsonb_strip_nulls(jsonb_build_object(
             'reviewed_at', now(),
             'reviewed_by', auth.uid(),
             'review_notes', v_notes
           ))
   WHERE id = p_order_id
   RETURNING * INTO v_order;

  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  VALUES (v_order.user_id,
          CASE WHEN p_approve THEN 'Cancellation Approved' ELSE 'Cancellation Declined' END,
          CASE WHEN p_approve
               THEN 'Order ' || v_order.tracking_number || ' has been cancelled as you requested.'
               ELSE 'Order ' || v_order.tracking_number || ' was not cancelled and is back to '
                    || chr(34) || v_restore || chr(34) || '.'
          END
          || COALESCE(' Note: ' || v_notes, ''),
          'order_update', v_order.id);

  INSERT INTO public.activity_logs (
    module, action, record_type, record_id, record_ref,
    previous_value, new_value, details
  )
  VALUES ('Orders',
          CASE WHEN p_approve THEN 'Cancellation Approved' ELSE 'Cancellation Rejected' END,
          'order',
          v_order.id,
          v_order.tracking_number,
          jsonb_build_object('status', 'Pending Cancellation'),
          jsonb_build_object('status', v_order.status),
          CASE WHEN p_approve
               THEN 'Approved the customer''s cancellation request; order cancelled.'
               ELSE 'Rejected the customer''s cancellation request; order restored to '
                    || chr(34) || v_restore || chr(34) || '.'
          END
          || COALESCE(' Note: ' || v_notes, '')
          || COALESCE(' Customer''s stated reason: ' || (v_order.cancellation_details->>'reason'), ''));

  RETURN v_order;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_chat_message_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Service work has no end-user JWT. Admins retain their existing full
  -- UPDATE policy. The remaining path is a customer read acknowledgement.
  IF auth.uid() IS NULL OR public.is_admin() THEN
    RETURN NEW;
  END IF;

  IF OLD.sender_role IS DISTINCT FROM 'admin'
     OR NOT EXISTS (
       SELECT 1
       FROM public.conversations
       WHERE id = OLD.conversation_id
         AND customer_id = auth.uid()
     )
  THEN
    RAISE EXCEPTION 'Customers may update only admin messages in their own conversations'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id
     OR NEW.sender_id IS DISTINCT FROM OLD.sender_id
     OR NEW.sender_role IS DISTINCT FROM OLD.sender_role
     OR NEW.message IS DISTINCT FROM OLD.message
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'Customers may change only the read state of a chat message'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.is_read IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Customers may only mark admin messages as read'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_admins_of_order_cancelled()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_reason TEXT := NULLIF(btrim(COALESCE(NEW.cancellation_details->>'reason', '')), '');
BEGIN
  INSERT INTO public.notifications (user_id, title, message, type, reference_id)
  SELECT
    p.id,
    'Booking Cancelled',
    format(
      'Order %s has been cancelled.%s',
      NEW.tracking_number,
      CASE WHEN v_reason IS NULL THEN '' ELSE ' Reason: ' || v_reason END
    ),
    'order_update',
    NEW.id
  FROM public.profiles AS p
  WHERE p.role = 'admin'
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.text_to_photo_ref(p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF p_text IS NULL OR btrim(p_text) = '' THEN
    RETURN NULL;
  END IF;
  IF left(btrim(p_text), 1) = '{' THEN
    BEGIN
      RETURN btrim(p_text)::jsonb;
    EXCEPTION WHEN OTHERS THEN
      RETURN to_jsonb(p_text);
    END;
  END IF;
  RETURN to_jsonb(p_text);
END;
$function$;
CREATE OR REPLACE FUNCTION public.classify_evidence_photo_ref(p_ref jsonb)
 RETURNS TABLE(provider text, storage_path text, size_bytes bigint, content_type text, taken_at timestamp with time zone)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_path text;
BEGIN
  IF p_ref IS NULL THEN
    RETURN;
  END IF;

  IF jsonb_typeof(p_ref) = 'object' THEN
    IF (p_ref ->> 'type') = 'firestore_fallback' OR p_ref ? 'firestore_path' THEN
      v_path := p_ref ->> 'firestore_path';
      IF v_path ~ '^photoFallbacks/[^/]+$' THEN
        RETURN QUERY SELECT
          'firebase'::text,
          v_path,
          NULLIF(p_ref ->> 'size_bytes', '')::bigint,
          p_ref ->> 'content_type',
          NULLIF(p_ref ->> 'created_at', '')::timestamptz;
      END IF;
      RETURN;
    END IF;

    IF (p_ref ->> 'type') = 'supabase_storage' OR p_ref ? 'path' THEN
      v_path := p_ref ->> 'path';
      -- Includes receipts/ so receipt descriptors classify correctly for
      -- display; deletion eligibility for receipts is still always denied,
      -- decided separately in delete_evidence_photos(), not by this shape
      -- check.
      IF v_path ~ '^(pickup-proofs|delivery-proofs|receipts)/[^/]+/.+' THEN
        RETURN QUERY SELECT
          'supabase'::text,
          v_path,
          NULLIF(p_ref ->> 'size_bytes', '')::bigint,
          p_ref ->> 'content_type',
          NULLIF(p_ref ->> 'created_at', '')::timestamptz;
      END IF;
      RETURN;
    END IF;

    RETURN; -- direct_url / embedded / unrecognized object shape
  END IF;

  IF jsonb_typeof(p_ref) = 'string' THEN
    v_path := p_ref #>> '{}';
    IF v_path IS NULL OR btrim(v_path) = '' THEN
      RETURN;
    END IF;
    v_path := btrim(v_path);

    -- Legacy double-encoded case: a jsonb array element that is itself a
    -- JSON-serialized descriptor string (mirrors photoReference.js's
    -- parseJsonReference, applied there to every string element regardless
    -- of source column).
    IF left(v_path, 1) = '{' THEN
      BEGIN
        RETURN QUERY SELECT * FROM public.classify_evidence_photo_ref(v_path::jsonb);
      EXCEPTION WHEN OTHERS THEN
        NULL; -- not actually valid JSON — treated as unclassified, same as any other unrecognized shape
      END;
      RETURN;
    END IF;

    IF v_path ~ '^photoFallbacks/[^/]+$' THEN
      RETURN QUERY SELECT 'firebase'::text, v_path, NULL::bigint, NULL::text, NULL::timestamptz;
      RETURN;
    END IF;
    IF v_path ~ '^https?:' OR v_path ~ '^data:image/' OR v_path ~ '^(blob:|error:)' THEN
      RETURN; -- legacy absolute URL / embedded image — not path-addressable
    END IF;

    v_path := regexp_replace(v_path, '^/+', '');
    IF v_path ~ '^(pickup-proofs|delivery-proofs|receipts)/[^/]+/.+' THEN
      RETURN QUERY SELECT 'supabase'::text, v_path, NULL::bigint, NULL::text, NULL::timestamptz;
    END IF;
    RETURN;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.purge_old_activity_logs()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  DELETE FROM public.activity_logs
  WHERE created_at < now() - interval '7 days';
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_public_business_profile()
 RETURNS TABLE(name text, smart_phone text, globe_phone text, facebook_link text, manila_address text, bohol_address text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    c.name,
    c.smart_phone,
    c.globe_phone,
    c.facebook AS facebook_link,
    c.manila_address,
    c.bohol_address
  FROM public.company_information c
  WHERE c.id = '00000000-0000-0000-0000-000000000001'
  LIMIT 1;
$function$;
CREATE OR REPLACE FUNCTION public.sync_auth_email_to_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_old_email TEXT := lower(btrim(COALESCE(OLD.email, '')));
  v_new_email TEXT := lower(btrim(COALESCE(NEW.email, '')));
  v_wants_announcements BOOLEAN := false;
BEGIN
  IF NEW.email IS DISTINCT FROM OLD.email THEN
    -- Read the account preference before changing the profile row.  It is a
    -- fallback only when neither address already has a preference row; an
    -- explicit existing unsubscribe always remains authoritative.
    SELECT COALESCE(p.wants_announcements, false)
      INTO v_wants_announcements
      FROM public.profiles AS p
     WHERE p.id = NEW.id;

    UPDATE public.profiles
       SET email = NEW.email,
           updated_at = NOW()
     WHERE id = NEW.id;

    IF v_old_email <> ''
       AND v_old_email IS DISTINCT FROM v_new_email
       AND v_new_email <> ''
       AND v_new_email ~ '^[^\s@]+@[^\s@]+\.[^\s@]+$'
       AND char_length(v_new_email) <= 320 THEN
      -- If the destination already has a preference (for example, the user
      -- previously opted out with that address), keep that newer explicit
      -- choice.  Otherwise move the old row without changing its source,
      -- actor, or timestamp history.
      INSERT INTO public.email_subscriptions
        (email, subscribed, source, updated_by, updated_at, created_at)
      SELECT v_new_email, es.subscribed, es.source, es.updated_by,
             es.updated_at, es.created_at
        FROM public.email_subscriptions AS es
       WHERE es.email = v_old_email
      ON CONFLICT (email) DO NOTHING;

      DELETE FROM public.email_subscriptions
       WHERE email = v_old_email;

      -- A registered account can have opted in before the subscription table
      -- was introduced.  Create the missing destination row only when the
      -- profile says opted in; never manufacture a false row or override an
      -- explicit destination preference.
      IF v_wants_announcements
         AND NOT EXISTS (
           SELECT 1
             FROM public.email_subscriptions
            WHERE email = v_new_email
         ) THEN
        INSERT INTO public.email_subscriptions
          (email, subscribed, source, updated_by, updated_at)
        VALUES (v_new_email, true, 'profile', NULL, NOW())
        ON CONFLICT (email) DO NOTHING;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reconcile_paymongo_payment_attempt(p_source_id text, p_payment_id text, p_payment_amount numeric, p_payment_status text DEFAULT 'paid'::text)
 RETURNS TABLE(order_reconciled boolean, order_id uuid, payment_id text, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  attempt_row public.payment_attempts%ROWTYPE;
  order_row public.orders%ROWTYPE;
  paid_amount NUMERIC(10,2);
  final_payment_status TEXT;
BEGIN
  IF LOWER(COALESCE(p_payment_status, '')) <> 'paid' THEN
    RAISE EXCEPTION 'Only a paid PayMongo payment can be reconciled'
      USING ERRCODE = '22023';
  END IF;
  IF p_payment_id IS NULL OR p_payment_id !~ '^pay_[A-Za-z0-9_-]{4,128}$' THEN
    RAISE EXCEPTION 'A verified PayMongo payment id is required'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO attempt_row
  FROM public.payment_attempts
  WHERE source_id = p_source_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, p_payment_id, 'No payment attempt found for source';
    RETURN;
  END IF;
  IF attempt_row.status = 'reconciled' THEN
    RETURN QUERY SELECT TRUE, attempt_row.order_id, attempt_row.payment_id, 'Already reconciled (no-op)';
    RETURN;
  END IF;

  paid_amount := ROUND(COALESCE(NULLIF(p_payment_amount, 0), attempt_row.amount), 2);
  IF paid_amount <= 0 OR ABS(paid_amount - attempt_row.amount) > 0.005 THEN
    RAISE EXCEPTION 'PayMongo payment amount does not match the registered attempt'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO order_row
  FROM public.orders
  WHERE id = attempt_row.order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    UPDATE public.payment_attempts
    SET status = 'failed', payment_id = p_payment_id, payment_status = 'failed',
        last_error = 'Order no longer exists'
    WHERE source_id = p_source_id;
    RETURN QUERY SELECT FALSE, attempt_row.order_id, p_payment_id, 'Order no longer exists';
    RETURN;
  END IF;

  final_payment_status := CASE WHEN attempt_row.payment_type = 'paylater' THEN 'partial' ELSE 'paid' END;

  INSERT INTO public.payment_transactions (
    order_id, amount, payment_method, payment_status,
    transaction_reference, gcash_channel, admin_name, notes
  ) VALUES (
    attempt_row.order_id, paid_amount, 'gcash', final_payment_status,
    p_payment_id, 'paymongo', 'System Webhook', 'Captured via PayMongo Webhook'
  )
  ON CONFLICT (transaction_reference) WHERE transaction_reference IS NOT NULL DO NOTHING;

  UPDATE public.orders
  SET payment_method = 'gcash',
      payer_type = COALESCE(attempt_row.payer_type, order_row.payer_type, 'sender'),
      payment_reference = COALESCE(p_payment_id, order_row.payment_reference),
      actual_weight = COALESCE(attempt_row.actual_weight, order_row.actual_weight),
      pickup_photos = COALESCE(attempt_row.pickup_photos, order_row.pickup_photos),
      promised_payment_date = COALESCE(attempt_row.promised_payment_date, order_row.promised_payment_date)
  WHERE id = attempt_row.order_id;

  UPDATE public.payment_attempts
  SET status = 'reconciled', payment_id = p_payment_id,
      payment_status = final_payment_status, amount = paid_amount,
      last_error = NULL, reconciled_at = COALESCE(reconciled_at, NOW())
  WHERE source_id = p_source_id;

  RETURN QUERY SELECT TRUE, attempt_row.order_id, p_payment_id,
    'Order reconciled via payment_transactions insert';
END;
$function$;
CREATE OR REPLACE FUNCTION public.delete_evidence_photos(p_items jsonb)
 RETURNS TABLE(item_key text, queue_id bigint, queued boolean, reason text, size_bytes bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item jsonb;
  v_order_id uuid;
  v_photo_field text;
  v_provider text;
  v_storage_path text;
  v_key text;
  v_order RECORD;
  v_array jsonb;
  v_new_array jsonb;
  v_found boolean;
  v_found_size bigint;
  v_elem jsonb;
  v_elem_provider text;
  v_elem_path text;
  v_elem_size bigint;
  v_queue_id bigint;
  v_orphan_size bigint;
  v_has_pending_attempt boolean;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'At least one photo must be selected' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_items) > 100 THEN
    RAISE EXCEPTION 'Too many photos selected at once (100 max)' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_order_id := NULLIF(v_item ->> 'order_id', '')::uuid;
    v_photo_field := v_item ->> 'photo_field';
    v_provider := v_item ->> 'provider';
    v_storage_path := v_item ->> 'storage_path';
    v_key := COALESCE(v_provider, '') || ':' || COALESCE(v_storage_path, '');
    v_queue_id := NULL;

    IF v_provider NOT IN ('supabase', 'firebase') OR v_storage_path IS NULL THEN
      item_key := v_key; queued := false; reason := 'Invalid photo reference';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;
    IF v_provider = 'supabase' AND v_storage_path !~ '^(pickup-proofs|delivery-proofs|receipts)/[^/]+/.+' THEN
      item_key := v_key; queued := false; reason := 'Invalid photo reference';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;
    IF v_provider = 'firebase' AND v_storage_path !~ '^photoFallbacks/[^/]+$' THEN
      item_key := v_key; queued := false; reason := 'Invalid photo reference';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;
    IF v_photo_field = 'receipt' THEN
      item_key := v_key; queued := false; reason := 'Receipt photos are always kept';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;

    -- ── Orphan claim: no order_id supplied. Re-derive orphan status fresh —
    -- never trust that the client's earlier read is still true.
    IF v_order_id IS NULL THEN
      IF v_provider <> 'supabase' THEN
        item_key := v_key; queued := false; reason := 'Invalid photo reference';
        queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
      END IF;

      SELECT CASE WHEN so.metadata ->> 'size' ~ '^[0-9]+$' THEN (so.metadata ->> 'size')::bigint ELSE NULL END
        INTO v_orphan_size
        FROM storage.objects so
       WHERE so.bucket_id = 'cargo-photos' AND so.name = v_storage_path;

      IF NOT FOUND THEN
        item_key := v_key; queued := false; reason := 'This photo could not be found';
        queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
      END IF;
      IF EXISTS (
        SELECT 1 FROM public.orders ord
        WHERE ord.tracking_number = (storage.foldername(v_storage_path))[2]
      ) THEN
        item_key := v_key; queued := false; reason := 'A booking now matches this photo — it is no longer unused';
        queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
      END IF;

      INSERT INTO public.photo_cleanup_queue (provider, storage_path)
      VALUES (v_provider, v_storage_path)
      ON CONFLICT (provider, storage_path) DO UPDATE
        SET queued_at = now(), completed_at = NULL, attempts = 0, last_error = NULL
      RETURNING id INTO v_queue_id;

      item_key := v_key; queued := true; reason := NULL;
      queue_id := v_queue_id; size_bytes := v_orphan_size; RETURN NEXT; CONTINUE;
    END IF;

    -- ── Referenced claim: must be pickup or delivery (never receipt, handled above).
    IF v_photo_field NOT IN ('pickup', 'delivery') THEN
      item_key := v_key; queued := false; reason := 'Invalid photo reference';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;

    SELECT o.id, o.status::text AS status, o.featured_on_website,
           CASE WHEN v_photo_field = 'pickup' THEN o.pickup_photos ELSE o.delivery_photos END AS photos
      INTO v_order
      FROM public.orders o
     WHERE o.id = v_order_id
     FOR UPDATE;

    IF NOT FOUND THEN
      item_key := v_key; queued := false; reason := 'Booking not found';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;
    IF v_order.featured_on_website THEN
      item_key := v_key; queued := false; reason := 'Featured on the public website';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;
    IF v_order.status NOT IN ('Delivered', 'Cancelled') THEN
      item_key := v_key; queued := false; reason := 'Shipment is still in progress';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;

    -- Pending-reconciliation dependency (new — see section A above). Only
    -- pickup photos can ever be referenced by payment_attempts.
    IF v_photo_field = 'pickup' THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.payment_attempts pa
        CROSS JOIN LATERAL jsonb_array_elements(COALESCE(pa.pickup_photos, '[]'::jsonb)) pe(value)
        CROSS JOIN LATERAL public.classify_evidence_photo_ref(pe.value) pc
        WHERE pa.order_id = v_order_id
          AND pa.status IN ('pending', 'chargeable')
          AND pc.provider = v_provider
          AND pc.storage_path = v_storage_path
      ) INTO v_has_pending_attempt;

      IF v_has_pending_attempt THEN
        item_key := v_key; queued := false; reason := 'A payment for this booking is still being reconciled';
        queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
      END IF;
    END IF;

    -- Rebuild the array with only the matching element removed. Matching is
    -- by classified (provider, path) identity, not array position, so a
    -- concurrent edit that reordered the array can't cause the wrong photo
    -- to be dropped.
    v_array := COALESCE(v_order.photos, '[]'::jsonb);
    v_new_array := '[]'::jsonb;
    v_found := false;
    v_found_size := NULL;
    FOR v_elem IN SELECT value FROM jsonb_array_elements(v_array)
    LOOP
      SELECT c.provider, c.storage_path, c.size_bytes
        INTO v_elem_provider, v_elem_path, v_elem_size
        FROM public.classify_evidence_photo_ref(v_elem) c;
      IF NOT v_found AND v_elem_provider = v_provider AND v_elem_path = v_storage_path THEN
        v_found := true;
        v_found_size := v_elem_size;
      ELSE
        v_new_array := v_new_array || jsonb_build_array(v_elem);
      END IF;
    END LOOP;

    IF NOT v_found THEN
      item_key := v_key; queued := false; reason := 'Photo reference no longer matches this booking';
      queue_id := NULL; size_bytes := NULL; RETURN NEXT; CONTINUE;
    END IF;

    IF v_photo_field = 'pickup' THEN
      UPDATE public.orders SET pickup_photos = v_new_array WHERE id = v_order_id;
    ELSE
      UPDATE public.orders SET delivery_photos = v_new_array WHERE id = v_order_id;
    END IF;

    INSERT INTO public.photo_cleanup_queue (provider, storage_path)
    VALUES (v_provider, v_storage_path)
    ON CONFLICT (provider, storage_path) DO UPDATE
      SET queued_at = now(), completed_at = NULL, attempts = 0, last_error = NULL
    RETURNING id INTO v_queue_id;

    item_key := v_key; queued := true; reason := NULL;
    queue_id := v_queue_id; size_bytes := v_found_size; RETURN NEXT;
  END LOOP;

  RETURN;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_public_order_events(p_tracking_number text)
 RETURNS TABLE(status character varying, changed_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT e.status, MIN(e.changed_at) AS changed_at
  FROM public.order_status_events e
  JOIN public.orders o ON o.id = e.order_id
  WHERE o.tracking_number = UPPER(TRIM(p_tracking_number))
  GROUP BY e.status
  ORDER BY MIN(e.changed_at);
$function$;
CREATE OR REPLACE FUNCTION public.log_order_status_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.order_status_events (order_id, status, changed_at, changed_by)
    VALUES (NEW.id, NEW.status, COALESCE(NEW.created_at, NOW()), auth.uid());
    RETURN NEW;
  END IF;

  -- UPDATE: only when the status actually moved.
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.order_status_events (order_id, status, changed_at, changed_by)
    VALUES (NEW.id, NEW.status, NOW(), auth.uid());
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.is_featured_photo_path(p_path text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.orders o
    CROSS JOIN LATERAL (
      SELECT CASE
        WHEN o.featured_image_type = 'delivery'
             AND jsonb_array_length(COALESCE(o.delivery_photos, '[]'::jsonb)) > 0
          THEN o.delivery_photos -> 0
        WHEN jsonb_array_length(COALESCE(o.pickup_photos, '[]'::jsonb)) > 0
          THEN o.pickup_photos -> 0
        ELSE NULL
      END AS photo
    ) selected
    CROSS JOIN LATERAL (
      SELECT CASE jsonb_typeof(selected.photo)
        WHEN 'object' THEN selected.photo ->> 'path'
        WHEN 'string' THEN selected.photo #>> '{}'
        ELSE NULL
      END AS raw_path
    ) photo_ref
    WHERE o.featured_on_website = TRUE
      AND (
        CASE
          WHEN photo_ref.raw_path LIKE '%/cargo-photos/%'
            THEN split_part(regexp_replace(photo_ref.raw_path, '^.*/cargo-photos/', ''), '?', 1)
          ELSE photo_ref.raw_path
        END
      ) = p_path
  );
$function$;
CREATE OR REPLACE FUNCTION public.is_supabase_evidence_upload_allowed(p_path text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.is_admin()
    AND (
      (storage.foldername(p_path))[1] NOT IN ('pickup', 'delivery', 'receipts', 'pickup-proofs', 'delivery-proofs')
      OR COALESCE(
        (SELECT (ps.upload_mode = 'automatic' OR ps.force_firebase_expires_at <= now())
         FROM public.photo_storage_settings ps WHERE ps.id = TRUE),
        TRUE
      )
    );
$function$;
CREATE OR REPLACE FUNCTION public.guard_activity_log_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_is_admin BOOLEAN;
  v_name TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RETURN NEW;
  END IF;

  v_is_admin := public.is_admin();

  IF NOT v_is_admin AND NEW.module NOT IN ('Orders', 'Authentication', 'Chat') THEN
    RAISE EXCEPTION 'Not allowed to write % activity logs', NEW.module;
  END IF;

  IF NEW.module = 'Payments'
     AND NEW.record_type = 'order'
     AND EXISTS (
       SELECT 1
       FROM public.activity_logs existing
       WHERE existing.module = 'Payments'
         AND existing.record_type = 'payment'
         AND existing.record_ref IS NOT DISTINCT FROM NEW.record_ref
         AND existing.created_at BETWEEN
           COALESCE(NEW.created_at, now()) - INTERVAL '5 minutes'
           AND COALESCE(NEW.created_at, now()) + INTERVAL '5 minutes'
     ) THEN
    RETURN NULL;
  END IF;

  SELECT name INTO v_name FROM public.profiles WHERE id = v_uid;
  NEW.admin_id := v_uid;
  NEW.admin_name := COALESCE(NULLIF(btrim(v_name), ''), 'Unknown Admin');

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_conversation_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL
     OR public.is_admin()
     OR COALESCE(current_setting('app.conversation_service_write', true), 'off') = 'on'
  THEN
    RETURN NEW;
  END IF;

  IF OLD.customer_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Cannot modify another customer''s conversation';
  END IF;

  NEW.id                       := OLD.id;
  NEW.customer_id              := OLD.customer_id;
  NEW.created_at               := OLD.created_at;
  NEW.first_response_at        := OLD.first_response_at;
  NEW.last_customer_message_at := OLD.last_customer_message_at;
  NEW.resolved_at              := OLD.resolved_at;

  IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status <> 'waiting' THEN
    NEW.status := OLD.status;
  END IF;

  IF NEW.escalated IS DISTINCT FROM OLD.escalated AND NEW.escalated = FALSE THEN
    NEW.escalated := OLD.escalated;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_effective_photo_storage_mode()
 RETURNS TABLE(upload_mode text, force_firebase_expires_at timestamp with time zone, updated_at timestamp with time zone, updated_by uuid, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings public.photo_storage_settings%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_settings FROM public.photo_storage_settings WHERE id = TRUE FOR UPDATE;

  IF v_settings.upload_mode = 'force_firebase'
     AND v_settings.force_firebase_expires_at <= now() THEN
    UPDATE public.photo_storage_settings
       SET upload_mode = 'automatic',
           force_firebase_expires_at = NULL,
           reason = 'Force Firebase mode expired automatically.',
           updated_by = NULL,
           updated_at = now()
     WHERE id = TRUE
     RETURNING * INTO v_settings;

    INSERT INTO public.photo_storage_events (
      event_type, provider, outcome, message, metadata
    ) VALUES (
      'mode_change', 'system', 'expired', 'Force Firebase mode expired and Automatic mode resumed.',
      jsonb_build_object('upload_mode', 'automatic')
    );
  END IF;

  RETURN QUERY
  SELECT v_settings.upload_mode, v_settings.force_firebase_expires_at,
         v_settings.updated_at, v_settings.updated_by, v_settings.reason;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_photo_storage_summary()
 RETURNS TABLE(supabase_photo_count bigint, firebase_photo_count bigint, legacy_photo_count bigint, pickup_photo_count bigint, delivery_photo_count bigint, receipt_photo_count bigint, failures_last_24h bigint, fallbacks_last_24h bigint, last_supabase_upload_at timestamp with time zone, last_firebase_upload_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH refs AS (
    SELECT 'pickup'::TEXT AS photo_type, jsonb_array_elements(COALESCE(o.pickup_photos, '[]'::jsonb)) AS ref
    FROM public.orders o
    UNION ALL
    SELECT 'delivery'::TEXT AS photo_type, jsonb_array_elements(COALESCE(o.delivery_photos, '[]'::jsonb)) AS ref
    FROM public.orders o
    UNION ALL
    SELECT 'receipt'::TEXT AS photo_type, to_jsonb(t.receipt_url) AS ref
    FROM public.payment_transactions t
    WHERE t.receipt_url IS NOT NULL AND btrim(t.receipt_url) <> ''
  ), classified AS (
    SELECT photo_type,
      CASE
        WHEN jsonb_typeof(ref) = 'object' AND ref ->> 'type' = 'firestore_fallback' THEN 'firebase'
        WHEN jsonb_typeof(ref) = 'object' AND ref ? 'firestore_path' THEN 'firebase'
        WHEN jsonb_typeof(ref) = 'string' AND ref #>> '{}' LIKE 'photoFallbacks/%' THEN 'firebase'
        WHEN jsonb_typeof(ref) = 'string' AND ref #>> '{}' LIKE '%"firestore_path"%' THEN 'firebase'
        WHEN jsonb_typeof(ref) = 'object' AND (ref ->> 'type' = 'supabase_storage' OR ref ? 'path') THEN 'supabase'
        WHEN jsonb_typeof(ref) = 'string' AND (ref #>> '{}') LIKE '{%' THEN 'legacy'
        WHEN jsonb_typeof(ref) = 'string' THEN 'legacy'
        ELSE 'legacy'
      END AS provider
    FROM refs
  )
  SELECT
    (SELECT count(*) FROM classified WHERE provider = 'supabase'),
    (SELECT count(*) FROM classified WHERE provider = 'firebase'),
    (SELECT count(*) FROM classified WHERE provider = 'legacy'),
    (SELECT count(*) FROM classified WHERE photo_type = 'pickup'),
    (SELECT count(*) FROM classified WHERE photo_type = 'delivery'),
    (SELECT count(*) FROM classified WHERE photo_type = 'receipt'),
    (SELECT count(*) FROM public.photo_storage_events WHERE event_type = 'upload' AND outcome = 'failure' AND created_at >= now() - INTERVAL '24 hours'),
    (SELECT count(*) FROM public.photo_storage_events WHERE event_type = 'upload' AND provider = 'firebase' AND outcome = 'success' AND created_at >= now() - INTERVAL '24 hours'),
    (SELECT max(created_at) FROM public.photo_storage_events WHERE event_type = 'upload' AND provider = 'supabase' AND outcome = 'success'),
    (SELECT max(created_at) FROM public.photo_storage_events WHERE event_type = 'upload' AND provider = 'firebase' AND outcome = 'success');
END;
$function$;
CREATE OR REPLACE FUNCTION public.mask_name(full_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN full_name IS NULL OR btrim(full_name) = '' THEN NULL
    ELSE
      split_part(btrim(full_name), ' ', 1)
      || CASE
        WHEN array_length(string_to_array(btrim(full_name), ' '), 1) > 1
          THEN ' '
            || UPPER(LEFT(split_part(
                  btrim(full_name), ' ',
                  array_length(string_to_array(btrim(full_name), ' '), 1)
                ), 1))
            || '.'
        ELSE ''
      END
  END
$function$;
CREATE OR REPLACE FUNCTION public.auto_resolve_stale_conversations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  WITH swept AS (
    UPDATE public.conversations
       SET status = 'resolved'
     WHERE status = 'waiting_customer'
       AND COALESCE(last_customer_message_at, created_at) < now() - interval '7 days'
    RETURNING id
  )
  SELECT COUNT(*) INTO v_count FROM swept;
  RETURN v_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.evidence_photo_rows()
 RETURNS TABLE(item_key text, source text, order_id uuid, tracking_number text, customer_name text, order_status text, photo_field text, provider text, storage_path text, size_bytes bigint, content_type text, taken_at timestamp with time zone, status text, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Not granted to anon/authenticated directly (see grants at the bottom) —
  -- only list_evidence_folders()/list_folder_photos() call it, and a
  -- SECURITY DEFINER caller's own admin check below is what actually gates
  -- this, same defense-in-depth reasoning as every other function here.
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH order_refs AS (
    SELECT
      o.id AS order_id,
      o.tracking_number::text AS tracking_number,
      COALESCE(o.receiver_name, o.sender_name)::text AS customer_name,
      o.status::text AS order_status,
      o.featured_on_website,
      field.photo_field,
      elem.value AS raw_ref,
      -- payment_attempts has no delivery_photos column, so this can only
      -- ever matter for a pickup photo. Compared by classified
      -- (provider, storage_path) identity, not raw jsonb equality, so a
      -- descriptor carrying extra/reordered fields still matches correctly
      -- — same reasoning as the array-rebuild loop in delete_evidence_photos.
      (field.photo_field = 'pickup' AND EXISTS (
        SELECT 1
        FROM public.payment_attempts pa
        CROSS JOIN LATERAL jsonb_array_elements(COALESCE(pa.pickup_photos, '[]'::jsonb)) pe(value)
        CROSS JOIN LATERAL public.classify_evidence_photo_ref(pe.value) pc
        CROSS JOIN LATERAL public.classify_evidence_photo_ref(elem.value) oc
        WHERE pa.order_id = o.id
          AND pa.status IN ('pending', 'chargeable')
          AND pc.provider = oc.provider
          AND pc.storage_path = oc.storage_path
      )) AS has_pending_payment_attempt
    FROM public.orders o
    CROSS JOIN LATERAL (VALUES ('pickup', o.pickup_photos), ('delivery', o.delivery_photos))
      AS field(photo_field, arr)
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(field.arr, '[]'::jsonb)) AS elem(value)
  ),
  receipt_refs AS (
    SELECT
      o.id AS order_id,
      o.tracking_number::text AS tracking_number,
      COALESCE(o.receiver_name, o.sender_name)::text AS customer_name,
      o.status::text AS order_status,
      o.featured_on_website,
      'receipt'::text AS photo_field,
      public.text_to_photo_ref(t.receipt_url) AS raw_ref,
      false AS has_pending_payment_attempt
    FROM public.payment_transactions t
    JOIN public.orders o ON o.id = t.order_id
    WHERE t.receipt_url IS NOT NULL AND btrim(t.receipt_url) <> ''
  ),
  referenced AS (
    SELECT * FROM order_refs
    UNION ALL
    SELECT * FROM receipt_refs
  ),
  classified_referenced AS (
    SELECT
      r.order_id, r.tracking_number, r.customer_name, r.photo_field,
      r.featured_on_website, r.order_status, r.has_pending_payment_attempt,
      c.provider, c.storage_path, c.size_bytes, c.content_type, c.taken_at
    FROM referenced r
    CROSS JOIN LATERAL public.classify_evidence_photo_ref(r.raw_ref) c
    WHERE c.provider IS NOT NULL
  ),
  referenced_rows AS (
    SELECT
      (cr.provider || ':' || cr.storage_path) AS item_key,
      'order'::text AS source,
      cr.order_id,
      cr.tracking_number,
      cr.customer_name,
      cr.order_status,
      cr.photo_field,
      cr.provider,
      cr.storage_path,
      cr.size_bytes,
      cr.content_type,
      cr.taken_at,
      CASE
        WHEN cr.photo_field = 'receipt' THEN 'protected'
        WHEN cr.featured_on_website THEN 'protected'
        WHEN cr.order_status NOT IN ('Delivered', 'Cancelled') THEN 'protected'
        WHEN cr.has_pending_payment_attempt THEN 'protected'
        ELSE 'eligible'
      END AS status,
      CASE
        WHEN cr.photo_field = 'receipt' THEN 'Receipt photo — kept as a financial record'
        WHEN cr.featured_on_website THEN 'Featured on the public website'
        WHEN cr.order_status NOT IN ('Delivered', 'Cancelled') THEN 'Shipment is still in progress'
        WHEN cr.has_pending_payment_attempt THEN 'A payment for this booking is still being reconciled'
        ELSE 'Delivered/Cancelled — can be deleted manually'
      END AS reason
    FROM classified_referenced cr
  ),
  orphaned_rows AS (
    SELECT
      ('supabase:' || o.name) AS item_key,
      'orphan'::text AS source,
      NULL::uuid AS order_id,
      NULL::text AS tracking_number,
      NULL::text AS customer_name,
      NULL::text AS order_status,
      CASE (storage.foldername(o.name))[1]
        WHEN 'pickup-proofs' THEN 'pickup'
        WHEN 'delivery-proofs' THEN 'delivery'
        WHEN 'receipts' THEN 'receipt'
        ELSE NULL
      END AS photo_field,
      'supabase'::text AS provider,
      o.name AS storage_path,
      CASE WHEN o.metadata ->> 'size' ~ '^[0-9]+$' THEN (o.metadata ->> 'size')::bigint ELSE NULL END AS size_bytes,
      o.metadata ->> 'mimetype' AS content_type,
      o.created_at AS taken_at,
      'eligible'::text AS status,
      'No matching booking was found for this photo'::text AS reason
    FROM storage.objects o
    WHERE o.bucket_id = 'cargo-photos'
      AND (storage.foldername(o.name))[1] IN ('pickup-proofs', 'delivery-proofs', 'receipts')
      AND (storage.foldername(o.name))[2] IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.orders ord WHERE ord.tracking_number = (storage.foldername(o.name))[2]
      )
  )
  SELECT * FROM referenced_rows
  UNION ALL
  SELECT * FROM orphaned_rows;
END;
$function$;
CREATE OR REPLACE FUNCTION public.search_conversation_messages(p_query text)
 RETURNS TABLE(conversation_id uuid, match_count integer, snippet text, matched_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_term TEXT;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  v_term := btrim(COALESCE(p_query, ''));
  IF length(v_term) < 2 THEN
    RETURN;   -- one character matches everything; not a search
  END IF;

  -- Treat the input as literal text: escape the LIKE metacharacters, and the
  -- escape character itself first so it is not double-processed.
  v_term := replace(v_term, '\', '\\');
  v_term := replace(v_term, '%', '\%');
  v_term := replace(v_term, '_', '\_');

  RETURN QUERY
  WITH hits AS (
    SELECT m.conversation_id AS conv_id,
           m.message,
           m.created_at,
           ROW_NUMBER() OVER (PARTITION BY m.conversation_id ORDER BY m.created_at DESC) AS rn,
           COUNT(*)     OVER (PARTITION BY m.conversation_id) AS total
      FROM public.chat_messages m
     WHERE m.message ILIKE '%' || v_term || '%' ESCAPE '\'
  )
  SELECT h.conv_id,
         h.total::INTEGER,
         -- The most recent matching line, trimmed for a one-line preview.
         CASE WHEN length(h.message) > 140
              THEN left(h.message, 140) || '…'
              ELSE h.message
         END,
         h.created_at
    FROM hits h
   WHERE h.rn = 1
   ORDER BY h.created_at DESC
   LIMIT 50;
END;
$function$;
CREATE OR REPLACE FUNCTION public.derive_payment_status(p_shipping_cost numeric, p_amount_paid numeric)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    -- Nothing collected. Also covers an unpriced booking (cost 0, paid 0),
    -- which the old `remaining <= 0` test wrongly called 'paid'.
    WHEN COALESCE(p_amount_paid, 0) <= 0 THEN 'unpaid'
    -- Settled. The half-centavo tolerance absorbs DECIMAL(10,2) rounding so
    -- a fully paid order is never left one centavo short of 'paid'.
    WHEN COALESCE(p_amount_paid, 0) >= COALESCE(p_shipping_cost, 0) - 0.005 THEN 'paid'
    ELSE 'partial'
  END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_payment_recorded()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_amount_text TEXT;
  v_balance_text TEXT;
  v_method_label TEXT;
BEGIN
  -- Defense in depth: every current insert path (reconcile_paymongo_payment_
  -- attempt, record_pickup_payment, record_delivery_payment,
  -- record_additional_payment) only ever writes 'paid' or 'partial'. A
  -- pending/failed/cancelled row (should one ever be written by a future
  -- change) must not notify.
  IF NEW.payment_status NOT IN ('paid', 'partial') THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_order
  FROM public.orders
  WHERE id = NEW.order_id;

  -- Orders always have a NOT NULL user_id today, but this is cheap insurance
  -- against a future schema change (e.g. a walk-in/no-account order) — the
  -- task asks this be handled gracefully, not assumed impossible.
  IF NOT FOUND OR v_order.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_amount_text := chr(8369) || to_char(
    GREATEST(COALESCE(NEW.amount, 0), 0),
    'FM999,999,999,990.00'
  );
  v_balance_text := chr(8369) || to_char(
    GREATEST(COALESCE(v_order.remaining_balance, 0), 0),
    'FM999,999,999,990.00'
  );

  -- Customer-friendly channel label. gcash_channel only exists on GCash rows
  -- (see 20260909010000); a manual direct transfer and an automatic PayMongo
  -- capture are deliberately worded differently, matching the two different
  -- trust levels already surfaced in the admin UI (PaymentCollectionPanel /
  -- AdditionalPaymentModal: "Process via PayMongo" vs "record a direct GCash
  -- transfer").
  v_method_label := CASE
    WHEN NEW.payment_method = 'gcash' AND NEW.gcash_channel = 'manual' THEN 'GCash transfer'
    WHEN NEW.payment_method = 'gcash' THEN 'GCash'
    WHEN NEW.payment_method = 'cash' THEN 'cash'
    ELSE COALESCE(NEW.payment_method, 'payment')
  END;

  INSERT INTO public.notifications (
    user_id, title, message, type, reference_id, payment_transaction_id
  )
  VALUES (
    v_order.user_id,
    CASE
      WHEN COALESCE(v_order.remaining_balance, 0) <= 0 THEN 'Payment Complete'
      ELSE 'Payment Received'
    END,
    CASE
      WHEN COALESCE(v_order.remaining_balance, 0) <= 0 THEN format(
        'We recorded your %s %s payment for order %s. Your order is now fully paid.',
        v_amount_text,
        v_method_label,
        v_order.tracking_number
      )
      ELSE format(
        'We recorded your %s %s payment for order %s. Remaining balance: %s.',
        v_amount_text,
        v_method_label,
        v_order.tracking_number,
        v_balance_text
      )
    END,
    'payment_update',
    v_order.id,
    NEW.id
  )
  -- Belt-and-suspenders: payment_transactions.id is a primary key, so this
  -- INSERT can only ever be attempted once per real payment under today's
  -- code. This guard is what makes that a guaranteed database invariant
  -- instead of an assumption about every future caller of this trigger.
  ON CONFLICT (payment_transaction_id) DO NOTHING;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_public_feedback()
 RETURNS TABLE(id uuid, rating integer, message text, created_at timestamp with time zone, customer_name text, receiver_city text, receiver_province text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    f.id,
    f.rating,
    f.message,
    f.created_at,
    public.mask_name(p.name) AS customer_name,
    o.receiver_city,
    o.receiver_province
  FROM public.customer_feedback f
  LEFT JOIN public.profiles p ON p.id = f.customer_id
  LEFT JOIN public.orders   o ON o.id = f.order_id
  WHERE f.is_hidden = false
  ORDER BY f.rating DESC, f.created_at DESC;
$function$;
CREATE OR REPLACE FUNCTION public.clear_payment_receipt_url(p_order_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.payment_transactions
     SET receipt_url = NULL
   WHERE order_id = p_order_id
     AND public.is_admin();
$function$;
CREATE OR REPLACE FUNCTION public.record_additional_payment(p_order_id uuid, p_amount numeric, p_payment_method text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_payment_date date DEFAULT NULL::date, p_receipt_url text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_admin_verified_receipt boolean DEFAULT false)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order              public.orders;
  v_admin_name         TEXT;
  v_paid_before        NUMERIC;
  v_paid_after         NUMERIC;
  v_payable            NUMERIC;
  v_outstanding_before NUMERIC;
  v_label              TEXT;
  v_ref_norm           TEXT;
  v_idempotency_order_id UUID;
  v_method             TEXT := lower(COALESCE(p_payment_method, ''));
  v_type               TEXT;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  IF COALESCE(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Amount must be greater than zero';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT order_id INTO v_idempotency_order_id
      FROM public.payment_transactions
     WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN
      IF v_idempotency_order_id = p_order_id THEN
        RETURN v_order;
      END IF;
      RAISE EXCEPTION 'This payment attempt identifier is already associated with another order.'
        USING ERRCODE = '23505';
    END IF;
  END IF;

  IF v_method = 'cash' THEN
    RAISE EXCEPTION 'Cash is no longer accepted once an order has been picked up. Collect the remaining balance via GCash.'
      USING ERRCODE = '22023';
  END IF;

  IF v_method <> 'gcash' THEN
    RAISE EXCEPTION 'Unsupported payment method: %', COALESCE(p_payment_method, '(missing)')
      USING ERRCODE = '22023';
  END IF;

  v_ref_norm := public.guard_manual_gcash_payment(p_reference, p_admin_verified_receipt);

  DECLARE
    v_gross_paid_before NUMERIC;
    v_refunded          NUMERIC;
  BEGIN
    SELECT COALESCE(SUM(amount), 0)
      INTO v_gross_paid_before
      FROM public.payment_transactions
     WHERE order_id = p_order_id
       AND payment_status IN ('paid', 'partial');
       
    SELECT COALESCE(SUM(amount), 0)
      INTO v_refunded
      FROM public.payment_refunds
     WHERE order_id = p_order_id
       AND status = 'succeeded';
       
    v_paid_before := GREATEST(0, v_gross_paid_before - v_refunded);
  END;

  v_payable            := public.order_payable_amount(v_order.shipping_cost, v_order.discount_amount);
  v_outstanding_before := GREATEST(0, v_payable - v_paid_before);

  IF p_amount > v_outstanding_before + 0.005 THEN
    RAISE EXCEPTION 'Payment amount of ₱% exceeds the outstanding balance of ₱%.',
      TO_CHAR(p_amount, 'FM999999990.00'),
      TO_CHAR(v_outstanding_before, 'FM999999990.00')
      USING ERRCODE = '22023';
  END IF;

  SELECT name INTO v_admin_name FROM public.profiles WHERE id = auth.uid();

  v_paid_after := v_paid_before + p_amount;
  v_label := CASE WHEN v_paid_after >= v_payable THEN 'paid' ELSE 'partial' END;
  v_type  := CASE
               WHEN v_label = 'paid' AND v_outstanding_before > 0.005 THEN 'Balance Settlement'
               ELSE 'Additional Payment'
             END;

  BEGIN
    INSERT INTO public.payment_transactions (
      order_id, amount, payment_method, payment_status,
      transaction_reference, transaction_reference_normalized, gcash_channel,
      admin_id, admin_name, notes, payment_type, payment_date, receipt_url,
      idempotency_key
    ) VALUES (
      p_order_id, p_amount, 'gcash', v_label,
      p_reference, v_ref_norm, 'manual',
      auth.uid(), COALESCE(v_admin_name, 'Unknown Admin'), p_notes,
      v_type, p_payment_date, p_receipt_url, p_idempotency_key
    );
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'This GCash reference was already recorded on another order. It cannot be credited again.'
      USING ERRCODE = '23505';
  END;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  RETURN v_order;
END;
$function$;
CREATE OR REPLACE FUNCTION private.clear_refund_uncertainty_on_provider_result()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.refund_id IS NOT NULL OR NEW.status IN ('failed', 'succeeded') THEN
    NEW.outcome_uncertain := FALSE;
  END IF;
  IF NEW.status <> 'failed' THEN
    NEW.public_failure_reason := NULL;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_paymongo_refund_uncertain(p_idempotency_key uuid, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_refund public.payment_refunds%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  UPDATE public.payment_refunds
  SET status = CASE WHEN status IN ('succeeded', 'failed') THEN status ELSE 'processing' END,
      outcome_uncertain = CASE WHEN status IN ('succeeded', 'failed') THEN FALSE ELSE TRUE END,
      last_error = CASE
        WHEN status IN ('succeeded', 'failed') THEN last_error
        ELSE LEFT(COALESCE(NULLIF(BTRIM(p_error), ''), 'Provider outcome is unknown'), 1000)
      END,
      public_failure_reason = NULL
  WHERE idempotency_key = p_idempotency_key
    AND refund_channel = 'paymongo'
  RETURNING * INTO v_refund;
  RETURN CASE WHEN FOUND THEN to_jsonb(v_refund) ELSE NULL END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_paymongo_refund_request(p_idempotency_key uuid, p_status text, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_refund public.payment_refunds%ROWTYPE;
  v_status TEXT := LOWER(BTRIM(COALESCE(p_status, '')));
BEGIN
  IF v_status NOT IN ('processing', 'failed') THEN
    RAISE EXCEPTION 'Request status must be processing or failed' USING ERRCODE = '22023';
  END IF;

  UPDATE public.payment_refunds
  SET status = CASE WHEN status = 'succeeded' THEN status ELSE v_status END,
      last_error = CASE WHEN status = 'succeeded' THEN last_error ELSE LEFT(p_error, 1000) END
  WHERE idempotency_key = p_idempotency_key
  RETURNING * INTO v_refund;

  RETURN CASE WHEN FOUND THEN to_jsonb(v_refund) ELSE NULL END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.prepare_paymongo_refund_without_settlement_guard(p_payment_transaction_id uuid, p_amount numeric, p_reason text, p_notes text, p_idempotency_key uuid, p_initiated_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_payment public.payment_transactions%ROWTYPE;
  v_existing public.payment_refunds%ROWTYPE;
  v_reserved NUMERIC(10,2);
  v_amount NUMERIC(10,2);
  v_reason TEXT;
  v_admin_name TEXT;
BEGIN
  IF p_payment_transaction_id IS NULL OR p_idempotency_key IS NULL OR p_initiated_by IS NULL THEN
    RAISE EXCEPTION 'Payment, idempotency key, and initiating admin are required'
      USING ERRCODE = '22023';
  END IF;

  v_amount := ROUND(COALESCE(p_amount, 0), 2);
  v_reason := LOWER(BTRIM(COALESCE(p_reason, '')));
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'Refund amount must be greater than zero' USING ERRCODE = '22023';
  END IF;
  IF v_reason NOT IN ('duplicate', 'fraudulent', 'requested_by_customer', 'others') THEN
    RAISE EXCEPTION 'Invalid refund reason' USING ERRCODE = '22023';
  END IF;
  IF p_notes IS NOT NULL AND char_length(BTRIM(p_notes)) > 255 THEN
    RAISE EXCEPTION 'Refund notes must be 255 characters or fewer' USING ERRCODE = '22023';
  END IF;
  SELECT p.name INTO v_admin_name
  FROM public.profiles p
  WHERE p.id = p_initiated_by AND p.role = 'admin';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_existing
  FROM public.payment_refunds
  WHERE idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.payment_transaction_id <> p_payment_transaction_id
       OR v_existing.amount <> v_amount
       OR v_existing.reason <> v_reason THEN
      RAISE EXCEPTION 'Idempotency key was already used for a different refund request'
        USING ERRCODE = '23505';
    END IF;
    RETURN to_jsonb(v_existing) || jsonb_build_object('created', FALSE);
  END IF;

  SELECT * INTO v_payment
  FROM public.payment_transactions
  WHERE id = p_payment_transaction_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Original payment was not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_payment.payment_method <> 'gcash'
     OR v_payment.gcash_channel IS DISTINCT FROM 'paymongo'
     OR v_payment.transaction_reference IS NULL
     OR v_payment.transaction_reference !~ '^pay_[A-Za-z0-9_-]{4,128}$'
     OR v_payment.payment_status NOT IN ('paid', 'partial') THEN
    RAISE EXCEPTION 'Only a verified PayMongo GCash payment can be refunded in the app'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(pr.amount), 0) INTO v_reserved
  FROM public.payment_refunds pr
  WHERE pr.payment_transaction_id = v_payment.id
    AND pr.status IN ('creating', 'pending', 'processing', 'succeeded');

  IF v_amount > v_payment.amount - v_reserved + 0.005 THEN
    RAISE EXCEPTION 'Refund exceeds the remaining refundable amount of %',
      GREATEST(v_payment.amount - v_reserved, 0)
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.payment_refunds (
    idempotency_key, payment_transaction_id, order_id, payment_id,
    amount, reason, notes, status, initiated_by, initiated_by_name
  ) VALUES (
    p_idempotency_key, v_payment.id, v_payment.order_id,
    v_payment.transaction_reference, v_amount, v_reason,
    NULLIF(BTRIM(p_notes), ''), 'creating', p_initiated_by, v_admin_name
  )
  RETURNING * INTO v_existing;

  RETURN to_jsonb(v_existing) || jsonb_build_object('created', TRUE);
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_payment_attempt_history(p_order_ids uuid[])
 RETURNS TABLE(id uuid, order_id uuid, amount numeric, status text, created_at timestamp with time zone, updated_at timestamp with time zone, failure_message text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_is_admin BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_order_ids IS NULL OR cardinality(p_order_ids) = 0 THEN RETURN; END IF;
  IF cardinality(p_order_ids) > 100 THEN
    RAISE EXCEPTION 'At most 100 order ids may be requested' USING ERRCODE = '22023';
  END IF;

  v_is_admin := public.is_admin();
  RETURN QUERY
  SELECT pa.id, pa.order_id, pa.amount, pa.status, pa.created_at, pa.updated_at,
    CASE WHEN v_is_admin THEN pa.last_error ELSE NULL END
  FROM public.payment_attempts pa
  JOIN public.orders o ON o.id = pa.order_id
  WHERE pa.order_id = ANY(p_order_ids)
    AND pa.status = 'failed'
    AND (v_is_admin OR o.user_id = auth.uid())
  ORDER BY pa.created_at, pa.id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.update_order_payment_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_gross_paid      NUMERIC(10,2);
  v_refunded        NUMERIC(10,2);
  v_total_paid      NUMERIC(10,2);
  v_shipping_cost   NUMERIC(10,2);
  v_discount_amount NUMERIC(10,2);
  v_payable         NUMERIC(10,2);
  v_remaining       NUMERIC(10,2);
  v_order_id        UUID;
BEGIN
  v_order_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.order_id ELSE NEW.order_id END;

  -- This is the common serialization point for payment and refund triggers.
  -- The aggregate SELECTs happen after the lock. Under READ COMMITTED, a
  -- concurrent waiter therefore takes its aggregate snapshot after the
  -- earlier recalculation commits and includes that transaction's child row.
  SELECT shipping_cost, discount_amount
    INTO v_shipping_cost, v_discount_amount
    FROM public.orders
   WHERE id = v_order_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(SUM(amount), 0)
    INTO v_gross_paid
    FROM public.payment_transactions
   WHERE order_id = v_order_id
     AND payment_status IN ('paid', 'partial');

  SELECT COALESCE(SUM(amount), 0)
    INTO v_refunded
    FROM public.payment_refunds
   WHERE order_id = v_order_id
     AND status = 'succeeded';

  v_total_paid := GREATEST(v_gross_paid - v_refunded, 0);
  v_payable := public.order_payable_amount(v_shipping_cost, v_discount_amount);
  v_remaining := GREATEST(0, v_payable - v_total_paid);

  UPDATE public.orders
     SET amount_paid = v_total_paid,
         remaining_balance = v_remaining,
         payment_status = public.derive_payment_status(v_payable, v_total_paid)
   WHERE id = v_order_id;

  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_sales_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  payload JSONB;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin access required'; END IF;

  WITH active_orders AS (
    SELECT o.*,
      GREATEST(COALESCE(o.shipping_cost, 0) - COALESCE(o.discount_amount, 0) - COALESCE(o.amount_paid, 0), 0) AS outstanding,
      (COALESCE(o.actual_weight, 0) > 0) AS is_priced,
      (o.status IN ('Picked Up', 'In Transit', 'Arrived at Hub', 'Out for Delivery', 'Delivered')) AS is_tracked
    FROM public.orders o WHERE o.status <> 'Cancelled'
  ),
  payments AS (
    SELECT LOWER(COALESCE(NULLIF(TRIM(pt.payment_method), ''), 'unspecified')) AS method,
      COALESCE(SUM(pt.amount), 0) AS gross_total, COUNT(*) AS payment_count
    FROM public.payment_transactions pt
    JOIN active_orders o ON o.id = pt.order_id
    WHERE pt.payment_status IN ('paid', 'partial') GROUP BY 1
  ),
  refunds AS (
    SELECT LOWER(COALESCE(NULLIF(TRIM(pt.payment_method), ''), 'unspecified')) AS method,
      COALESCE(SUM(pr.amount), 0) AS refund_total, COUNT(*) AS refund_count
    FROM public.payment_refunds pr
    JOIN public.payment_transactions pt ON pt.id = pr.payment_transaction_id
    JOIN active_orders o ON o.id = pr.order_id
    WHERE pr.status = 'succeeded' GROUP BY 1
  ),
  ledger AS (
    SELECT COALESCE(p.method, r.method) AS method,
      COALESCE(p.gross_total, 0) - COALESCE(r.refund_total, 0) AS total,
      COALESCE(p.gross_total, 0) AS gross_total,
      COALESCE(r.refund_total, 0) AS refund_total,
      COALESCE(p.payment_count, 0) AS payment_count,
      COALESCE(r.refund_count, 0) AS refund_count
    FROM payments p FULL OUTER JOIN refunds r USING (method)
  ),
  ledger_rollup AS (
    SELECT
      COALESCE(SUM(total) FILTER (WHERE method = 'cash'), 0) AS cash_total,
      COALESCE(SUM(total) FILTER (WHERE method = 'gcash'), 0) AS gcash_total,
      COALESCE(SUM(total) FILTER (WHERE method = 'paylater'), 0) AS paylater_total,
      COALESCE(SUM(total), 0) AS ledger_total,
      COALESCE(SUM(gross_total), 0) AS gross_ledger_total,
      COALESCE(SUM(refund_total), 0) AS refund_total,
      COALESCE(SUM(refund_count), 0) AS refund_count,
      COALESCE(jsonb_agg(jsonb_build_object(
        'method', method, 'total', total, 'grossTotal', gross_total,
        'refundTotal', refund_total, 'count', payment_count, 'refundCount', refund_count
      ) ORDER BY total DESC), '[]'::jsonb) AS method_totals
    FROM ledger
  ),
  order_rollup AS (
    SELECT COALESCE(SUM(GREATEST(shipping_cost - discount_amount, 0)), 0) AS total_revenue,
      COALESCE(SUM(discount_amount), 0) AS total_discounts,
      COALESCE(SUM(amount_paid), 0) AS paid_total,
      COALESCE(SUM(outstanding) FILTER (WHERE is_tracked), 0) AS outstanding_tracked,
      COALESCE(SUM(outstanding), 0) AS outstanding_all,
      COALESCE(SUM(remaining_balance) FILTER (WHERE is_tracked), 0) AS outstanding_stored,
      COUNT(*) FILTER (WHERE is_tracked AND outstanding > 0.005) AS unpaid_count,
      COUNT(*) FILTER (WHERE NOT is_priced) AS unpriced_count
    FROM active_orders
  ),
  summary AS (
    SELECT jsonb_build_object(
      'totalRevenue', o.total_revenue, 'totalDiscounts', o.total_discounts,
      'cashTotal', l.cash_total, 'gcashTotal', l.gcash_total, 'paylaterTotal', l.paylater_total,
      'methodTotals', l.method_totals, 'ledgerTotal', l.ledger_total,
      'grossLedgerTotal', l.gross_ledger_total,
      'refundTotal', l.refund_total, 'refundCount', l.refund_count,
      'grossCollected', o.paid_total + l.refund_total, 'netCollected', o.paid_total,
      'unattributedTotal', GREATEST(o.paid_total - l.ledger_total, 0),
      'paidTotal', o.paid_total, 'outstandingTotal', o.outstanding_tracked,
      'outstandingAllOrders', o.outstanding_all, 'outstandingStored', o.outstanding_stored,
      'unpaidTotal', o.outstanding_all, 'unpaidCount', o.unpaid_count, 'unpricedCount', o.unpriced_count
    ) AS value FROM order_rollup o, ledger_rollup l
  ),
  monthly AS (
    SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.month DESC), '[]'::jsonb) AS value
    FROM (
      SELECT TO_CHAR(DATE_TRUNC('month', created_at), 'YYYY-MM') AS month,
        COALESCE(SUM(GREATEST(shipping_cost - discount_amount, 0)), 0) AS total_revenue,
        COALESCE(SUM(amount_paid), 0) AS collected,
        COALESCE(SUM(outstanding), 0) AS outstanding
      FROM active_orders GROUP BY DATE_TRUNC('month', created_at)
      ORDER BY DATE_TRUNC('month', created_at) DESC LIMIT 24
    ) m
  ),
  unpaid AS (
    SELECT COALESCE(jsonb_agg(to_jsonb(u) ORDER BY u.created_at DESC), '[]'::jsonb) AS value
    FROM (
      SELECT id, tracking_number, created_at, status, shipping_cost, amount_paid,
        outstanding AS remaining_balance, payment_status
      FROM active_orders WHERE is_tracked AND outstanding > 0.005
      ORDER BY created_at DESC LIMIT 100
    ) u
  )
  SELECT jsonb_build_object('summary', summary.value, 'monthlySales', monthly.value, 'unpaidOrders', unpaid.value)
  INTO payload FROM summary, monthly, unpaid;
  RETURN payload;
END;
$function$;
CREATE OR REPLACE FUNCTION private.enqueue_paymongo_refund_recovery_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.payment_method = 'gcash'
     AND NEW.gcash_channel = 'paymongo'
     AND NEW.transaction_reference ~ '^pay_[A-Za-z0-9_-]{4,128}$'
     AND NEW.payment_status IN ('paid', 'partial') THEN
    INSERT INTO private.paymongo_refund_recovery_jobs (
      payment_transaction_id,
      payment_id,
      scan_until,
      next_check_at
    ) VALUES (
      NEW.id,
      NEW.transaction_reference,
      COALESCE(NEW.created_at, NOW()) + INTERVAL '180 days',
      NOW() + INTERVAL '5 minutes'
    )
    ON CONFLICT (payment_transaction_id) DO UPDATE
    SET payment_id = EXCLUDED.payment_id,
        status = 'active',
        scan_until = GREATEST(
          private.paymongo_refund_recovery_jobs.scan_until,
          EXCLUDED.scan_until
        ),
        next_check_at = LEAST(
          COALESCE(
            private.paymongo_refund_recovery_jobs.next_check_at,
            EXCLUDED.next_check_at
          ),
          EXCLUDED.next_check_at
        ),
        claim_token = CASE
          WHEN private.paymongo_refund_recovery_jobs.payment_id <> EXCLUDED.payment_id
            THEN NULL
          ELSE private.paymongo_refund_recovery_jobs.claim_token
        END,
        claimed_at = CASE
          WHEN private.paymongo_refund_recovery_jobs.payment_id <> EXCLUDED.payment_id
            THEN NULL
          ELSE private.paymongo_refund_recovery_jobs.claimed_at
        END,
        livemode = CASE
          WHEN private.paymongo_refund_recovery_jobs.payment_id <> EXCLUDED.payment_id
            THEN NULL
          ELSE private.paymongo_refund_recovery_jobs.livemode
        END,
        updated_at = NOW();
  ELSE
    DELETE FROM private.paymongo_refund_recovery_jobs
    WHERE payment_transaction_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.kick_push_worker_on_new_jobs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  -- Fire-and-forget pg_net call to process notifications immediately
  PERFORM private.trigger_push_delivery_worker();
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION private.wake_paymongo_refund_recovery_for_refund()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.refund_channel <> 'paymongo' THEN
    RETURN NEW;
  END IF;

  UPDATE private.paymongo_refund_recovery_jobs
  SET status = 'active',
      scan_until = GREATEST(scan_until, NOW() + INTERVAL '24 hours'),
      next_check_at = LEAST(
        COALESCE(next_check_at, NOW() + INTERVAL '2 minutes'),
        NOW() + INTERVAL '2 minutes'
      ),
      updated_at = NOW()
  WHERE payment_transaction_id = NEW.payment_transaction_id;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_paymongo_refund_recovery_jobs(p_limit integer, p_livemode boolean)
 RETURNS TABLE(payment_transaction_id uuid, payment_id text, claim_token uuid, livemode boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_limit INTEGER := LEAST(GREATEST(COALESCE(p_limit, 15), 1), 25);
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  IF p_livemode IS NULL THEN
    RAISE EXCEPTION 'PayMongo mode is required' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT j.payment_transaction_id
    FROM private.paymongo_refund_recovery_jobs AS j
    WHERE j.status = 'active'
      AND j.next_check_at <= NOW()
      AND (j.claimed_at IS NULL OR j.claimed_at < NOW() - INTERVAL '10 minutes')
      AND (j.livemode IS NULL OR j.livemode = p_livemode)
    ORDER BY
      EXISTS (
        SELECT 1
        FROM public.payment_refunds AS pr
        WHERE pr.payment_transaction_id = j.payment_transaction_id
          AND pr.status IN ('creating', 'pending', 'processing')
      ) DESC,
      j.next_check_at,
      j.payment_transaction_id
    FOR UPDATE OF j SKIP LOCKED
    LIMIT v_limit
  ), claimed AS (
    UPDATE private.paymongo_refund_recovery_jobs AS j
    SET claim_token = gen_random_uuid(),
        claimed_at = NOW(),
        updated_at = NOW()
    FROM candidates AS c
    WHERE j.payment_transaction_id = c.payment_transaction_id
    RETURNING
      j.payment_transaction_id,
      j.payment_id,
      j.claim_token,
      j.livemode
  )
  SELECT
    c.payment_transaction_id,
    c.payment_id,
    c.claim_token,
    c.livemode
  FROM claimed AS c;
END;
$function$;
CREATE OR REPLACE FUNCTION public.finish_paymongo_refund_recovery_job(p_payment_transaction_id uuid, p_claim_token uuid, p_success boolean, p_livemode boolean, p_has_unresolved boolean DEFAULT false, p_refund_count integer DEFAULT 0, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_updated INTEGER;
  v_payment_created_at TIMESTAMPTZ;
  v_oldest_unresolved_at TIMESTAMPTZ;
  v_has_unlinked BOOLEAN := FALSE;
  v_next_delay INTERVAL;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  IF p_payment_transaction_id IS NULL OR p_claim_token IS NULL OR p_livemode IS NULL THEN
    RAISE EXCEPTION 'Job, claim, and PayMongo mode are required' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_success, FALSE) THEN
    SELECT pt.created_at INTO v_payment_created_at
    FROM public.payment_transactions AS pt
    WHERE pt.id = p_payment_transaction_id;

    IF COALESCE(p_has_unresolved, FALSE) THEN
      SELECT MIN(pr.created_at), BOOL_OR(pr.refund_id IS NULL)
      INTO v_oldest_unresolved_at, v_has_unlinked
      FROM public.payment_refunds AS pr
      WHERE pr.payment_transaction_id = p_payment_transaction_id
        AND pr.status IN ('creating', 'pending', 'processing');

      v_next_delay := CASE
        WHEN COALESCE(v_has_unlinked, FALSE) THEN INTERVAL '5 minutes'
        WHEN v_oldest_unresolved_at >= NOW() - INTERVAL '1 hour' THEN INTERVAL '5 minutes'
        WHEN v_oldest_unresolved_at >= NOW() - INTERVAL '24 hours' THEN INTERVAL '30 minutes'
        ELSE INTERVAL '6 hours'
      END;
    ELSIF GREATEST(COALESCE(p_refund_count, 0), 0) > 0 THEN
      v_next_delay := INTERVAL '12 hours';
    ELSE
      v_next_delay := CASE
        WHEN v_payment_created_at >= NOW() - INTERVAL '7 days' THEN INTERVAL '6 hours'
        WHEN v_payment_created_at >= NOW() - INTERVAL '30 days' THEN INTERVAL '24 hours'
        ELSE INTERVAL '72 hours'
      END;
    END IF;

    UPDATE private.paymongo_refund_recovery_jobs AS j
    SET livemode = COALESCE(j.livemode, p_livemode),
        status = CASE
          WHEN NOT COALESCE(p_has_unresolved, FALSE) AND NOW() >= j.scan_until THEN 'completed'
          ELSE 'active'
        END,
        next_check_at = CASE
          WHEN NOT COALESCE(p_has_unresolved, FALSE) AND NOW() >= j.scan_until THEN NULL
          ELSE NOW() + v_next_delay
        END,
        last_checked_at = NOW(),
        last_success_at = NOW(),
        last_refund_count = GREATEST(COALESCE(p_refund_count, 0), 0),
        consecutive_failures = 0,
        last_error = NULL,
        last_error_at = NULL,
        claim_token = NULL,
        claimed_at = NULL,
        updated_at = NOW()
    WHERE j.payment_transaction_id = p_payment_transaction_id
      AND j.claim_token = p_claim_token
      AND (j.livemode IS NULL OR j.livemode = p_livemode);
  ELSE
    UPDATE private.paymongo_refund_recovery_jobs AS j
    SET status = 'active',
        next_check_at = NOW() + make_interval(
          mins => LEAST(360, 5 * (2 ^ LEAST(j.consecutive_failures, 6))::INTEGER)
        ),
        last_checked_at = NOW(),
        consecutive_failures = j.consecutive_failures + 1,
        last_error = LEFT(
          COALESCE(NULLIF(BTRIM(p_error), ''), 'unknown_stage: Unexpected non-error failure'),
          1000
        ),
        last_error_at = NOW(),
        claim_token = NULL,
        claimed_at = NULL,
        updated_at = NOW()
    WHERE j.payment_transaction_id = p_payment_transaction_id
      AND j.claim_token = p_claim_token;
  END IF;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated = 1;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_paymongo_refund_recovery_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_result JSONB;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'activeJobs', COUNT(*) FILTER (WHERE j.status = 'active'),
    'completedJobs', COUNT(*) FILTER (WHERE j.status = 'completed'),
    'dueJobs', COUNT(*) FILTER (WHERE j.status = 'active' AND j.next_check_at <= NOW()),
    'jobsInBackoff', COUNT(*) FILTER (WHERE j.consecutive_failures > 0),
    'failuresLast24Hours', COUNT(*) FILTER (WHERE j.last_error_at >= NOW() - INTERVAL '24 hours'),
    'oldestDueAt', MIN(j.next_check_at) FILTER (WHERE j.status = 'active' AND j.next_check_at <= NOW()),
    'lastSuccessfulScanAt', MAX(j.last_success_at),
    'lastFailureAt', MAX(j.last_error_at),
    'unresolvedRefunds', (
      SELECT COUNT(*) FROM public.payment_refunds AS pr
      WHERE pr.status IN ('creating', 'pending', 'processing')
    ),
    'uncertainRefunds', (
      SELECT COUNT(*) FROM public.payment_refunds AS pr WHERE pr.outcome_uncertain
    ),
    'recentFailureDiagnostics', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'at', recent.last_error_at,
        'diagnostic', recent.last_error,
        'consecutiveFailures', recent.consecutive_failures
      ) ORDER BY recent.last_error_at DESC)
      FROM (
        SELECT last_error_at, last_error, consecutive_failures
        FROM private.paymongo_refund_recovery_jobs
        WHERE last_error_at IS NOT NULL
        ORDER BY last_error_at DESC
        LIMIT 10
      ) AS recent
    ), '[]'::JSONB)
  ) INTO v_result
  FROM private.paymongo_refund_recovery_jobs AS j;
  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_payment_transaction_history(p_order_ids uuid[])
 RETURNS TABLE(id uuid, order_id uuid, amount numeric, payment_method text, transaction_reference text, payment_status text, admin_id uuid, admin_name text, notes text, created_at timestamp with time zone, payment_type text, payment_date date, receipt_url text, idempotency_key uuid, gcash_channel text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_is_admin BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_order_ids IS NULL OR cardinality(p_order_ids) = 0 THEN RETURN; END IF;
  IF cardinality(p_order_ids) > 100 THEN
    RAISE EXCEPTION 'At most 100 order ids may be requested' USING ERRCODE = '22023';
  END IF;
  v_is_admin := public.is_admin();

  RETURN QUERY
  SELECT
    pt.id,
    pt.order_id,
    pt.amount,
    pt.payment_method,
    CASE
      WHEN v_is_admin THEN pt.transaction_reference
      WHEN pt.transaction_reference ~* '^(pay_|ref_|src_|link_|paym_|pi_|re_|sub_|cus_|evt_)' THEN NULL
      ELSE pt.transaction_reference
    END,
    pt.payment_status,
    CASE WHEN v_is_admin THEN pt.admin_id ELSE NULL END,
    CASE
      WHEN v_is_admin THEN pt.admin_name
      WHEN LOWER(BTRIM(COALESCE(pt.admin_name, ''))) IN
        ('system webhook', 'system', 'payment system', 'paymongo dashboard')
        THEN 'Payment System'
      ELSE 'CargoExpress Staff'
    END,
    CASE WHEN v_is_admin THEN pt.notes ELSE NULL END,
    pt.created_at,
    pt.payment_type,
    pt.payment_date,
    pt.receipt_url,
    CASE WHEN v_is_admin THEN pt.idempotency_key ELSE NULL END,
    pt.gcash_channel
  FROM public.payment_transactions AS pt
  JOIN public.orders AS o ON o.id = pt.order_id
  WHERE pt.order_id = ANY(p_order_ids)
    AND (v_is_admin OR o.user_id = auth.uid())
  ORDER BY pt.created_at, pt.id;
END;
$function$;
CREATE OR REPLACE FUNCTION public.list_evidence_folders(p_search text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 30)
 RETURNS TABLE(folder_key text, tracking_number text, customer_name text, order_status text, photo_count bigint, eligible_count bigint, total_size_bytes bigint, latest_taken_at timestamp with time zone, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_page integer := GREATEST(1, COALESCE(p_page, 1));
  v_page_size integer := LEAST(60, GREATEST(1, COALESCE(p_page_size, 30)));
  v_search text := NULLIF(btrim(COALESCE(p_search, '')), '');
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH grouped AS (
    SELECT
      COALESCE(r.tracking_number, '__unbooked__') AS folder_key,
      r.tracking_number,
      max(r.customer_name) AS customer_name,
      max(r.order_status) AS order_status,
      count(*)::bigint AS photo_count,
      count(*) FILTER (WHERE r.status = 'eligible')::bigint AS eligible_count,
      sum(COALESCE(r.size_bytes, 0))::bigint AS total_size_bytes,
      max(r.taken_at) AS latest_taken_at
    FROM public.evidence_photo_rows() r
    GROUP BY COALESCE(r.tracking_number, '__unbooked__'), r.tracking_number
  ),
  filtered AS (
    SELECT *
    FROM grouped g
    WHERE v_search IS NULL
       OR g.tracking_number ILIKE ('%' || v_search || '%')
       OR (g.tracking_number IS NULL AND 'photos without bookings' ILIKE ('%' || lower(v_search) || '%'))
  )
  SELECT
    f.folder_key, f.tracking_number, f.customer_name, f.order_status,
    f.photo_count, f.eligible_count, f.total_size_bytes, f.latest_taken_at,
    count(*) OVER ()::bigint AS total_count
  FROM filtered f
  -- The unbooked catch-all sorts last — it is a fallback bucket, not a
  -- booking, and pinning it keeps the normal folder order (most recent
  -- activity first) stable regardless of how large it grows.
  ORDER BY (f.tracking_number IS NULL), f.latest_taken_at DESC NULLS LAST, f.folder_key
  LIMIT v_page_size OFFSET (v_page - 1) * v_page_size;
END;
$function$;
CREATE OR REPLACE FUNCTION public.list_folder_photos(p_folder_key text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 100)
 RETURNS TABLE(item_key text, source text, order_id uuid, tracking_number text, photo_field text, provider text, storage_path text, size_bytes bigint, content_type text, taken_at timestamp with time zone, status text, reason text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_page integer := GREATEST(1, COALESCE(p_page, 1));
  -- Real booking folders are always small (a handful of photos); the higher
  -- cap exists for the "Photos Without Bookings" folder, which can be large
  -- after a bulk data reset and must still be paginated, not fetched whole.
  v_page_size integer := LEAST(200, GREATEST(1, COALESCE(p_page_size, 100)));
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(btrim(p_folder_key), '') = '' THEN
    RAISE EXCEPTION 'A folder must be specified' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH matched AS (
    SELECT r.*
    FROM public.evidence_photo_rows() r
    WHERE (p_folder_key = '__unbooked__' AND r.tracking_number IS NULL)
       OR r.tracking_number = p_folder_key
  )
  SELECT
    m.item_key, m.source, m.order_id, m.tracking_number, m.photo_field,
    m.provider, m.storage_path, m.size_bytes, m.content_type, m.taken_at,
    m.status, m.reason,
    count(*) OVER ()::bigint AS total_count
  FROM matched m
  ORDER BY m.taken_at DESC NULLS LAST, m.item_key
  LIMIT v_page_size OFFSET (v_page - 1) * v_page_size;
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_company_asset_deletable(p_paths text[])
 RETURNS TABLE(storage_path text, deletable boolean, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_banner_path text;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_paths IS NULL OR array_length(p_paths, 1) IS NULL THEN
    RAISE EXCEPTION 'At least one file must be selected' USING ERRCODE = '22023';
  END IF;
  IF array_length(p_paths, 1) > 100 THEN
    RAISE EXCEPTION 'Too many files selected at once (100 max)' USING ERRCODE = '22023';
  END IF;

  -- banner_image_url is stored as a full public URL with a cache-busting
  -- "?t=..." query string (CompanyInformationPage.jsx); reduce it to the
  -- bare storage path the same way the bucket itself addresses the object.
  SELECT regexp_replace(
           regexp_replace(ci.banner_image_url, '^.*/company-assets/', ''),
           '\?.*$', ''
         )
    INTO v_banner_path
    FROM public.company_information ci
   WHERE ci.id = '00000000-0000-0000-0000-000000000001';

  RETURN QUERY
  SELECT
    p AS storage_path,
    (v_banner_path IS NULL OR p <> v_banner_path) AS deletable,
    CASE WHEN v_banner_path IS NOT NULL AND p = v_banner_path
      THEN 'Currently used as the site banner image — replace it on Company Information first.'
      ELSE NULL
    END AS reason
  FROM unnest(p_paths) AS p;
END;
$function$;
CREATE OR REPLACE FUNCTION private.monitor_push_delivery_health()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_dead INTEGER;
  v_stuck INTEGER;
  v_overdue INTEGER;
  v_cron_failures INTEGER;
  v_message TEXT;
BEGIN
  SELECT
    count(*) FILTER (
      WHERE status = 'dead' AND updated_at >= now() - INTERVAL '24 hours'
    ),
    count(*) FILTER (
      WHERE status = 'processing' AND claimed_at < now() - INTERVAL '5 minutes'
    ),
    count(*) FILTER (
      WHERE status IN ('pending', 'retry')
        AND available_at < now() - INTERVAL '10 minutes'
    )
  INTO v_dead, v_stuck, v_overdue
  FROM public.notification_delivery_jobs;

  SELECT count(*)
    INTO v_cron_failures
  FROM cron.job_run_details AS run
  JOIN cron.job AS job ON job.jobid = run.jobid
  WHERE job.jobname = 'process_push_deliveries'
    AND run.status = 'failed'
    AND run.start_time >= now() - INTERVAL '15 minutes';

  IF v_dead = 0
     AND v_stuck = 0
     AND v_overdue = 0
     AND v_cron_failures = 0 THEN
    RETURN;
  END IF;

  v_message := format(
    'System Notification Error: %s failed permanently, %s stuck, %s delayed, %s background worker failures.',
    v_dead, v_stuck, v_overdue, v_cron_failures
  );

  RAISE WARNING '%', v_message;

  INSERT INTO public.notifications (user_id, title, message, type)
  SELECT p.id, 'System Push Notification Alert', v_message, 'system_alert'
  FROM public.profiles AS p
  WHERE p.role = 'admin'
    AND NOT EXISTS (
      SELECT 1
      FROM public.notifications AS n
      WHERE n.user_id = p.id
        AND n.type = 'system_alert'
        AND n.title = 'System Push Notification Alert'
        AND n.created_at >= now() - INTERVAL '30 minutes'
    );
END;
$function$;
CREATE OR REPLACE FUNCTION private.sync_contact_inquiry_email_subscription()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_email TEXT := lower(btrim(COALESCE(NEW.contact_email, '')));
BEGIN
  IF NEW.wants_announcements IS NOT TRUE THEN
    RETURN NEW;
  END IF;
  IF v_email = '' OR v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.email_subscriptions (email, subscribed, source, updated_by, updated_at)
  VALUES (v_email, true, 'contact_form', NULL, now())
  ON CONFLICT (email) DO UPDATE SET
    subscribed = true,
    source = 'contact_form',
    updated_by = NULL,
    updated_at = now();

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION private.sync_profile_email_subscription()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_email TEXT := lower(btrim(COALESCE(NEW.email, '')));
BEGIN
  IF current_setting('cargoexpress.suppress_subscription_sync', true) = 'true' THEN
    RETURN NEW;
  END IF;
  IF v_email = '' OR v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.email_subscriptions (email, subscribed, source, updated_by, updated_at)
  VALUES (v_email, NEW.wants_announcements, 'profile', NULL, now())
  ON CONFLICT (email) DO UPDATE SET
    subscribed = NEW.wants_announcements,
    source = 'profile',
    updated_by = NULL,
    updated_at = now();

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.check_manual_refund_reauth_lockout(p_admin_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_row private.manual_refund_reauth_attempts%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM private.manual_refund_reauth_attempts WHERE admin_id = p_admin_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('locked', FALSE, 'locked_until', NULL, 'failed_count', 0);
  END IF;
  RETURN jsonb_build_object(
    'locked', v_row.locked_until IS NOT NULL AND v_row.locked_until > NOW(),
    'locked_until', v_row.locked_until,
    'failed_count', v_row.failed_count
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.admin_set_email_subscription(p_email text, p_subscribed boolean)
 RETURNS email_subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_email TEXT := lower(btrim(p_email));
  v_result public.email_subscriptions;
BEGIN
  IF NOT (SELECT public.is_admin()) THEN
    RAISE EXCEPTION 'Admin privileges required';
  END IF;
  IF v_email IS NULL OR v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  INSERT INTO public.email_subscriptions (email, subscribed, source, updated_by, updated_at)
  VALUES (v_email, p_subscribed, 'admin', auth.uid(), now())
  ON CONFLICT (email) DO UPDATE SET
    subscribed = p_subscribed,
    source = 'admin',
    updated_by = auth.uid(),
    updated_at = now()
  RETURNING * INTO v_result;

  -- Disabling must actually stop the separate trip-reschedule courtesy email
  -- too, if this address belongs to a registered customer — that feature
  -- reads profiles.wants_announcements directly and is not otherwise
  -- touched here. Deliberately asymmetric: enabling via this admin path does
  -- NOT mirror into profiles (agreeing to hear about trip schedules through
  -- a phone/chat conversation on an inquiry is not the same as opting into
  -- every future account-level email), but disabling always propagates,
  -- because an opt-out should never leave a person still receiving mail
  -- from a related feature.
  IF NOT p_subscribed THEN
    PERFORM set_config('cargoexpress.suppress_subscription_sync', 'true', true);
    UPDATE public.profiles SET wants_announcements = false WHERE lower(btrim(email)) = v_email;
  END IF;

  RETURN v_result;
END;
$function$;
CREATE OR REPLACE FUNCTION public.unsubscribe_email_updates(p_email text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_email TEXT := lower(btrim(p_email));
BEGIN
  IF v_email IS NULL OR v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  INSERT INTO public.email_subscriptions (email, subscribed, source, updated_by, updated_at)
  VALUES (v_email, false, 'unsubscribe_link', NULL, now())
  ON CONFLICT (email) DO UPDATE SET
    subscribed = false,
    source = 'unsubscribe_link',
    updated_by = NULL,
    updated_at = now();

  PERFORM set_config('cargoexpress.suppress_subscription_sync', 'true', true);
  UPDATE public.profiles SET wants_announcements = false WHERE lower(btrim(email)) = v_email;
  UPDATE public.contact_inquiries SET wants_announcements = false WHERE lower(btrim(contact_email)) = v_email;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_financial_report_data(p_start_date timestamp with time zone, p_end_date timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  payload JSONB;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  WITH payments AS (
    SELECT id, order_id, amount, LOWER(TRIM(payment_method)) as method, created_at as event_date, payment_status, transaction_reference
    FROM payment_transactions
    WHERE payment_status IN ('paid', 'partial')
      AND created_at >= p_start_date AND created_at < p_end_date
  ),
  refunds AS (
    SELECT pr.id, pr.order_id, pr.amount, LOWER(TRIM(pt.payment_method)) as method,
           COALESCE(pr.succeeded_at, pr.provider_updated_at, pr.updated_at) as event_date,
           pr.payment_id, pr.refund_id
    FROM payment_refunds pr
    JOIN payment_transactions pt ON pr.payment_transaction_id = pt.id
    WHERE pr.status = 'succeeded'
      AND COALESCE(pr.succeeded_at, pr.provider_updated_at, pr.updated_at) >= p_start_date
      AND COALESCE(pr.succeeded_at, pr.provider_updated_at, pr.updated_at) < p_end_date
  ),
  delivered_orders AS (
    SELECT o.id, o.tracking_number, o.sender_name, o.receiver_name, o.origin, o.destination,
           o.shipping_cost, o.discount_amount, o.amount_paid, o.payment_status,
           GREATEST(o.shipping_cost - COALESCE(o.discount_amount, 0), 0) AS final_fee,
           GREATEST(GREATEST(o.shipping_cost - COALESCE(o.discount_amount, 0), 0) - COALESCE(o.amount_paid, 0), 0) AS balance,
           (SELECT MAX(changed_at) FROM order_status_events ose WHERE ose.order_id = o.id AND ose.status = 'Delivered') as delivered_at
    FROM orders o
    WHERE o.status = 'Delivered'
      AND EXISTS (
        SELECT 1 FROM order_status_events ose
        WHERE ose.order_id = o.id
          AND ose.status = 'Delivered'
          AND ose.changed_at >= p_start_date
          AND ose.changed_at < p_end_date
      )
  ),
  gross_collected AS (
    SELECT COALESCE(SUM(amount), 0) as total FROM payments WHERE method != 'paylater'
  ),
  successful_refunds AS (
    SELECT COALESCE(SUM(amount), 0) as total FROM refunds
  ),
  delivered_value AS (
    SELECT COALESCE(SUM(final_fee), 0) as total FROM delivered_orders
  ),
  method_union AS (
    SELECT method, amount as gross, 1 as p_count, 0 as ref_amt, 0 as r_count FROM payments WHERE method != 'paylater'
    UNION ALL
    SELECT method, 0 as gross, 0 as p_count, amount as ref_amt, 1 as r_count FROM refunds
  ),
  method_totals AS (
    SELECT method,
           SUM(gross) as gross,
           SUM(p_count) as payment_count,
           SUM(ref_amt) as refunds,
           SUM(r_count) as refund_count,
           SUM(gross) - SUM(ref_amt) as net
    FROM method_union
    GROUP BY method
  ),
  daily_union AS (
    SELECT (created_at AT TIME ZONE 'Asia/Manila')::date as day, amount as gross, 0 as ref_amt
    FROM payment_transactions
    WHERE payment_status IN ('paid', 'partial') AND LOWER(TRIM(payment_method)) != 'paylater'
      AND created_at >= p_start_date AND created_at < p_end_date
    UNION ALL
    SELECT (COALESCE(succeeded_at, provider_updated_at, updated_at) AT TIME ZONE 'Asia/Manila')::date as day, 0 as gross, amount as ref_amt
    FROM payment_refunds
    WHERE status = 'succeeded'
      AND COALESCE(succeeded_at, provider_updated_at, updated_at) >= p_start_date
      AND COALESCE(succeeded_at, provider_updated_at, updated_at) < p_end_date
  ),
  daily_chart AS (
    SELECT day, SUM(gross) - SUM(ref_amt) as net
    FROM daily_union
    GROUP BY day
    ORDER BY day
  ),
  combined_details AS (
    SELECT 'payment' as type, id, order_id, amount, method, event_date, transaction_reference as ref_id
    FROM payments
    UNION ALL
    SELECT 'refund' as type, id, order_id, amount, method, event_date, refund_id as ref_id
    FROM refunds
    ORDER BY event_date DESC
  )
  SELECT jsonb_build_object(
    'grossCollected', (SELECT total FROM gross_collected),
    'successfulRefunds', (SELECT total FROM successful_refunds),
    'netCollected', (SELECT total FROM gross_collected) - (SELECT total FROM successful_refunds),
    'deliveredShipmentValue', (SELECT total FROM delivered_value),
    'methodTotals', COALESCE((SELECT jsonb_agg(to_jsonb(mt)) FROM method_totals mt), '[]'::jsonb),
    'dailyChart', COALESCE((SELECT jsonb_agg(to_jsonb(dc)) FROM daily_chart dc), '[]'::jsonb),
    'completedDeliveries', COALESCE((SELECT jsonb_agg(to_jsonb(do_rows)) FROM delivered_orders do_rows), '[]'::jsonb),
    'paymentRefundDetail', COALESCE((SELECT jsonb_agg(to_jsonb(cd)) FROM combined_details cd), '[]'::jsonb)
  ) INTO payload;

  RETURN payload;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_announcement_email_recipient(p_announcement_id uuid, p_worker_token uuid, p_lease_seconds integer DEFAULT 45)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_recipient public.announcement_email_recipients%ROWTYPE;
  v_recipient_token UUID := gen_random_uuid();
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.announcement_email_broadcasts
    WHERE announcement_id = p_announcement_id
      AND claim_token = p_worker_token
      AND claim_expires_at > now()
  ) THEN
    RAISE EXCEPTION 'Broadcast claim is stale';
  END IF;

  SELECT * INTO v_recipient
  FROM public.announcement_email_recipients
  WHERE announcement_id = p_announcement_id
    AND status IN ('pending', 'retryable')
    AND next_attempt_at <= now()
  ORDER BY created_at, id
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF NOT FOUND THEN RETURN NULL; END IF;

  UPDATE public.announcement_email_recipients
  SET status = 'sending',
      attempts = attempts + 1,
      claim_token = v_recipient_token,
      claim_expires_at = now() + make_interval(secs => p_lease_seconds),
      first_attempt_at = COALESCE(first_attempt_at, now()),
      updated_at = now()
  WHERE id = v_recipient.id
  RETURNING * INTO v_recipient;

  RETURN jsonb_build_object(
    'id', v_recipient.id,
    'email', v_recipient.email,
    'idempotency_key', v_recipient.idempotency_key,
    'recipient_token', v_recipient.claim_token,
    'delivery_payload', v_recipient.delivery_payload,
    'attempts', v_recipient.attempts
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.prepare_announcement_email_payload(p_announcement_id uuid, p_worker_token uuid, p_recipient_id uuid, p_recipient_token uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_payload JSONB;
BEGIN
  IF jsonb_typeof(p_payload) <> 'object' THEN RAISE EXCEPTION 'Invalid email payload'; END IF;
  UPDATE public.announcement_email_recipients r
  SET delivery_payload = COALESCE(r.delivery_payload, p_payload), updated_at = now()
  FROM public.announcement_email_broadcasts b
  WHERE r.id = p_recipient_id
    AND r.announcement_id = p_announcement_id
    AND r.status = 'sending'
    AND r.claim_token = p_recipient_token
    AND r.claim_expires_at > now()
    AND b.announcement_id = r.announcement_id
    AND b.claim_token = p_worker_token
    AND b.claim_expires_at > now()
  RETURNING r.delivery_payload INTO v_payload;
  IF NOT FOUND THEN RAISE EXCEPTION 'Recipient claim is stale'; END IF;
  RETURN v_payload;
END;
$function$;
CREATE OR REPLACE FUNCTION public.claim_announcement_email_broadcast(p_announcement_id uuid, p_from_email text, p_worker_token uuid, p_lease_seconds integer DEFAULT 120)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_announcement public.announcements%ROWTYPE;
  v_job public.announcement_email_broadcasts%ROWTYPE;
  v_created BOOLEAN := false;
BEGIN
  IF p_worker_token IS NULL OR p_lease_seconds < 30 OR p_lease_seconds > 600 THEN
    RAISE EXCEPTION 'Invalid broadcast lease';
  END IF;
  IF btrim(COALESCE(p_from_email, '')) = '' OR char_length(p_from_email) > 320 THEN
    RAISE EXCEPTION 'Invalid sender address';
  END IF;

  SELECT * INTO v_announcement
  FROM public.announcements
  WHERE id = p_announcement_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Announcement not found'; END IF;
  IF v_announcement.send_email IS NOT TRUE THEN
    RAISE EXCEPTION 'Announcement is not marked for email';
  END IF;

  SELECT * INTO v_job
  FROM public.announcement_email_broadcasts
  WHERE announcement_id = p_announcement_id
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.announcement_email_broadcasts
      (announcement_id, subject, content, from_email, status, cta_label, cta_url)
    VALUES
      (p_announcement_id, v_announcement.title, v_announcement.content, p_from_email, 'pending',
       v_announcement.cta_label, v_announcement.cta_url)
    RETURNING * INTO v_job;
    v_created := true;

    INSERT INTO public.announcement_email_recipients (announcement_id, email)
    SELECT p_announcement_id, email
    FROM public.email_subscriptions
    WHERE subscribed IS TRUE
    ON CONFLICT (announcement_id, email) DO NOTHING;

    UPDATE public.announcement_email_broadcasts
    SET total_recipients = (
      SELECT count(*) FROM public.announcement_email_recipients
      WHERE announcement_id = p_announcement_id
    )
    WHERE announcement_id = p_announcement_id
    RETURNING * INTO v_job;
  END IF;

  IF v_announcement.emailed_at IS NOT NULL OR v_job.status = 'completed' THEN
    RETURN jsonb_build_object('state', 'completed', 'already_completed', true);
  END IF;

  IF v_job.claim_expires_at > now() AND v_job.claim_token IS DISTINCT FROM p_worker_token THEN
    RETURN jsonb_build_object('state', 'busy', 'retry_after', v_job.claim_expires_at);
  END IF;

  -- An expired send is uncertain. Reuse the same provider idempotency key only
  -- while Resend still retains it; older uncertain sends require review.
  UPDATE public.announcement_email_recipients
  SET status = CASE
        WHEN first_attempt_at <= now() - interval '23 hours' THEN 'needs_review'
        ELSE 'retryable'
      END,
      claim_token = NULL,
      claim_expires_at = NULL,
      next_attempt_at = now(),
      last_error = COALESCE(last_error, 'Recovered an expired sending claim'),
      updated_at = now()
  WHERE announcement_id = p_announcement_id
    AND status = 'sending'
    AND claim_expires_at <= now();

  UPDATE public.announcement_email_recipients
  SET status = 'needs_review',
      last_error = COALESCE(last_error, 'Provider idempotency retention window elapsed'),
      updated_at = now()
  WHERE announcement_id = p_announcement_id
    AND status = 'retryable'
    AND first_attempt_at <= now() - interval '23 hours';

  UPDATE public.announcement_email_broadcasts
  SET status = 'processing',
      claim_token = p_worker_token,
      claim_expires_at = now() + make_interval(secs => p_lease_seconds),
      updated_at = now()
  WHERE announcement_id = p_announcement_id
  RETURNING * INTO v_job;

  RETURN jsonb_build_object(
    'state', 'claimed',
    'created', v_created,
    'subject', v_job.subject,
    'content', v_job.content,
    'from_email', v_job.from_email,
    'cta_label', v_job.cta_label,
    'cta_url', v_job.cta_url,
    'total', v_job.total_recipients
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_announcement_email_outcome(p_announcement_id uuid, p_worker_token uuid, p_recipient_id uuid, p_recipient_token uuid, p_outcome text, p_provider_message_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 60)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF p_outcome NOT IN ('accepted', 'skipped', 'retryable', 'permanent_failed', 'needs_review') THEN
    RAISE EXCEPTION 'Invalid recipient outcome';
  END IF;
  UPDATE public.announcement_email_recipients r
  SET status = p_outcome,
      provider_message_id = CASE WHEN p_outcome = 'accepted' THEN p_provider_message_id ELSE r.provider_message_id END,
      accepted_at = CASE WHEN p_outcome = 'accepted' THEN now() ELSE r.accepted_at END,
      last_error = left(p_error, 1000),
      next_attempt_at = CASE WHEN p_outcome = 'retryable'
        THEN now() + make_interval(secs => greatest(15, least(p_retry_after_seconds, 3600)))
        ELSE r.next_attempt_at END,
      claim_token = NULL,
      claim_expires_at = NULL,
      updated_at = now()
  FROM public.announcement_email_broadcasts b
  WHERE r.id = p_recipient_id
    AND r.announcement_id = p_announcement_id
    AND r.status = 'sending'
    AND r.claim_token = p_recipient_token
    AND b.announcement_id = r.announcement_id
    AND b.claim_token = p_worker_token
    AND b.claim_expires_at > now();
  IF NOT FOUND THEN RAISE EXCEPTION 'Recipient claim is stale'; END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.finish_announcement_email_broadcast(p_announcement_id uuid, p_worker_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_total INTEGER;
  v_accepted INTEGER;
  v_skipped INTEGER;
  v_retryable INTEGER;
  v_failed INTEGER;
  v_review INTEGER;
  v_outstanding INTEGER;
  v_status TEXT;
BEGIN
  PERFORM 1 FROM public.announcement_email_broadcasts
  WHERE announcement_id = p_announcement_id
    AND claim_token = p_worker_token
    AND claim_expires_at > now()
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Broadcast claim is stale'; END IF;

  SELECT count(*),
         count(*) FILTER (WHERE status = 'accepted'),
         count(*) FILTER (WHERE status = 'skipped'),
         count(*) FILTER (WHERE status = 'retryable'),
         count(*) FILTER (WHERE status = 'permanent_failed'),
         count(*) FILTER (WHERE status = 'needs_review'),
         count(*) FILTER (WHERE status IN ('pending', 'sending', 'retryable'))
  INTO v_total, v_accepted, v_skipped, v_retryable, v_failed, v_review, v_outstanding
  FROM public.announcement_email_recipients
  WHERE announcement_id = p_announcement_id;

  v_status := CASE
    WHEN v_outstanding = 0 AND v_failed = 0 AND v_review = 0 THEN 'completed'
    WHEN v_outstanding = 0 AND v_review > 0 THEN 'needs_review'
    WHEN v_outstanding = 0 AND v_failed > 0 THEN 'failed'
    ELSE 'partial'
  END;

  IF v_status = 'completed' THEN
    UPDATE public.announcements
    SET emailed_at = COALESCE(emailed_at, now())
    WHERE id = p_announcement_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Announcement completion write failed'; END IF;
  END IF;

  UPDATE public.announcement_email_broadcasts
  SET status = v_status,
      claim_token = NULL,
      claim_expires_at = NULL,
      total_recipients = v_total,
      accepted_count = v_accepted,
      skipped_count = v_skipped,
      retryable_count = v_retryable,
      failed_count = v_failed,
      needs_review_count = v_review,
      completed_at = CASE WHEN v_status = 'completed' THEN now() ELSE NULL END,
      updated_at = now()
  WHERE announcement_id = p_announcement_id;

  RETURN jsonb_build_object(
    'state', v_status,
    'total', v_total,
    'accepted', v_accepted,
    'skipped', v_skipped,
    'retryable', v_retryable,
    'failed', v_failed,
    'needs_review', v_review
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_manual_refund_reauth_attempt(p_admin_id uuid, p_success boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_max_attempts CONSTANT INTEGER := 5;
  v_lockout_minutes CONSTANT INTEGER := 15;
  v_row private.manual_refund_reauth_attempts%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  IF p_admin_id IS NULL THEN
    RAISE EXCEPTION 'Admin id is required' USING ERRCODE = '22023';
  END IF;

  IF p_success THEN
    INSERT INTO private.manual_refund_reauth_attempts (admin_id, failed_count, first_failed_at, locked_until, updated_at)
    VALUES (p_admin_id, 0, NULL, NULL, NOW())
    ON CONFLICT (admin_id) DO UPDATE
    SET failed_count = 0, first_failed_at = NULL, locked_until = NULL, updated_at = NOW();
    RETURN jsonb_build_object('locked', FALSE, 'locked_until', NULL, 'failed_count', 0);
  END IF;

  INSERT INTO private.manual_refund_reauth_attempts (admin_id, failed_count, first_failed_at, updated_at)
  VALUES (p_admin_id, 1, NOW(), NOW())
  ON CONFLICT (admin_id) DO UPDATE
  SET failed_count = CASE
        WHEN private.manual_refund_reauth_attempts.locked_until IS NOT NULL
             AND private.manual_refund_reauth_attempts.locked_until <= NOW()
          THEN 1
        ELSE private.manual_refund_reauth_attempts.failed_count + 1
      END,
      first_failed_at = CASE
        WHEN private.manual_refund_reauth_attempts.locked_until IS NOT NULL
             AND private.manual_refund_reauth_attempts.locked_until <= NOW()
          THEN NOW()
        ELSE COALESCE(private.manual_refund_reauth_attempts.first_failed_at, NOW())
      END,
      updated_at = NOW()
  RETURNING * INTO v_row;

  IF v_row.failed_count >= v_max_attempts THEN
    UPDATE private.manual_refund_reauth_attempts
    SET locked_until = NOW() + (v_lockout_minutes || ' minutes')::interval
    WHERE admin_id = p_admin_id
    RETURNING * INTO v_row;
  END IF;

  RETURN jsonb_build_object(
    'locked', v_row.locked_until IS NOT NULL AND v_row.locked_until > NOW(),
    'locked_until', v_row.locked_until,
    'failed_count', v_row.failed_count
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_manual_refund_without_settlement_guard(p_payment_transaction_id uuid, p_amount numeric, p_reason text, p_notes text, p_return_method text, p_return_reference text, p_returned_at timestamp with time zone, p_idempotency_key uuid, p_admin_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_payment public.payment_transactions%ROWTYPE;
  v_existing public.payment_refunds%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_reserved NUMERIC(10,2);
  v_amount NUMERIC(10,2);
  v_reason TEXT;
  v_return_method TEXT;
  v_notes TEXT;
  v_return_reference TEXT;
  v_returned_at TIMESTAMPTZ;
  v_admin_name TEXT;
BEGIN
  -- Reachable only via service_role (see GRANT below) — i.e. only the
  -- record-manual-refund Edge Function, after it has verified the caller's
  -- password against Supabase Auth. p_admin_id is that verified identity,
  -- never a browser-supplied value the browser could set to someone else.
  -- Rechecked against profiles regardless, so this function alone can never
  -- attribute a refund to an id that isn't actually an admin right now.
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  IF p_payment_transaction_id IS NULL OR p_idempotency_key IS NULL OR p_admin_id IS NULL THEN
    RAISE EXCEPTION 'Payment, idempotency key, and verified admin are required'
      USING ERRCODE = '22023';
  END IF;

  SELECT p.name INTO v_admin_name
  FROM public.profiles p
  WHERE p.id = p_admin_id AND p.role = 'admin';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  v_amount := ROUND(COALESCE(p_amount, 0), 2);
  v_reason := LOWER(BTRIM(COALESCE(p_reason, '')));
  v_return_method := LOWER(BTRIM(COALESCE(p_return_method, '')));
  v_notes := NULLIF(BTRIM(p_notes), '');
  v_return_reference := NULLIF(BTRIM(p_return_reference), '');
  v_returned_at := COALESCE(p_returned_at, NOW());

  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'Refund amount must be greater than zero' USING ERRCODE = '22023';
  END IF;
  IF v_reason NOT IN ('duplicate', 'fraudulent', 'requested_by_customer', 'others') THEN
    RAISE EXCEPTION 'Invalid refund reason' USING ERRCODE = '22023';
  END IF;
  IF v_return_method NOT IN ('cash', 'gcash') THEN
    RAISE EXCEPTION 'Return method must be cash or gcash' USING ERRCODE = '22023';
  END IF;
  IF v_return_method = 'gcash' AND (v_return_reference IS NULL OR char_length(v_return_reference) < 4) THEN
    RAISE EXCEPTION 'A GCash transfer reference is required to record a manual GCash return'
      USING ERRCODE = '22023';
  END IF;
  -- Format checks beyond "present and 4+ characters" — mirrors
  -- src/utils/gcashReference.js on the client and the equivalent checks in
  -- the record-manual-refund Edge Function, so all three layers agree.
  IF v_return_method = 'gcash' AND v_return_reference ~ '@' THEN
    RAISE EXCEPTION 'That looks like an email address, not a GCash transfer reference'
      USING ERRCODE = '22023';
  END IF;
  -- Checked in two steps: first that the value is phone-SHAPED at all (only
  -- digits and common phone punctuation) before stripping anything.
  -- Stripping non-digits from an alphanumeric value first — e.g. a PayMongo
  -- id like "pay_9f8a7b6c5d4e3f2a1b0c" — can coincidentally leave a
  -- 10-digit string starting with 9, which would misread as a phone number
  -- even though the original value plainly wasn't one.
  IF v_return_method = 'gcash'
     AND v_return_reference ~ '^[0-9[:space:]()+-]+$'
     AND regexp_replace(v_return_reference, '[^0-9]', '', 'g') ~ '^(63|0)?9[0-9]{9}$'
     AND char_length(regexp_replace(v_return_reference, '[^0-9]', '', 'g')) <= 12 THEN
    RAISE EXCEPTION 'That looks like a phone number, not a GCash transfer reference'
      USING ERRCODE = '22023';
  END IF;
  IF v_return_method = 'gcash' AND v_return_reference ~* '^(pay|ref|src|link|paym|pi|re|sub|cus|evt)_[A-Za-z0-9_-]+$' THEN
    RAISE EXCEPTION 'That looks like an internal payment system ID, not a GCash transfer reference'
      USING ERRCODE = '22023';
  END IF;
  IF v_return_method = 'gcash' AND v_return_reference !~ '[0-9]{4,}' THEN
    RAISE EXCEPTION 'Enter the reference number from the completed GCash transfer receipt'
      USING ERRCODE = '22023';
  END IF;
  IF v_return_method = 'cash' AND (v_notes IS NULL OR char_length(v_notes) < 5) THEN
    RAISE EXCEPTION 'A short acknowledgement note is required to record a manual cash return'
      USING ERRCODE = '22023';
  END IF;
  IF v_notes IS NOT NULL AND char_length(v_notes) > 255 THEN
    RAISE EXCEPTION 'Notes must be 255 characters or fewer' USING ERRCODE = '22023';
  END IF;
  IF v_returned_at > NOW() + INTERVAL '5 minutes' THEN
    RAISE EXCEPTION 'The return time cannot be in the future' USING ERRCODE = '22023';
  END IF;

  -- Idempotent retry (double-click / network retry from the Edge Function):
  -- the identical key must describe the identical request, never a second
  -- logical refund.
  SELECT * INTO v_existing
  FROM public.payment_refunds
  WHERE idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_existing.payment_transaction_id <> p_payment_transaction_id
       OR v_existing.amount <> v_amount
       OR v_existing.reason <> v_reason
       OR v_existing.refund_channel <> 'manual' THEN
      RAISE EXCEPTION 'Idempotency key was already used for a different refund request'
        USING ERRCODE = '23505';
    END IF;
    RETURN to_jsonb(v_existing) || jsonb_build_object('created', FALSE);
  END IF;

  -- Locking the original payment row serializes two admins recording a
  -- manual refund (or one admin double-submitting from two tabs) for the
  -- same transaction at the same time — same technique as
  -- prepare_paymongo_refund.
  SELECT * INTO v_payment
  FROM public.payment_transactions
  WHERE id = p_payment_transaction_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Original payment was not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_payment.payment_status NOT IN ('paid', 'partial') THEN
    RAISE EXCEPTION 'Only a paid or partially paid transaction can be refunded' USING ERRCODE = '22023';
  END IF;
  -- A verified PayMongo GCash payment has its own reconcilable provider
  -- record and must go through prepare_paymongo_refund/paymongo-refund
  -- instead, so it stays checkable against PayMongo's own ledger. This RPC
  -- exists only for the payments PayMongo has no record of at all.
  IF v_payment.payment_method = 'gcash' AND v_payment.gcash_channel = 'paymongo' THEN
    RAISE EXCEPTION 'This payment was made through PayMongo. Use the provider refund instead of a manual refund.'
      USING ERRCODE = '22023';
  END IF;
  -- Only meaningful once v_payment is loaded: the reference of the NEW
  -- outgoing refund transfer must not just be the original payment's own
  -- reference copied back in (a plausible mistake, not a malicious one, but
  -- it would record something that never actually happened as evidence).
  IF v_return_method = 'gcash'
     AND v_payment.transaction_reference IS NOT NULL
     AND LOWER(v_return_reference) = LOWER(BTRIM(v_payment.transaction_reference)) THEN
    RAISE EXCEPTION 'That matches the original payment''s own reference. Enter the reference of the NEW outgoing refund transfer.'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(pr.amount), 0) INTO v_reserved
  FROM public.payment_refunds pr
  WHERE pr.payment_transaction_id = v_payment.id
    AND pr.status IN ('creating', 'pending', 'processing', 'succeeded');

  IF v_amount > v_payment.amount - v_reserved + 0.005 THEN
    RAISE EXCEPTION 'Refund exceeds the remaining refundable amount of %',
      GREATEST(v_payment.amount - v_reserved, 0)
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.payment_refunds (
    idempotency_key, payment_transaction_id, order_id, payment_id, refund_id,
    amount, currency, status, reason, notes, initiated_by, initiated_by_name,
    refund_channel, return_method, return_reference, returned_at, succeeded_at
  ) VALUES (
    p_idempotency_key, v_payment.id, v_payment.order_id, NULL, NULL,
    v_amount, 'PHP', 'succeeded', v_reason, v_notes, p_admin_id, v_admin_name,
    'manual', v_return_method, v_return_reference, v_returned_at, v_returned_at
  )
  RETURNING * INTO v_existing;

  -- Fires the existing trigger_update_totals_after_refund trigger
  -- (unchanged) via the INSERT above, recomputing amount_paid /
  -- remaining_balance / payment_status the same way a PayMongo refund does.
  -- Also fires the existing notify_refund_succeeded trigger for the
  -- customer notification, and (for a manual refund's parent payment,
  -- which is never gcash_channel='paymongo') wake_paymongo_refund_recovery_for_refund
  -- is a guaranteed no-op — see that function's own refund_channel guard.

  SELECT * INTO v_order FROM public.orders WHERE id = v_payment.order_id;

  -- guard_activity_log_insert() only derives admin_id/admin_name from
  -- auth.uid() when it is non-null; a service-role call has no auth.uid(),
  -- so it passes the row through untouched — these must be set explicitly
  -- here, using the identity this function itself just verified above, not
  -- anything supplied by the Edge Function's request body directly.
  INSERT INTO public.activity_logs (
    admin_id, admin_name, module, action, record_type, record_id, record_ref,
    previous_value, new_value, details
  ) VALUES (
    p_admin_id, v_admin_name, 'Payments', 'Manual Refund Recorded', 'order',
    v_payment.order_id, v_order.tracking_number,
    jsonb_build_object('amount_paid', v_order.amount_paid),
    jsonb_build_object('manual_refund_amount', v_amount, 'return_method', v_return_method),
    format(
      'Recorded a manual %s return of %s against the original %s payment (transaction %s). %s',
      v_return_method,
      to_char(v_amount, 'FM999,999,999,990.00'),
      v_payment.payment_method,
      v_payment.id,
      CASE WHEN v_return_method = 'gcash'
        THEN 'Transfer reference: ' || v_return_reference
        ELSE 'Acknowledgement: ' || v_notes
      END
    )
  );

  RETURN to_jsonb(v_existing) || jsonb_build_object('created', TRUE);
END;
$function$;
CREATE OR REPLACE FUNCTION public.reschedule_trip(p_trip_id uuid, p_departure_date timestamp with time zone, p_arrival_date timestamp with time zone, p_notify_all_subscribers boolean DEFAULT false, p_public_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  RAISE EXCEPTION 'A rescheduling reason is required. Refresh the app and try again.';
END;
$function$;
CREATE OR REPLACE FUNCTION public.mark_paymongo_refund_failed(p_idempotency_key uuid, p_error text, p_public_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_refund public.payment_refunds%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;
  UPDATE public.payment_refunds
  SET status = CASE WHEN status = 'succeeded' THEN status ELSE 'failed' END,
      outcome_uncertain = FALSE,
      last_error = CASE
        WHEN status = 'succeeded' THEN last_error
        ELSE LEFT(COALESCE(NULLIF(BTRIM(p_error), ''), 'Provider rejected the refund'), 1000)
      END,
      public_failure_reason = CASE
        WHEN status = 'succeeded' THEN public_failure_reason
        ELSE LEFT(COALESCE(NULLIF(BTRIM(p_public_error), ''),
          'PayMongo could not complete the refund. No refund amount was deducted from the order’s collected total.'), 500)
      END
  WHERE idempotency_key = p_idempotency_key
    AND refund_channel = 'paymongo'
  RETURNING * INTO v_refund;
  RETURN CASE WHEN FOUND THEN to_jsonb(v_refund) ELSE NULL END;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reconcile_paymongo_refund(p_refund_id text, p_payment_id text, p_amount numeric, p_status text, p_reason text DEFAULT 'others'::text, p_notes text DEFAULT NULL::text, p_livemode boolean DEFAULT NULL::boolean, p_event_id text DEFAULT NULL::text, p_provider_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_provider_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_idempotency_key uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_payment public.payment_transactions%ROWTYPE;
  v_refund public.payment_refunds%ROWTYPE;
  v_amount NUMERIC(10,2);
  v_status TEXT;
  v_reason TEXT;
  v_other_succeeded NUMERIC(10,2);
BEGIN
  v_amount := ROUND(COALESCE(p_amount, 0), 2);
  v_status := LOWER(BTRIM(COALESCE(p_status, '')));
  v_reason := LOWER(BTRIM(COALESCE(p_reason, 'others')));

  IF p_refund_id IS NULL OR p_refund_id !~ '^ref_[A-Za-z0-9_-]{4,128}$'
     OR p_payment_id IS NULL OR p_payment_id !~ '^pay_[A-Za-z0-9_-]{4,128}$'
     OR v_amount <= 0
     OR v_status NOT IN ('pending', 'processing', 'succeeded', 'failed') THEN
    RAISE EXCEPTION 'Invalid PayMongo refund resource' USING ERRCODE = '22023';
  END IF;
  IF v_reason NOT IN ('duplicate', 'fraudulent', 'requested_by_customer', 'others') THEN
    v_reason := 'others';
  END IF;

  SELECT * INTO v_payment
  FROM public.payment_transactions
  WHERE transaction_reference = p_payment_id
    AND payment_method = 'gcash'
    AND gcash_channel = 'paymongo'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'linked', FALSE,
      'refund_id', p_refund_id,
      'message', 'Original PayMongo payment ledger row was not found'
    );
  END IF;

  SELECT * INTO v_refund
  FROM public.payment_refunds
  WHERE refund_id = p_refund_id
  FOR UPDATE;

  IF NOT FOUND AND p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_refund
    FROM public.payment_refunds
    WHERE idempotency_key = p_idempotency_key
    FOR UPDATE;
  END IF;

  -- A signed webhook does not carry our local idempotency key. If the Edge
  -- Function timed out after PayMongo accepted the request, attach that
  -- webhook to the recent unresolved reservation instead of creating an
  -- orphaned second row. refund_channel = 'paymongo' keeps this from ever
  -- being able to match a manual refund row, even hypothetically (a manual
  -- row's parent payment is never gcash_channel='paymongo', so v_payment
  -- above already could not have matched it — this is the explicit,
  -- belt-and-suspenders guard).
  IF NOT FOUND AND p_idempotency_key IS NULL THEN
    SELECT * INTO v_refund
    FROM public.payment_refunds
    WHERE payment_transaction_id = v_payment.id
      AND refund_channel = 'paymongo'
      AND refund_id IS NULL
      AND amount = v_amount
      AND reason = v_reason
      AND status IN ('creating', 'processing')
      AND created_at >= NOW() - INTERVAL '24 hours'
    ORDER BY created_at
    LIMIT 1
    FOR UPDATE;
  END IF;

  IF FOUND THEN
    IF v_refund.payment_transaction_id <> v_payment.id OR v_refund.amount <> v_amount THEN
      RAISE EXCEPTION 'Refund identity conflicts with its original payment'
        USING ERRCODE = '23505';
    END IF;

    -- A completed refund is terminal. Ignore older or lower-state deliveries.
    IF v_refund.status = 'succeeded' AND v_status <> 'succeeded' THEN
      RETURN to_jsonb(v_refund) || jsonb_build_object('linked', TRUE, 'changed', FALSE);
    END IF;
    IF v_refund.provider_updated_at IS NOT NULL
       AND p_provider_updated_at IS NOT NULL
       AND p_provider_updated_at < v_refund.provider_updated_at THEN
      RETURN to_jsonb(v_refund) || jsonb_build_object('linked', TRUE, 'changed', FALSE);
    END IF;
  END IF;

  IF v_status = 'succeeded' THEN
    SELECT COALESCE(SUM(pr.amount), 0) INTO v_other_succeeded
    FROM public.payment_refunds pr
    WHERE pr.payment_transaction_id = v_payment.id
      AND pr.status = 'succeeded'
      AND (v_refund.id IS NULL OR pr.id <> v_refund.id);

    IF v_other_succeeded + v_amount > v_payment.amount + 0.005 THEN
      RAISE EXCEPTION 'Successful refunds exceed the original payment amount'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_refund.id IS NULL THEN
    INSERT INTO public.payment_refunds (
      refund_id, idempotency_key, payment_transaction_id, order_id, payment_id,
      amount, status, reason, notes, livemode, last_event_id,
      provider_created_at, provider_updated_at, succeeded_at, refund_channel
    ) VALUES (
      p_refund_id, p_idempotency_key, v_payment.id, v_payment.order_id, p_payment_id,
      v_amount, v_status, v_reason, NULLIF(BTRIM(p_notes), ''), p_livemode, p_event_id,
      p_provider_created_at, p_provider_updated_at,
      CASE WHEN v_status = 'succeeded' THEN COALESCE(p_provider_updated_at, NOW()) ELSE NULL END,
      'paymongo'
    ) RETURNING * INTO v_refund;
  ELSE
    UPDATE public.payment_refunds
    SET refund_id = COALESCE(refund_id, p_refund_id),
        payment_id = p_payment_id,
        status = v_status,
        reason = v_reason,
        notes = COALESCE(NULLIF(BTRIM(p_notes), ''), notes),
        livemode = COALESCE(p_livemode, livemode),
        last_event_id = COALESCE(p_event_id, last_event_id),
        last_error = CASE WHEN v_status = 'failed' THEN last_error ELSE NULL END,
        provider_created_at = COALESCE(p_provider_created_at, provider_created_at),
        provider_updated_at = COALESCE(p_provider_updated_at, provider_updated_at),
        succeeded_at = CASE
          WHEN v_status = 'succeeded' THEN COALESCE(succeeded_at, p_provider_updated_at, NOW())
          ELSE succeeded_at
        END
    WHERE id = v_refund.id
      AND refund_channel = 'paymongo'
    RETURNING * INTO v_refund;
  END IF;

  RETURN to_jsonb(v_refund) || jsonb_build_object('linked', TRUE, 'changed', TRUE);
END;
$function$;
CREATE OR REPLACE FUNCTION public.assert_cancellation_refund_capacity(p_order_id uuid, p_new_refund_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_fee NUMERIC(10,2);
  v_gross NUMERIC(10,2);
  v_succeeded NUMERIC(10,2);
  v_pending NUMERIC(10,2);
  v_amount NUMERIC(10,2) := ROUND(COALESCE(p_new_refund_amount, 0), 2);
BEGIN
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'Refund amount must be greater than zero' USING ERRCODE = '22023';
  END IF;

  SELECT agreed_retained_amount INTO v_fee
  FROM public.cancellation_settlements
  WHERE order_id = p_order_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_gross
  FROM public.payment_transactions
  WHERE order_id = p_order_id AND payment_status IN ('paid', 'partial');
  SELECT
    COALESCE(SUM(amount) FILTER (WHERE status = 'succeeded'), 0),
    COALESCE(SUM(amount) FILTER (
      WHERE status IN ('creating', 'pending', 'processing')
         OR (COALESCE(outcome_uncertain, FALSE) AND status NOT IN ('succeeded', 'failed'))
    ), 0)
  INTO v_succeeded, v_pending
  FROM public.payment_refunds WHERE order_id = p_order_id;

  IF v_succeeded > v_gross + 0.005
     OR v_succeeded + v_pending + v_fee > v_gross + 0.005 THEN
    RAISE EXCEPTION 'Cancellation settlement needs reconciliation before another refund'
      USING ERRCODE = '22023';
  END IF;
  IF v_succeeded + v_pending + v_fee + v_amount > v_gross + 0.005 THEN
    RAISE EXCEPTION 'Refund exceeds the amount available after the agreed cancellation fee'
      USING ERRCODE = '22023';
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_sales_overview_data(p_year integer DEFAULT EXTRACT(year FROM (now() AT TIME ZONE 'Asia/Manila'::text)))
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  payload JSONB;
  v_month_start TIMESTAMPTZ;
  v_month_end TIMESTAMPTZ;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin access required';
  END IF;

  v_month_start := date_trunc('month', now() AT TIME ZONE 'Asia/Manila') AT TIME ZONE 'Asia/Manila';
  v_month_end := v_month_start + interval '1 month';

  WITH current_unpaid AS (
    SELECT COALESCE(SUM(GREATEST(GREATEST(shipping_cost - COALESCE(discount_amount, 0), 0) - COALESCE(amount_paid, 0), 0)), 0) as total
    FROM orders
    WHERE status IN ('Picked Up', 'In Transit', 'Arrived at Hub', 'Out for Delivery', 'Delivered')
  ),
  delivered_unpaid AS (
    SELECT COALESCE(SUM(GREATEST(GREATEST(shipping_cost - COALESCE(discount_amount, 0), 0) - COALESCE(amount_paid, 0), 0)), 0) as total
    FROM orders
    WHERE status = 'Delivered'
  ),
  collected_today AS (
    SELECT COALESCE(SUM(amount), 0) as total
    FROM payment_transactions
    WHERE payment_status IN ('paid', 'partial') AND LOWER(TRIM(payment_method)) != 'paylater'
      AND (created_at AT TIME ZONE 'Asia/Manila')::date = (now() AT TIME ZONE 'Asia/Manila')::date
  ),
  refunds_today AS (
    SELECT COALESCE(SUM(amount), 0) as total
    FROM payment_refunds
    WHERE status = 'succeeded'
      AND (COALESCE(succeeded_at, provider_updated_at, updated_at) AT TIME ZONE 'Asia/Manila')::date = (now() AT TIME ZONE 'Asia/Manila')::date
  ),
  collected_month AS (
    SELECT COALESCE(SUM(amount), 0) as total
    FROM payment_transactions
    WHERE payment_status IN ('paid', 'partial') AND LOWER(TRIM(payment_method)) != 'paylater'
      AND created_at >= v_month_start AND created_at < v_month_end
  ),
  refunds_month AS (
    SELECT COALESCE(SUM(amount), 0) as total
    FROM payment_refunds
    WHERE status = 'succeeded'
      AND COALESCE(succeeded_at, provider_updated_at, updated_at) >= v_month_start 
      AND COALESCE(succeeded_at, provider_updated_at, updated_at) < v_month_end
  ),
  monthly_payments AS (
    SELECT EXTRACT(MONTH FROM created_at AT TIME ZONE 'Asia/Manila') as mth, SUM(amount) as gross
    FROM payment_transactions
    WHERE payment_status IN ('paid', 'partial') AND LOWER(TRIM(payment_method)) != 'paylater'
      AND EXTRACT(YEAR FROM created_at AT TIME ZONE 'Asia/Manila') = p_year
    GROUP BY 1
  ),
  monthly_refunds AS (
    SELECT EXTRACT(MONTH FROM COALESCE(succeeded_at, provider_updated_at, updated_at) AT TIME ZONE 'Asia/Manila') as mth, SUM(amount) as refunds
    FROM payment_refunds
    WHERE status = 'succeeded'
      AND EXTRACT(YEAR FROM COALESCE(succeeded_at, provider_updated_at, updated_at) AT TIME ZONE 'Asia/Manila') = p_year
    GROUP BY 1
  ),
  monthly_data AS (
    SELECT m.mth, 
           COALESCE(p.gross, 0) as gross, 
           COALESCE(r.refunds, 0) as refunds,
           COALESCE(p.gross, 0) - COALESCE(r.refunds, 0) as net
    FROM (SELECT generate_series(1, 12) as mth) m
    LEFT JOIN monthly_payments p ON p.mth = m.mth
    LEFT JOIN monthly_refunds r ON r.mth = m.mth
    ORDER BY m.mth
  )
  SELECT jsonb_build_object(
    'collectedToday', (SELECT total FROM collected_today) - (SELECT total FROM refunds_today),
    'netCollectedThisMonth', (SELECT total FROM collected_month) - (SELECT total FROM refunds_month),
    'currentUnpaidBalance', (SELECT total FROM current_unpaid),
    'deliveredButUnpaid', (SELECT total FROM delivered_unpaid),
    'monthlyChart', COALESCE((SELECT jsonb_agg(to_jsonb(md)) FROM monthly_data md), '[]'::jsonb)
  ) INTO payload;

  RETURN payload;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_payment_refund_history(p_order_ids uuid[])
 RETURNS TABLE(id uuid, refund_id text, idempotency_key uuid, payment_transaction_id uuid, order_id uuid, payment_id text, amount numeric, currency text, status text, reason text, notes text, livemode boolean, initiated_by uuid, initiated_by_name text, provider_created_at timestamp with time zone, provider_updated_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, outcome_uncertain boolean, public_failure_reason text, refund_channel text, return_method text, return_reference text, returned_at timestamp with time zone, succeeded_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_is_admin BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;
  IF p_order_ids IS NULL OR cardinality(p_order_ids) = 0 THEN RETURN; END IF;
  IF cardinality(p_order_ids) > 100 THEN
    RAISE EXCEPTION 'At most 100 order ids may be requested' USING ERRCODE = '22023';
  END IF;
  v_is_admin := public.is_admin();

  RETURN QUERY
  SELECT
    pr.id,
    CASE WHEN v_is_admin THEN pr.refund_id ELSE NULL END,
    CASE WHEN v_is_admin THEN pr.idempotency_key ELSE NULL END,
    pr.payment_transaction_id,
    pr.order_id,
    CASE WHEN v_is_admin THEN pr.payment_id ELSE NULL END,
    pr.amount,
    pr.currency,
    pr.status,
    CASE WHEN v_is_admin THEN pr.reason ELSE 'others' END,
    CASE WHEN v_is_admin THEN pr.notes ELSE NULL END,
    CASE WHEN v_is_admin THEN pr.livemode ELSE NULL END,
    CASE WHEN v_is_admin THEN pr.initiated_by ELSE NULL END,
    CASE
      WHEN pr.initiated_by IS NULL THEN 'Payment System'
      ELSE COALESCE(NULLIF(BTRIM(pr.initiated_by_name), ''), 'CargoExpress Staff')
    END,
    pr.provider_created_at,
    pr.provider_updated_at,
    pr.created_at,
    pr.updated_at,
    pr.outcome_uncertain,
    pr.public_failure_reason,
    pr.refund_channel,
    pr.return_method,
    CASE WHEN v_is_admin THEN pr.return_reference ELSE NULL END,
    pr.returned_at,
    pr.succeeded_at
  FROM public.payment_refunds AS pr
  JOIN public.orders AS o ON o.id = pr.order_id
  WHERE pr.order_id = ANY(p_order_ids)
    AND (v_is_admin OR o.user_id = auth.uid())
  ORDER BY pr.created_at, pr.id;
END;
$function$;
CREATE OR REPLACE FUNCTION private.notify_refund_succeeded()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_amount_text TEXT;
  v_balance_text TEXT;
  v_message TEXT;
BEGIN
  IF NEW.status <> 'succeeded'
     OR (TG_OP = 'UPDATE' AND OLD.status = 'succeeded') THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = NEW.order_id;
  IF NOT FOUND OR v_order.user_id IS NULL THEN RETURN NEW; END IF;

  v_amount_text := chr(8369) || to_char(NEW.amount, 'FM999,999,999,990.00');
  v_balance_text := chr(8369) || to_char(
    GREATEST(COALESCE(v_order.remaining_balance, 0), 0),
    'FM999,999,999,990.00'
  );

  v_message := CASE
    WHEN NEW.refund_channel = 'manual' AND NEW.return_method = 'cash' THEN
      format(
        'A %s cash refund for order %s was recorded. The remaining balance for this order is now %s.',
        v_amount_text, v_order.tracking_number, v_balance_text
      )
    WHEN NEW.refund_channel = 'manual' AND NEW.return_method = 'gcash' THEN
      format(
        'A %s GCash refund for order %s was recorded as returned by our team. The remaining balance for this order is now %s.',
        v_amount_text, v_order.tracking_number, v_balance_text
      )
    ELSE
      format(
        'Your %s refund for order %s was successfully processed. The remaining balance for this order is now %s. It may take additional time for the refund to appear in your original GCash account.',
        v_amount_text, v_order.tracking_number, v_balance_text
      )
  END;

  INSERT INTO public.notifications (
    user_id, title, message, type, reference_id, payment_refund_id
  ) VALUES (
    v_order.user_id,
    'Refund Confirmed',
    v_message,
    'payment_update', v_order.id, NEW.id
  ) ON CONFLICT (payment_refund_id) WHERE payment_refund_id IS NOT NULL DO NOTHING;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_cancellation_settlement_summary(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_decision public.cancellation_settlements%ROWTYPE;
  v_is_admin BOOLEAN;
  v_gross NUMERIC(10,2);
  v_succeeded NUMERIC(10,2);
  v_pending NUMERIC(10,2);
  v_net NUMERIC(10,2);
  v_final_charge NUMERIC(10,2);
  v_fee NUMERIC(10,2);
  v_due NUMERIC(10,2);
  v_available NUMERIC(10,2);
  v_invalid BOOLEAN := FALSE;
  v_state TEXT;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found' USING ERRCODE = 'P0002';
  END IF;

  v_is_admin := public.is_admin();
  IF NOT v_is_admin AND v_order.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Not allowed to view this settlement' USING ERRCODE = '42501';
  END IF;
  IF v_order.status <> 'Cancelled' THEN
    RAISE EXCEPTION 'Cancellation settlement is available only for cancelled bookings'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_gross
  FROM public.payment_transactions
  WHERE order_id = p_order_id AND payment_status IN ('paid', 'partial');

  SELECT
    COALESCE(SUM(amount) FILTER (WHERE status = 'succeeded'), 0),
    COALESCE(SUM(amount) FILTER (
      WHERE status IN ('creating', 'pending', 'processing')
         OR (COALESCE(outcome_uncertain, FALSE) AND status NOT IN ('succeeded', 'failed'))
    ), 0)
  INTO v_succeeded, v_pending
  FROM public.payment_refunds
  WHERE order_id = p_order_id;

  SELECT * INTO v_decision
  FROM public.cancellation_settlements
  WHERE order_id = p_order_id;

  v_final_charge := public.order_payable_amount(v_order.shipping_cost, v_order.discount_amount);
  v_net := v_gross - v_succeeded;

  IF FOUND THEN
    v_fee := v_decision.agreed_retained_amount;
    v_due := v_gross - v_succeeded - v_fee;
    v_available := v_gross - v_succeeded - v_pending - v_fee;
    v_invalid := v_gross < 0
      OR v_succeeded < 0
      OR v_pending < 0
      OR v_succeeded > v_gross + 0.005
      OR v_succeeded + v_pending > v_gross + 0.005
      OR v_fee < 0
      OR v_fee > LEAST(v_gross, v_final_charge) + 0.005
      OR v_succeeded + v_pending + v_fee > v_gross + 0.005
      OR v_due < -0.005
      OR v_available < -0.005;

    IF v_invalid THEN
      v_state := 'needs_reconciliation';
    ELSIF v_due > 0.005 AND v_pending > 0.005 THEN
      v_state := 'refund_pending';
    ELSIF v_due > 0.005 THEN
      v_state := 'refund_due';
    ELSE
      v_state := 'refund_settled';
    END IF;
  ELSE
    v_fee := NULL;
    v_due := NULL;
    v_available := NULL;
    v_invalid := v_gross < 0 OR v_succeeded < 0 OR v_pending < 0
      OR v_succeeded > v_gross + 0.005
      OR v_succeeded + v_pending > v_gross + 0.005;
    v_state := CASE WHEN v_invalid THEN 'needs_reconciliation' ELSE 'for_review' END;
  END IF;

  RETURN jsonb_build_object(
    'order_id', v_order.id,
    'booking_status', v_order.status,
    'historical_final_charge', v_final_charge,
    'gross_collected', v_gross,
    'successful_refunds', v_succeeded,
    'net_retained', v_net,
    'refund_in_progress', v_pending,
    'refund_still_due', v_due,
    'refund_not_initiated', v_available,
    'settlement_status', v_state,
    'has_confirmed_decision', v_decision.order_id IS NOT NULL,
    'decision_type', v_decision.decision_type,
    'agreed_cancellation_fee', v_fee,
    'customer_agreement_confirmed', COALESCE(v_decision.customer_agreement_confirmed, FALSE),
    'decided_at', v_decision.decided_at,
    'decided_by', CASE WHEN v_is_admin THEN v_decision.decided_by ELSE NULL END,
    'internal_notes', CASE WHEN v_is_admin THEN v_decision.internal_notes ELSE NULL END,
    'version', v_decision.version,
    'invariants_valid', NOT v_invalid
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.prepare_paymongo_refund(p_payment_transaction_id uuid, p_amount numeric, p_reason text, p_notes text, p_idempotency_key uuid, p_initiated_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order_id UUID;
  v_existing public.payment_refunds%ROWTYPE;
BEGIN
  SELECT * INTO v_existing FROM public.payment_refunds
  WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN public.prepare_paymongo_refund_without_settlement_guard(
      p_payment_transaction_id, p_amount, p_reason, p_notes, p_idempotency_key, p_initiated_by
    );
  END IF;

  SELECT order_id INTO v_order_id FROM public.payment_transactions
  WHERE id = p_payment_transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Original payment was not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM 1 FROM public.orders WHERE id = v_order_id FOR UPDATE;

  SELECT * INTO v_existing FROM public.payment_refunds
  WHERE idempotency_key = p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    RETURN public.prepare_paymongo_refund_without_settlement_guard(
      p_payment_transaction_id, p_amount, p_reason, p_notes, p_idempotency_key, p_initiated_by
    );
  END IF;

  PERFORM public.assert_cancellation_refund_capacity(v_order_id, p_amount);
  RETURN public.prepare_paymongo_refund_without_settlement_guard(
    p_payment_transaction_id, p_amount, p_reason, p_notes, p_idempotency_key, p_initiated_by
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.record_manual_refund(p_payment_transaction_id uuid, p_amount numeric, p_reason text, p_notes text, p_return_method text, p_return_reference text, p_returned_at timestamp with time zone, p_idempotency_key uuid, p_admin_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order_id UUID;
  v_existing public.payment_refunds%ROWTYPE;
BEGIN
  SELECT * INTO v_existing FROM public.payment_refunds
  WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN public.record_manual_refund_without_settlement_guard(
      p_payment_transaction_id, p_amount, p_reason, p_notes, p_return_method,
      p_return_reference, p_returned_at, p_idempotency_key, p_admin_id
    );
  END IF;

  SELECT order_id INTO v_order_id FROM public.payment_transactions
  WHERE id = p_payment_transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Original payment was not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM 1 FROM public.orders WHERE id = v_order_id FOR UPDATE;

  SELECT * INTO v_existing FROM public.payment_refunds
  WHERE idempotency_key = p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    RETURN public.record_manual_refund_without_settlement_guard(
      p_payment_transaction_id, p_amount, p_reason, p_notes, p_return_method,
      p_return_reference, p_returned_at, p_idempotency_key, p_admin_id
    );
  END IF;

  PERFORM public.assert_cancellation_refund_capacity(v_order_id, p_amount);
  RETURN public.record_manual_refund_without_settlement_guard(
    p_payment_transaction_id, p_amount, p_reason, p_notes, p_return_method,
    p_return_reference, p_returned_at, p_idempotency_key, p_admin_id
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_order_sender_receiver_names_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NULLIF(btrim(COALESCE(NEW.sender_first_name, '')), '') IS NULL
     AND NULLIF(btrim(COALESCE(NEW.sender_name, '')), '') IS NOT NULL THEN
    NEW.sender_first_name := split_part(btrim(NEW.sender_name), ' ', 1);
    NEW.sender_last_name  := CASE
      WHEN position(' ' in btrim(NEW.sender_name)) = 0 THEN ''
      ELSE btrim(substring(btrim(NEW.sender_name) from position(' ' in btrim(NEW.sender_name)) + 1))
    END;
  ELSE
    NEW.sender_name := NULLIF(btrim(concat_ws(' ', NEW.sender_first_name, NEW.sender_last_name)), '');
  END IF;

  IF NULLIF(btrim(COALESCE(NEW.receiver_first_name, '')), '') IS NULL
     AND NULLIF(btrim(COALESCE(NEW.receiver_name, '')), '') IS NOT NULL THEN
    NEW.receiver_first_name := split_part(btrim(NEW.receiver_name), ' ', 1);
    NEW.receiver_last_name  := CASE
      WHEN position(' ' in btrim(NEW.receiver_name)) = 0 THEN ''
      ELSE btrim(substring(btrim(NEW.receiver_name) from position(' ' in btrim(NEW.receiver_name)) + 1))
    END;
  ELSE
    NEW.receiver_name := NULLIF(btrim(concat_ws(' ', NEW.receiver_first_name, NEW.receiver_last_name)), '');
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.get_trip_start_date_gates(p_trip_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(trip_id uuid, scheduled_day date, ph_today date, gate_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_today DATE := (clock_timestamp() AT TIME ZONE 'Asia/Manila')::DATE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin privileges required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    t.id,
    (t.departure_date AT TIME ZONE 'Asia/Manila')::DATE,
    v_today,
    CASE
      WHEN t.status <> 'scheduled' THEN 'not_scheduled'
      WHEN t.departure_date IS NULL THEN 'missing_date'
      WHEN (t.departure_date AT TIME ZONE 'Asia/Manila')::DATE > v_today THEN 'before_date'
      WHEN (t.departure_date AT TIME ZONE 'Asia/Manila')::DATE < v_today THEN 'overdue'
      ELSE 'today'
    END
  FROM public.trips AS t
  WHERE p_trip_ids IS NULL OR t.id = ANY(p_trip_ids);
END;
$function$;
CREATE OR REPLACE FUNCTION public.update_order_contact_details(p_order_id uuid, p_sender_first_name text, p_sender_last_name text, p_sender_phone text, p_sender_province text, p_sender_city text, p_sender_barangay text, p_sender_street text, p_sender_landmark text, p_sender_address text, p_receiver_first_name text, p_receiver_last_name text, p_receiver_phone text, p_receiver_province text, p_receiver_city text, p_receiver_barangay text, p_receiver_street text, p_receiver_landmark text, p_receiver_address text)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_is_admin BOOLEAN;
  v_actor TEXT;
  v_previous JSONB;
  v_new JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NULLIF(btrim(p_sender_first_name), '') IS NULL OR NULLIF(btrim(p_sender_last_name), '') IS NULL
     OR NULLIF(btrim(p_sender_phone), '') IS NULL
     OR NULLIF(btrim(p_sender_province), '') IS NULL OR NULLIF(btrim(p_sender_city), '') IS NULL
     OR NULLIF(btrim(p_sender_barangay), '') IS NULL OR NULLIF(btrim(p_sender_street), '') IS NULL
     OR NULLIF(btrim(p_sender_landmark), '') IS NULL
     OR NULLIF(btrim(p_receiver_first_name), '') IS NULL OR NULLIF(btrim(p_receiver_last_name), '') IS NULL
     OR NULLIF(btrim(p_receiver_phone), '') IS NULL
     OR NULLIF(btrim(p_receiver_province), '') IS NULL OR NULLIF(btrim(p_receiver_city), '') IS NULL
     OR NULLIF(btrim(p_receiver_barangay), '') IS NULL OR NULLIF(btrim(p_receiver_street), '') IS NULL
     OR NULLIF(btrim(p_receiver_landmark), '') IS NULL THEN
    RAISE EXCEPTION 'First name, last name, phone, province, city, barangay, street and landmark are all required for both sender and receiver.';
  END IF;

  v_is_admin := public.is_admin();

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found';
  END IF;

  -- Customers: locked at Out for Delivery, Delivered, and Cancelled.
  -- Admins: locked at Out for Delivery and Delivered only.
  -- (Admins retain access to Cancelled bookings for archival/dispute corrections.)
  IF NOT v_is_admin THEN
    IF v_order.status IN ('Out for Delivery', 'Delivered', 'Cancelled') THEN
      RAISE EXCEPTION 'Customer details are locked once the booking is out for delivery. (current status: %)', v_order.status;
    END IF;
    IF v_order.user_id <> auth.uid() THEN
      RAISE EXCEPTION 'Only your own bookings can be edited';
    END IF;
  ELSE
    -- Admin is also locked at the final delivery stages
    IF v_order.status IN ('Out for Delivery', 'Delivered') THEN
      RAISE EXCEPTION 'Customer details are locked once the booking is out for delivery. (current status: %)', v_order.status;
    END IF;
  END IF;

  v_previous := jsonb_build_object(
    'sender_first_name', v_order.sender_first_name, 'sender_last_name', v_order.sender_last_name,
    'sender_phone', v_order.sender_phone,
    'sender_province', v_order.sender_province, 'sender_city', v_order.sender_city,
    'sender_barangay', v_order.sender_barangay, 'sender_street', v_order.sender_street,
    'sender_landmark', v_order.sender_landmark, 'sender_address', v_order.sender_address,
    'receiver_first_name', v_order.receiver_first_name, 'receiver_last_name', v_order.receiver_last_name,
    'receiver_phone', v_order.receiver_phone,
    'receiver_province', v_order.receiver_province, 'receiver_city', v_order.receiver_city,
    'receiver_barangay', v_order.receiver_barangay, 'receiver_street', v_order.receiver_street,
    'receiver_landmark', v_order.receiver_landmark, 'receiver_address', v_order.receiver_address
  );
  v_new := jsonb_build_object(
    'sender_first_name', btrim(p_sender_first_name), 'sender_last_name', btrim(p_sender_last_name),
    'sender_phone', btrim(p_sender_phone),
    'sender_province', btrim(p_sender_province), 'sender_city', btrim(p_sender_city),
    'sender_barangay', btrim(p_sender_barangay), 'sender_street', btrim(p_sender_street),
    'sender_landmark', btrim(p_sender_landmark), 'sender_address', btrim(p_sender_address),
    'receiver_first_name', btrim(p_receiver_first_name), 'receiver_last_name', btrim(p_receiver_last_name),
    'receiver_phone', btrim(p_receiver_phone),
    'receiver_province', btrim(p_receiver_province), 'receiver_city', btrim(p_receiver_city),
    'receiver_barangay', btrim(p_receiver_barangay), 'receiver_street', btrim(p_receiver_street),
    'receiver_landmark', btrim(p_receiver_landmark), 'receiver_address', btrim(p_receiver_address)
  );

  -- Nothing actually changed — return the row as-is with no write, no log.
  IF v_previous = v_new THEN
    RETURN v_order;
  END IF;

  -- sender_name/receiver_name are deliberately NOT set here — guard_order_update()
  -- derives them from the first/last pair on this same UPDATE (BEFORE trigger).
  UPDATE public.orders SET
    sender_first_name = btrim(p_sender_first_name),
    sender_last_name = btrim(p_sender_last_name),
    sender_phone = btrim(p_sender_phone),
    sender_province = btrim(p_sender_province),
    sender_city = btrim(p_sender_city),
    sender_barangay = btrim(p_sender_barangay),
    sender_street = btrim(p_sender_street),
    sender_landmark = btrim(p_sender_landmark),
    sender_address = btrim(p_sender_address),
    receiver_first_name = btrim(p_receiver_first_name),
    receiver_last_name = btrim(p_receiver_last_name),
    receiver_phone = btrim(p_receiver_phone),
    receiver_province = btrim(p_receiver_province),
    receiver_city = btrim(p_receiver_city),
    receiver_barangay = btrim(p_receiver_barangay),
    receiver_street = btrim(p_receiver_street),
    receiver_landmark = btrim(p_receiver_landmark),
    receiver_address = btrim(p_receiver_address)
  WHERE id = p_order_id
  RETURNING * INTO v_order;

  v_actor := CASE WHEN v_is_admin THEN 'Admin' ELSE 'Customer' END;

  INSERT INTO public.activity_logs (
    module, action, record_type, record_id, record_ref,
    previous_value, new_value, details
  ) VALUES (
    'Orders',
    v_actor || ' Updated Sender/Receiver Details',
    'order',
    v_order.id,
    v_order.tracking_number,
    v_previous,
    v_new,
    format('%s updated sender/receiver contact and address details.', v_actor)
  );

  RETURN v_order;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_trip_reschedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_today DATE;
  v_new_day DATE;
BEGIN
  IF NEW.departure_date IS NOT DISTINCT FROM OLD.departure_date
     AND NEW.arrival_date IS NOT DISTINCT FROM OLD.arrival_date THEN
    RETURN NEW;
  END IF;

  IF current_setting('cargoexpress.trip_reschedule_authorized', true) IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'Use the authorized trip reschedule action so the reason and schedule history are recorded.';
  END IF;
  IF NEW.departure_date IS NULL THEN
    RAISE EXCEPTION 'A departure date is required when rescheduling a trip.';
  END IF;
  IF OLD.status <> 'scheduled' OR OLD.departure_at IS NOT NULL THEN
    RAISE EXCEPTION 'Only a trip that has not started can be rescheduled.';
  END IF;

  v_today := (clock_timestamp() AT TIME ZONE 'Asia/Manila')::DATE;
  v_new_day := (NEW.departure_date AT TIME ZONE 'Asia/Manila')::DATE;
  IF v_new_day < v_today THEN
    RAISE EXCEPTION 'A trip cannot be rescheduled to a past Manila date.';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.reschedule_trip(p_trip_id uuid, p_departure_date timestamp with time zone, p_arrival_date timestamp with time zone, p_notify_all_subscribers boolean, p_public_reason text, p_change_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_before public.trips%ROWTYPE;
  v_after public.trips%ROWTYPE;
  v_changed BOOLEAN;
  v_reason TEXT := NULLIF(btrim(COALESCE(p_change_reason, '')), '');
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Admin privileges required' USING ERRCODE = '42501';
  END IF;
  IF v_reason IS NULL OR char_length(v_reason) < 5 OR char_length(v_reason) > 500 THEN
    RAISE EXCEPTION 'Enter a rescheduling reason between 5 and 500 characters.';
  END IF;

  SELECT * INTO v_before FROM public.trips WHERE id = p_trip_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Trip not found'; END IF;

  PERFORM set_config('cargoexpress.trip_reschedule_notify_all',
    CASE WHEN p_notify_all_subscribers THEN 'true' ELSE 'false' END, true);
  PERFORM set_config('cargoexpress.trip_reschedule_authorized', 'true', true);

  UPDATE public.trips
  SET departure_date = p_departure_date,
      arrival_date = p_arrival_date
  WHERE id = p_trip_id
  RETURNING * INTO v_after;

  v_changed := (v_before.departure_date IS DISTINCT FROM v_after.departure_date)
            OR (v_before.arrival_date IS DISTINCT FROM v_after.arrival_date);

  IF v_changed THEN
    INSERT INTO public.activity_logs (
      module, action, record_type, record_id, record_ref,
      previous_value, new_value, details
    ) VALUES (
      'Trips', 'Trip Rescheduled', 'trip', v_after.id, v_after.trip_number,
      jsonb_build_object('departure_date', v_before.departure_date, 'arrival_date', v_before.arrival_date),
      jsonb_build_object('departure_date', v_after.departure_date, 'arrival_date', v_after.arrival_date),
      format(
        'Departure date: %s → %s; estimated shipment delivery date: %s → %s. Reason: %s',
        COALESCE(to_char(v_before.departure_date AT TIME ZONE 'Asia/Manila', 'Mon FMDD, YYYY'), 'Not set'),
        COALESCE(to_char(v_after.departure_date AT TIME ZONE 'Asia/Manila', 'Mon FMDD, YYYY'), 'Not set'),
        COALESCE(to_char(v_before.arrival_date AT TIME ZONE 'Asia/Manila', 'Mon FMDD, YYYY'), 'Not set'),
        COALESCE(to_char(v_after.arrival_date AT TIME ZONE 'Asia/Manila', 'Mon FMDD, YYYY'), 'Not set'),
        v_reason
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'trip', to_jsonb(v_after),
    'schedule_changed', v_changed,
    'old_departure_date', v_before.departure_date,
    'old_arrival_date', v_before.arrival_date,
    'public_reason', NULLIF(btrim(COALESCE(p_public_reason, '')), ''),
    'change_reason', v_reason
  );
END;
$function$;
CREATE OR REPLACE FUNCTION public.is_valid_person_name(p_name text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN NULLIF(btrim(p_name), '') IS NULL THEN FALSE
    ELSE
      -- every character is a letter, mark, space, period, hyphen or apostrophe
      normalize(btrim(p_name), NFC) ~ ('^[[:alpha:][:space:].' || chr(39) || chr(8217) || '-]+$')
      -- ...and at least one of them is a letter
      AND normalize(btrim(p_name), NFC) ~ '[[:alpha:]]'
      AND char_length(btrim(p_name)) BETWEEN 2 AND 100
  END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_profile_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
      NEW.role := 'customer';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
    NEW.id := OLD.id;
    NEW.email := OLD.email;
    NEW.role := OLD.role;
    NEW.created_at := OLD.created_at;
  END IF;

  -- ── NEW (20260922160000) — name policy, on CHANGE only ─────────────────
  -- A profile whose name predates this policy keeps working: phone, address
  -- and every other self-service edit still saves, because this fires only
  -- when the name column itself is being written to a new value.
  IF TG_OP = 'UPDATE'
     AND NEW.name IS DISTINCT FROM OLD.name
     AND NULLIF(btrim(NEW.name), '') IS NOT NULL
     AND NOT public.is_valid_person_name(NEW.name) THEN
    RAISE EXCEPTION 'Name may only contain letters, spaces, periods, hyphens and apostrophes.'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.track_order_public(p_tracking_number text)
 RETURNS TABLE(tracking_number character varying, status character varying, sender_name text, receiver_name text, origin character varying, destination character varying, package_description text, actual_weight numeric, estimated_delivery timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, trip_departure_date timestamp with time zone, trip_departure_at timestamp with time zone, trip_estimated_arrival_at timestamp with time zone, trip_arrived_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    o.tracking_number,
    o.status,
    public.mask_name(o.sender_name)   AS sender_name,
    public.mask_name(o.receiver_name) AS receiver_name,
    o.origin,
    o.destination,
    CASE
      WHEN length(o.package_description) > 40
        THEN left(o.package_description, 40) || '…'
      ELSE o.package_description
    END                               AS package_description,
    o.actual_weight,
    t.arrival_date                    AS estimated_delivery,
    o.created_at,
    o.updated_at,
    t.departure_date                  AS trip_departure_date,
    t.departure_at                    AS trip_departure_at,
    t.estimated_arrival_at            AS trip_estimated_arrival_at,
    t.arrived_at                      AS trip_arrived_at
  FROM public.orders AS o
  LEFT JOIN public.trips AS t ON t.id = o.trip_id
  WHERE o.tracking_number = UPPER(TRIM(p_tracking_number))
  LIMIT 1;
$function$;
