CREATE TRIGGER trips_notify_reschedule_email AFTER UPDATE OF departure_date, arrival_date ON public.trips FOR EACH ROW WHEN ((((new.status)::text = 'scheduled'::text) AND ((new.departure_date IS DISTINCT FROM old.departure_date) OR (new.arrival_date IS DISTINCT FROM old.arrival_date)))) EXECUTE FUNCTION private.trigger_trip_reschedule_email();
CREATE TRIGGER trips_updated_at BEFORE UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trips_validate_status_transition BEFORE UPDATE OF status ON public.trips FOR EACH ROW EXECUTE FUNCTION private.validate_trip_status_transition();
