CREATE POLICY "Allow admin full access" ON public.company_information AS PERMISSIVE FOR ALL TO public USING (is_admin()) WITH CHECK (is_admin());
CREATE POLICY "Admins can insert activity logs" ON public.activity_logs AS PERMISSIVE FOR INSERT TO public WITH CHECK (is_admin());
CREATE POLICY "Anyone can view trips" ON public.trips AS PERMISSIVE FOR SELECT TO public USING (true);
CREATE POLICY "Admins can manage trips" ON public.trips AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role)::text = 'admin'::text)))));
CREATE POLICY "Users can view own orders" ON public.orders AS PERMISSIVE FOR SELECT TO public USING (((user_id = auth.uid()) OR is_admin()));
CREATE POLICY "Admins insert conversations" ON public.conversations AS PERMISSIVE FOR INSERT TO public WITH CHECK ((is_admin() AND (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = conversations.customer_id) AND ((profiles.role)::text = 'customer'::text))))));
CREATE POLICY "Admins can manage announcements" ON public.announcements AS PERMISSIVE FOR ALL TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role)::text = 'admin'::text)))));
CREATE POLICY "Admins view photo storage events" ON public.photo_storage_events AS PERMISSIVE FOR SELECT TO authenticated USING (is_admin());
CREATE POLICY "Admins can update orders" ON public.orders AS PERMISSIVE FOR UPDATE TO public USING (is_admin()) WITH CHECK (is_admin());
CREATE POLICY "Admins can view inquiries" ON public.contact_inquiries AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role)::text = 'admin'::text)))));
CREATE POLICY "Published legal documents are public" ON public.legal_documents AS PERMISSIVE FOR SELECT TO anon, authenticated USING (is_current);
CREATE POLICY "Users can view own legal consents" ON public.legal_consents AS PERMISSIVE FOR SELECT TO authenticated USING ((user_id = auth.uid()));
CREATE POLICY "Admins can view legal consents" ON public.legal_consents AS PERMISSIVE FOR SELECT TO authenticated USING (is_admin());
CREATE POLICY "Admins can delete orders" ON public.orders AS PERMISSIVE FOR DELETE TO public USING (is_admin());
CREATE POLICY "Users can insert their own activity logs" ON public.activity_logs AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((admin_id = auth.uid()));
CREATE POLICY "Customers view own conversations" ON public.conversations AS PERMISSIVE FOR SELECT TO public USING (((customer_id = auth.uid()) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role)::text = 'admin'::text))))));
CREATE POLICY "Customers insert own conversations" ON public.conversations AS PERMISSIVE FOR INSERT TO public WITH CHECK ((customer_id = auth.uid()));
CREATE POLICY "Users view messages in allowed conversations" ON public.chat_messages AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM conversations
  WHERE ((conversations.id = chat_messages.conversation_id) AND ((conversations.customer_id = auth.uid()) OR (EXISTS ( SELECT 1
           FROM profiles
          WHERE ((profiles.id = auth.uid()) AND ((profiles.role)::text = 'admin'::text)))))))));
CREATE POLICY "Customers mark admin messages read" ON public.chat_messages AS PERMISSIVE FOR UPDATE TO authenticated USING ((((sender_role)::text = 'admin'::text) AND (EXISTS ( SELECT 1
   FROM conversations
  WHERE ((conversations.id = chat_messages.conversation_id) AND (conversations.customer_id = auth.uid())))))) WITH CHECK ((((sender_role)::text = 'admin'::text) AND (is_read = true) AND (EXISTS ( SELECT 1
   FROM conversations
  WHERE ((conversations.id = chat_messages.conversation_id) AND (conversations.customer_id = auth.uid()))))));
CREATE POLICY "Admins update messages" ON public.chat_messages AS PERMISSIVE FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND ((profiles.role)::text = 'admin'::text)))));
CREATE POLICY "Users can view own profile" ON public.profiles AS PERMISSIVE FOR SELECT TO public USING ((id = auth.uid()));
CREATE POLICY "Admins can view profiles" ON public.profiles AS PERMISSIVE FOR SELECT TO public USING (is_admin());
CREATE POLICY "Users can update own profile" ON public.profiles AS PERMISSIVE FOR UPDATE TO public USING ((id = auth.uid())) WITH CHECK ((id = auth.uid()));
CREATE POLICY "Admins can update profiles" ON public.profiles AS PERMISSIVE FOR UPDATE TO public USING (is_admin()) WITH CHECK (is_admin());
CREATE POLICY "Users can insert own profile" ON public.profiles AS PERMISSIVE FOR INSERT TO public WITH CHECK ((id = auth.uid()));
