   FROM orders o
  WHERE ((o.id = order_status_events.order_id) AND (o.user_id = auth.uid()))))));
CREATE POLICY "Admins can update contact inquiries" ON public.contact_inquiries AS PERMISSIVE FOR UPDATE TO public USING (is_admin()) WITH CHECK (is_admin());
CREATE POLICY "Users insert messages in allowed conversations" ON public.chat_messages AS PERMISSIVE FOR INSERT TO public WITH CHECK (((sender_id = auth.uid()) AND (EXISTS ( SELECT 1
