CREATE POLICY "Admins can manage payment attempts" ON public.payment_attempts AS PERMISSIVE FOR ALL TO public USING (is_admin()) WITH CHECK (is_admin());
CREATE POLICY "Admins can view activity logs" ON public.activity_logs AS PERMISSIVE FOR SELECT TO public USING (is_admin());
CREATE POLICY "Admins can delete contact inquiries" ON public.contact_inquiries AS PERMISSIVE FOR DELETE TO public USING (is_admin());
CREATE POLICY "Customers can insert own delivered-order feedback" ON public.customer_feedback AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((auth.uid() = customer_id) AND (EXISTS ( SELECT 1
   FROM orders o
  WHERE ((o.id = customer_feedback.order_id) AND (o.user_id = auth.uid()) AND ((o.status)::text = 'Delivered'::text))))));
