CREATE POLICY "Authenticated users can view announcements" ON public.announcements AS PERMISSIVE FOR SELECT TO authenticated USING ((audience = 'public'::text));
CREATE POLICY "Users can create own orders" ON public.orders AS PERMISSIVE FOR INSERT TO public WITH CHECK (((user_id = auth.uid()) AND ((status)::text = ANY ((ARRAY['Pending'::character varying, 'Assigned'::character varying])::text[])) AND (actual_weight IS NULL) AND (payment_method IS NULL) AND ((payment_status)::text = 'unpaid'::text) AND (amount_paid = (0)::numeric) AND (pickup_photos = '[]'::jsonb) AND (delivery_photos = '[]'::jsonb) AND (service_area_status = ANY (ARRAY['standard'::text, 'for_review'::text])) AND (service_area_remarks IS NULL)));
CREATE POLICY "Authorized users can view payment refunds" ON public.payment_refunds AS PERMISSIVE FOR SELECT TO authenticated USING ((( SELECT is_admin() AS is_admin) OR (EXISTS ( SELECT 1
   FROM orders o
  WHERE ((o.id = payment_refunds.order_id) AND (o.user_id = ( SELECT auth.uid() AS uid)))))));
CREATE POLICY "Admins can view email subscriptions" ON public.email_subscriptions AS PERMISSIVE FOR SELECT TO authenticated USING (( SELECT is_admin() AS is_admin));
